// ---- Export data screen (More tab) ----
// The server builds the chosen files (Export.gs); the app only says which files
// and which dates. "Get my files" brings them to the phone, one Save button per
// file (a second tap, because iOS only opens its share sheet straight from a
// tap — not after a wait for the server). "Send to my email" is offered only
// when the backend has an address saved; the address can never come from here.

const EXPORT_PREFS_KEY = "exportPrefs";

function exportEl_(id) { return document.getElementById(id); }

function loadExportPrefs_() {
  try { return JSON.parse(localStorage.getItem(EXPORT_PREFS_KEY) || "{}") || {}; } catch (err) { return {}; }
}

function saveExportPrefs_() {
  try {
    localStorage.setItem(EXPORT_PREFS_KEY, JSON.stringify({
      entries: exportEl_("export-entries-check").checked,
      backup: exportEl_("export-backup-check").checked,
      range: exportEl_("export-range").value,
      pending: exportEl_("export-pending-check").checked
    }));
  } catch (err) { /* private mode etc.: the screen works without it */ }
}

function showExportScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-export"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  const prefs = loadExportPrefs_();
  exportEl_("export-entries-check").checked = !!prefs.entries;
  exportEl_("export-backup-check").checked = !!prefs.backup;
  exportEl_("export-pending-check").checked = !!prefs.pending;
  if (["month", "year", "all", "custom"].includes(prefs.range)) exportEl_("export-range").value = prefs.range;
  exportEl_("export-status").textContent = "";
  exportEl_("export-ready").hidden = true;
  exportEl_("export-ready").textContent = "";
  refreshExportScreen_();
  offerExportTip_();   // nothing to fetch on this screen, so it is complete as soon as it is drawn (loading standard)
}

function refreshExportScreen_() {
  const entries = exportEl_("export-entries-check").checked;
  exportEl_("export-entries-options").hidden = !entries;
  exportEl_("export-custom-fields").hidden = exportEl_("export-range").value !== "custom";
  const any = entries || exportEl_("export-backup-check").checked;
  exportEl_("export-get-btn").disabled = !any;
  // Once the files are ready, their Save buttons are the next thing to tap: "Get my files" steps back (grey, "… again"); the owner
  // found two blue buttons confusing (2026-11-03).
  const got = !exportEl_("export-ready").hidden;
  const getBtn = exportEl_("export-get-btn");
  getBtn.className = got ? "cancel-edit-btn" : "primary";
  getBtn.dataset.i18n = got ? "export.getAgain" : "export.get";
  getBtn.textContent = tr(getBtn.dataset.i18n);
  exportEl_("export-send-btn").hidden = !(meta && meta.capabilities && meta.capabilities.emailExport);
  exportEl_("export-send-btn").disabled = !any;
}

// The dates for the picked range, as YYYY-MM-DD (empty = no limit on that side).
function exportDateRange_() {
  const range = exportEl_("export-range").value;
  const today = todayLocalISO();
  const y = Number(today.slice(0, 4)), m = Number(today.slice(5, 7));
  if (range === "month") {
    const last = new Date(y, m, 0).getDate();
    return { startDate: `${today.slice(0, 7)}-01`, endDate: `${today.slice(0, 7)}-${String(last).padStart(2, "0")}` };
  }
  if (range === "year") return { startDate: `${y}-01-01`, endDate: `${y}-12-31` };
  if (range === "custom") return { startDate: exportEl_("export-start").value, endDate: exportEl_("export-end").value };
  return { startDate: "", endDate: "" };
}

// The files picked on screen, or null (after saying why) when the request is not valid yet.
function exportRequest_() {
  const status = exportEl_("export-status");
  const cards = [];
  if (exportEl_("export-entries-check").checked) cards.push("entries");
  if (exportEl_("export-backup-check").checked) cards.push("backup");
  if (!cards.length) return null;
  const range = exportDateRange_();
  if (cards.includes("entries") && exportEl_("export-range").value === "custom" && !range.startDate && !range.endDate) {
    status.style.color = "#d64545";
    status.textContent = tr("export.pickDates");
    return null;
  }
  return {
    cards, startDate: range.startDate, endDate: range.endDate,
    includePending: exportEl_("export-pending-check").checked
  };
}

function exportFileLabel_(f) {
  return tr(f.kind === "entries" ? "export.fileEntries" : "export.fileRecords", { name: f.name, n: f.rows === 1 ? 1 : f.rows.toLocaleString("en-US") });
}

async function getExportFiles_() {
  const req = exportRequest_();
  if (!req) return;
  const status = exportEl_("export-status");
  const ready = exportEl_("export-ready");
  const btn = exportEl_("export-get-btn");
  btn.disabled = true;
  ready.hidden = true;
  ready.textContent = "";
  status.style.color = "";
  status.textContent = tr("export.preparing");
  try {
    const res = await callApi("exportDownload", req);
    status.textContent = tr("export.ready");
    res.files.forEach((f) => {
      const b = document.createElement("button");
      b.type = "button";
      b.className = "primary";
      b.style.marginTop = "8px";
      b.textContent = tr("export.save", { file: exportFileLabel_(f) });
      b.addEventListener("click", () => saveExportFile_(f));
      ready.appendChild(b);
    });
    ready.hidden = false;
  } catch (err) {
    status.style.color = "#d64545";
    status.textContent = err.message;
  } finally {
    refreshExportScreen_();
  }
}

// iPhone: the share sheet ("Save to Files") when the browser can share files;
// otherwise (desktop, older browsers) a normal download link.
async function saveExportFile_(f) {
  const status = exportEl_("export-status");
  status.style.color = "";
  const file = new File([f.text], f.name, { type: f.mime });
  try {
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file] });
      return;
    }
  } catch (err) {
    if (err && err.name === "AbortError") return;   // closed the share sheet: not an error
    // anything else: fall through to the plain download below
  }
  try {
    const url = URL.createObjectURL(file);
    const a = document.createElement("a");
    a.href = url;
    a.download = f.name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  } catch (err) {
    status.style.color = "#d64545";
    status.textContent = err.message;
  }
}

async function sendExport_() {
  const status = exportEl_("export-status");
  const btn = exportEl_("export-send-btn");
  const req = exportRequest_();
  if (!req) return;
  btn.disabled = true;
  status.style.color = "";
  status.textContent = tr("export.sending");
  try {
    const res = await callApi("exportData", req);
    const parts = res.files.map(exportFileLabel_);
    status.textContent = tr("export.sent", { files: parts.join(tr("export.and")) });
  } catch (err) {
    status.style.color = "#d64545";
    status.textContent = err.message;
  } finally {
    refreshExportScreen_();
  }
}

document.getElementById("data-export-btn").addEventListener("click", showExportScreen);
document.getElementById("export-back-btn").addEventListener("click", showMyDataScreen);
// A changed choice makes the files already prepared out of date: their Save buttons go, and "Get my files" is the main button again.
function clearExportReady_() {
  if (exportEl_("export-ready").hidden) return;
  exportEl_("export-ready").hidden = true;
  exportEl_("export-ready").textContent = "";
  exportEl_("export-status").textContent = "";
}
["export-entries-check", "export-backup-check", "export-range", "export-pending-check"].forEach((id) => {
  exportEl_(id).addEventListener("change", () => { clearExportReady_(); refreshExportScreen_(); saveExportPrefs_(); });
});
["export-start", "export-end"].forEach((id) => exportEl_(id).addEventListener("change", () => { clearExportReady_(); refreshExportScreen_(); }));
document.getElementById("export-get-btn").addEventListener("click", getExportFiles_);
document.getElementById("export-send-btn").addEventListener("click", sendExport_);

// ---- First-use practice: Export my data (owner's design, 2026-11-03) ----
// Offered on More → My data → Export my data. The person really makes a file of their OWN entries and gets the Save button (the
// phone's share sheet) for it. Nothing is recorded in the app (exporting only reads), so there is no server cleanup and no capability
// flag. It starts from the person's own choices (owner's walk, 2026-11-05: wiping them and restoring them looked like the app changing
// its mind): only "Entries spreadsheet" is checked if it was not, because that is the file it makes, and it stays checked. The person
// changes only the period, and that alone is put back at the end.
let practiceE_ = null;   // { range }: the period before the practice started

function offerExportTip_() {
  offerTip_("export", "export-tip-invite", tr("spot.e.invite"), startExportPractice_);
}

function practiceESteps_() {
  const el = (id) => document.getElementById(id);
  const ready = () => document.querySelector("#export-ready button");
  const statusError = () => { const s = el("export-status"); return s.style.color ? (s.textContent || "").trim() : ""; };
  return [
    { key: "intro", text: () => tr("spot.e.intro"), button: () => tr("spot.e.start") },
    { target: "#export-range", text: () => tr("spot.e.s2"), visit: "#export-range" },
    // (While the file is being prepared the button is disabled, so it looks pale: the text says what is happening instead of "Tap".)
    { key: "get", target: "#export-get-btn", text: () => { const e = statusError(); if (e) return tr("spot.e.s4err", { error: e }); return el("export-get-btn").disabled ? tr("export.preparing") : tr("spot.e.s4"); },
      until: () => !!ready() },
    { target: "#export-ready button", text: () => tr("spot.e.s5"), tap: "#export-ready button", wait: 15000 },
    { text: () => tr("spot.e.s6"), button: () => tr("spot.e.finish") }
  ];
}

function startExportPractice_() {
  const open = ["exchange-modal-backdrop", "edit-entry-modal-backdrop", "drilldown-modal-backdrop", "currency-modal-backdrop"].some((id) => { const e = document.getElementById(id); return e && !e.hidden; });
  if (open || newEntrySheetOpen_) { showToast_(tr("spot.x.busy")); return false; }
  practiceE_ = { range: exportEl_("export-range").value };
  exportEl_("export-entries-check").checked = true;
  exportEl_("export-status").textContent = "";
  exportEl_("export-status").style.color = "";
  exportEl_("export-ready").hidden = true;
  exportEl_("export-ready").textContent = "";
  refreshExportScreen_();
  runTip_(practiceESteps_(), async (how) => {
    const mine = practiceE_;
    practiceE_ = null;
    // Only the period goes back; every other choice is as the person sees it.
    if (mine) exportEl_("export-range").value = mine.range;
    saveExportPrefs_();
    if (!document.getElementById("screen-export").hidden) showExportScreen();   // redraws the boxes (the tip is already marked as seen)
    if (how === "done") showToast_(tr("spot.e.done"));
  }, tr("spot.e.note"));
  return true;
}

// ---- Categories that catch up later (backend/CategoryFollow.gs) ----

let appUndoTimer_ = null, appUndoLeaving_ = null;
// A message with an Undo button, for something the app did for the person beyond what they tapped. Undos STACK (QA round 2, 2026-11-03): a second
// action used to replace the first one's Undo, which made the first change permanent without a word. Now the button undoes the newest, then offers
// the one before it (if it is under a minute old); the toast says how many earlier ones wait. When the toast times out (10 s) all of them go.
// `kind` ("friends", "accounts"...) lets a screen drop the Undo of something the person has just reversed by hand (dropUndoKind_).
const UNDO_STACK_MAX_ = 5, UNDO_STACK_FRESH_MS_ = 60000;
let appUndoStack_ = [];   // newest first
function paintUndoToast_() {
  const box = document.getElementById("app-undo-toast");
  clearTimeout(appUndoTimer_);
  const top = appUndoStack_[0];
  if (!top) { box.hidden = true; return; }
  const earlier = appUndoStack_.length - 1;
  document.getElementById("app-undo-text").textContent = top.text + (earlier ? " " + tr("tidy.undoEarlier", { n: earlier }) : "");
  clearTimeout(appUndoLeaving_);   // a new Undo arriving while the old one slides away stays
  box.classList.remove("is-dragging", "is-leaving");
  box.style.removeProperty("--drag-y");
  box.style.removeProperty("opacity");
  box.hidden = false;
  startUndoTimer_();
}
function startUndoTimer_() {
  clearTimeout(appUndoTimer_);
  appUndoTimer_ = setTimeout(dismissUndoToast_, 10000);
}
// Closing it by hand (a tap, or a swipe down) is the same as letting it time out: every waiting Undo goes.
function dismissUndoToast_() {
  clearTimeout(appUndoTimer_);
  appUndoStack_ = [];
  document.getElementById("app-undo-toast").hidden = true;
}
// Owner's request 2026-11-07: the Undo message follows the finger. Held, it moves with it; let go, it springs back to its place unless it was
// pulled clearly downwards (far enough, or flicked fast), then it slides away. Upwards it only gives a little (it stays anchored). A tap on the
// message (not on Undo) closes it too. While held it does not time out.
(function wireUndoToastDrag_() {
  const box = document.getElementById("app-undo-toast");
  const DISMISS_PX = 60, FLICK_PX = 20, FLICK_SPEED = 0.5, TAP_PX = 8;   // speed in px per ms
  let drag = null, swallowClick = false;
  box.addEventListener("pointerdown", (e) => {
    if (e.button > 0) return;
    swallowClick = false;
    const onUndo = !!(e.target && e.target.closest && e.target.closest("#app-undo-btn"));
    drag = { id: e.pointerId, y0: e.clientY, t0: e.timeStamp, dy: 0, moved: false, onUndo, lastY: e.clientY, lastT: e.timeStamp, v: 0 };
    clearTimeout(appUndoTimer_);
    box.classList.add("is-dragging");
  });
  box.addEventListener("pointermove", (e) => {
    if (!drag || e.pointerId !== drag.id) return;
    const raw = e.clientY - drag.y0;
    if (!drag.moved && Math.abs(raw) > TAP_PX) {
      drag.moved = true;
      // Held only once it moves: a plain tap must still reach the Undo button as a normal click.
      try { box.setPointerCapture(e.pointerId); } catch (_) {}
    }
    const dt = e.timeStamp - drag.lastT;
    if (dt > 0) drag.v = (e.clientY - drag.lastY) / dt;
    drag.lastY = e.clientY;
    drag.lastT = e.timeStamp;
    drag.dy = raw > 0 ? raw : raw * 0.25;   // upwards: a little give, it stays where it belongs
    box.style.setProperty("--drag-y", drag.dy + "px");
    box.style.opacity = raw > 0 ? String(Math.max(0.3, 1 - raw / 200)) : "";
  });
  function release(e, cancelled) {
    if (!drag || e.pointerId !== drag.id) return;
    const d = drag;
    drag = null;
    box.classList.remove("is-dragging");
    if (!cancelled && !d.moved) {   // a tap
      if (!d.onUndo) dismissUndoToast_();
      else startUndoTimer_();   // the button's own click does the Undo
      return;
    }
    swallowClick = d.onUndo;   // a drag that began on the Undo button is not a press of it (the click comes right after the release)
    if (swallowClick) setTimeout(() => { swallowClick = false; }, 400);
    const down = d.dy > 0 ? d.dy : 0;
    const speed = Math.max(d.v, down / Math.max(1, e.timeStamp - d.t0));   // the last movement, or the whole gesture's average
    if (!cancelled && (down >= DISMISS_PX || (down >= FLICK_PX && speed >= FLICK_SPEED))) {
      box.classList.add("is-leaving");
      box.style.setProperty("--drag-y", (down + 160) + "px");
      box.style.opacity = "0";
      appUndoLeaving_ = setTimeout(dismissUndoToast_, 200);
      return;
    }
    box.style.removeProperty("--drag-y");   // springs back (CSS transition)
    box.style.removeProperty("opacity");
    startUndoTimer_();
  }
  box.addEventListener("pointerup", (e) => release(e, false));
  box.addEventListener("pointercancel", (e) => release(e, true));
  box.addEventListener("click", (e) => {
    if (swallowClick) { swallowClick = false; e.stopImmediatePropagation(); e.preventDefault(); }
  }, true);
})();
function showUndoToast_(text, onUndo, kind) {
  appUndoStack_.unshift({ text, action: onUndo, kind: kind || "", at: Date.now() });
  if (appUndoStack_.length > UNDO_STACK_MAX_) appUndoStack_.length = UNDO_STACK_MAX_;
  paintUndoToast_();
}
function dropUndoKind_(kind) {
  appUndoStack_ = appUndoStack_.filter((e) => e.kind !== kind);
  paintUndoToast_();
}
document.getElementById("app-undo-btn").addEventListener("click", async () => {
  const entry = appUndoStack_.shift();
  document.getElementById("app-undo-toast").hidden = true;
  clearTimeout(appUndoTimer_);
  if (!entry) return;
  try { await entry.action(); } catch (err) { alert(err.message || String(err)); }
  appUndoStack_ = appUndoStack_.filter((e) => Date.now() - e.at < UNDO_STACK_FRESH_MS_);
  paintUndoToast_();   // the one before it, if any
});

// An edit gave one entry a category and the server filled the other blanks of the same merchant (answer of updateEntry).
function onCategoryFollowed_(follow) {
  refreshEntryList().catch(() => {});
  refreshHomeGlance_(true);
  showUndoToast_(tr(follow.similarCount ? "follow.doneSimilar" : "follow.done", { n: follow.count, category: follow.categoryName }), async () => {
    await callApi("undoCategoryFollow", { changes: [{ categoryId: follow.categoryId, ids: follow.ids }], annualIds: follow.annualIds });
    showToast_(tr("tidy.undone"));
    refreshEntryList().catch(() => {});
    refreshHomeGlance_(true);
  });
}

const tidySkipped_ = new Set();   // groups the person skipped on this visit
let tidyGroups_ = [];
let tidyData_ = {};

// ---- More → Recently deleted (stage 3 of the Home bulk edit, owner's plan 2026-11-03) ----
// Entries deleted several at a time keep a 30-day safety copy on the server. Here they can be restored (a whole batch or one entry) or deleted for good.
// The same restore is the Undo on the delete toast.
async function restoreDeletedBatch_(payload) {
  const out = await callApi("restoreDeletedEntries", payload);
  practiceDNote_("restored", out.restored);
  showToast_(out.restored.length ? tr("deleted.restored", { n: out.restored.length }) : tr("deleted.restoredNone"), false, 6000);   // (everything was already back)
  if (out.lostDebt && out.lostDebt.length) alert(tr("deleted.lostDebt", { n: out.lostDebt.length }));
  try { await refreshEntryList(); } catch (e) { /* the list shows its own error */ }
  if (searchActive) await refreshSearchAfterEdit_();
  afterNewEntrySaved_();
  refreshLoans().catch(() => {});
  refreshReviewQueue(undefined, true).catch(() => {});   // a restored waiting entry is back in Needs review
  if (!document.getElementById("screen-deleted-entries").hidden) refreshDeletedScreen_().catch(() => {});
  return out;
}
async function showDeletedScreen_() {
  showMoreSub_("deleted-entries");
  document.getElementById("deleted-list").innerHTML = `<p class="hint">${escapeHtml(tr("common.loading"))}</p>`;
  document.getElementById("deleted-empty").hidden = true;
  await refreshDeletedScreen_();
  if (!document.getElementById("deleted-error").textContent) offerDeletedTip_();   // loading standard: offered once everything has arrived
}
const deletedBatchBusy_ = {};   // batch id -> the restore still on its way for that batch
async function refreshDeletedScreen_() {
  const errorEl = document.getElementById("deleted-error");
  errorEl.textContent = "";
  const list = document.getElementById("deleted-list");
  let res;
  try { res = await callApi("listDeletedEntries", {}); }
  catch (err) { list.innerHTML = ""; errorEl.textContent = tr("business.loadFailed", { error: err.message }); return; }
  list.innerHTML = "";
  document.getElementById("deleted-empty").hidden = res.batches.length > 0;
  document.getElementById("deleted-empty").textContent = tr("deleted.empty", { days: res.days });
  const when = (iso) => new Date(iso).toLocaleString(I18n.getLang() === "es" ? "es" : "en", { dateStyle: "medium", timeStyle: "short" });
  res.batches.forEach((b) => {
    const box = document.createElement("div");
    box.className = "deleted-batch";
    box.dataset.entries = b.entries.map((e) => e.entry_id).join(",");   // (the Recently deleted practice finds its own batch by these)
    box.innerHTML = `<div class="deleted-batch-title">${escapeHtml(tr("deleted.batchTitle", { when: when(b.deleted_at), n: b.entries.length }))}</div>
      <div class="hint deleted-batch-sub">${escapeHtml(shortNames_(b.entries.map((e) => e.description || tr("review.noDescription"))))}</div>`;   // (batches made in the same minute read alike: what is inside tells them apart)
    b.entries.forEach((e) => {
      const catName = (meta.categories.find((c) => c.id === e.category_id) || {}).name || "";
      const row = document.createElement("div");
      row.className = "recurring-row";
      row.dataset.entryId = e.entry_id;
      row.innerHTML = `
        <div>
          <div class="recurring-row-name">${escapeHtml(e.description || catName || tr("review.noDescription"))}</div>
          <div class="recurring-row-sub">${escapeHtml([listDate_(e.date), catName, e.shared ? tr("deleted.sharedTag") : "", e.status === "pending" ? tr("deleted.pendingTag") : ""].filter(Boolean).join(" · "))}</div>
        </div>
        <div class="recurring-row-amount"><span class="primary-amt${entryFlowDirection_(e) === "in" ? " review-amt-in" : ""}">${formatAmount(Math.abs(Number(e.amount) || 0), e.currency, { in: "+", out: "−" }[entryFlowDirection_(e)] || "")}</span><button type="button" class="add-inline deleted-one">${escapeHtml(tr("deleted.restoreOne"))}</button></div>`;
      row.querySelector(".deleted-one").addEventListener("click", () => {
        // The row leaves at once (the screen shows the change, the server catches up: owner's walk 2026-11-05, the practice waited here).
        // "Delete for good" on the same batch waits for this restore first, so it can never forget the entry being brought back.
        const ownPractice = practiceDOwns_([e.entry_id]);
        const work = (deletedBatchBusy_[b.batch_id] || Promise.resolve()).catch(() => {})
          .then(() => restoreDeletedBatch_({ batch_id: b.batch_id, ids: [e.entry_id] }));
        deletedBatchBusy_[b.batch_id] = work;
        saveBehindScreen_(() => work, null, { busy: "deleted.restoring" });
        row.remove();
        if (ownPractice && practiceD_) { practiceD_.restoreTapped = true; practiceDSave_(); }
      });
      box.appendChild(row);
    });
    const actions = document.createElement("div");
    actions.className = "deleted-batch-actions";
    actions.innerHTML = `<button type="button" class="primary deleted-all">${escapeHtml(tr("deleted.restoreAll"))}</button><button type="button" class="add-inline deleted-forget">${escapeHtml(tr("deleted.forget"))}</button>`;
    actions.querySelector(".deleted-all").addEventListener("click", () => {
      saveBehindScreen_(() => restoreDeletedBatch_({ batch_id: b.batch_id }), null, { busy: "deleted.restoring" });
    });
    actions.querySelector(".deleted-forget").addEventListener("click", () => {
      const ownPractice = practiceDOwns_(b.entries.map((e) => e.entry_id));
      if (!practiceNoConfirm_(ownPractice) && !confirm(tr("deleted.confirmForget", { n: b.entries.length }))) return;   // (the practice's own batch asks nothing while the walkthrough runs)
      if (ownPractice && practiceD_) { practiceD_.forgetTapped = true; practiceDSave_(); }   // the practice moves on at once; the cleanup waits for the call
      saveBehindScreen_(async () => {
        await (deletedBatchBusy_[b.batch_id] || Promise.resolve()).catch(() => {});   // a restore from this batch lands first
        await callApi("forgetDeletedEntries", { batch_id: b.batch_id });
        if (ownPractice) practiceDNote_("forgot");
      }, () => refreshDeletedScreen_().catch(() => {}), { busy: "common.deletingToast" });
    });
    box.appendChild(actions);
    list.appendChild(box);
  });
}
document.getElementById("more-deleted-btn").addEventListener("click", showDeletedScreen_);
document.getElementById("deleted-back-btn").addEventListener("click", () => showMyDataScreen());   // it lives in the My data hub, under "Then tidy"

// ---- First-use practice: Recently deleted (owner's design, 2026-11-03) ----
// Offered on More → My data → Recently deleted. The person really deletes TWO made-up expenses together from Home (edit mode: pencil, tick both,
// Delete), then finds them in Recently deleted, restores one and deletes the other for good. One server call makes the two entries
// (createPracticeDeleted); one cleanup call (removePracticeDeleted) deletes whichever is still on the books and drops the safety copies, in the
// background like the other practices, also on Exit and, if the app was closed midway, the next time it opens (it asks first).
// Only the practice's own rows are ever lit up and tappable (the ticks, the one Restore, the batch's Delete for good), so a real entry or a
// real batch is never touched.
const PRACTICE_D_KEY_ = "tipPracticeDeleted";
let practiceD_ = null;          // { made, ids, deleted, restored, forgot, startedOn }
let practiceDRemoving_ = false;
let practiceDLeftoverAsked_ = false;
let practiceDMaking_ = null;    // the creation call started while the person taps Home

function practiceDLoad_() { try { return JSON.parse(localStorage.getItem(PRACTICE_D_KEY_) || "null"); } catch (e) { return null; } }
function practiceDSave_() {
  try { if (practiceD_) localStorage.setItem(PRACTICE_D_KEY_, JSON.stringify(practiceD_)); else localStorage.removeItem(PRACTICE_D_KEY_); } catch (e) { /* ignore */ }
}
const practiceDIds_ = () => (practiceD_ && practiceD_.ids) || [];
// Is this list of entry ids the practice's own (all of them are)? Only while a practice is running.
function practiceDOwns_(ids) {
  const mine = practiceDIds_();
  return Spotlight.isRunning() && mine.length > 0 && ids.length > 0 && ids.every((id) => mine.includes(String(id)));
}
// What the real screens report back to the practice (the delete sheet, Restore, Delete for good).
function practiceDNote_(what, ids) {
  if (!practiceD_ || !practiceD_.ids.length) return;
  const mine = practiceD_.ids;
  if (what === "deleted" && mine.every((id) => (ids || []).map(String).includes(id))) {
    practiceD_.deleted = true;
    if (!document.getElementById("screen-deleted-entries").hidden) refreshDeletedScreen_().catch(() => {});   // already open: show the batch now
  }
  else if (what === "restored" && (ids || []).some((id) => mine.includes(String(id)))) practiceD_.restored = true;
  else if (what === "forgot") practiceD_.forgot = true;
  else return;
  practiceDSave_();
}

function offerDeletedTip_() {
  const caps = (meta && meta.capabilities) || {};
  if (!caps.practiceDeleted || !caps.entriesRestore || !caps.entriesBulk) return;   // an older backend could not make the practice entries, keep a safety copy or clean up
  offerTip_("deleted", "deleted-tip-invite", tr("spot.d.invite"), startDeletedPractice_);
}

function practiceDSteps_() {
  const el = (id) => document.getElementById(id);
  const deletedShown = () => !el("screen-deleted-entries").hidden;
  const homeRow = (i) => () => { const id = practiceDIds_()[i]; return id ? document.querySelector(`#entry-list .entry[data-entry-id="${id}"]`) : null; };
  const picked = (i) => () => entriesSelected_.has(practiceDIds_()[i]);
  const pokeHome = () => { refreshEntryList().catch(() => {}); };
  const pokeDeleted = () => { if (deletedShown()) refreshDeletedScreen_().catch(() => {}); };
  const batch = () => Array.from(document.querySelectorAll("#deleted-list .deleted-batch")).find((b) => (b.dataset.entries || "").split(",").some((id) => practiceDIds_().includes(id))) || null;
  const restoreBtn = () => { const b = batch(); return b ? b.querySelector(`.recurring-row[data-entry-id="${practiceDIds_()[0]}"] .deleted-one`) : null; };
  const forgetBtn = () => { const b = batch(); return b && b.querySelectorAll(".recurring-row").length === 1 ? b.querySelector(".deleted-forget") : null; };   // (once one is restored, the batch holds the other alone)
  return [
    { key: "intro", text: () => tr("spot.d.intro"), button: () => tr("spot.d.start") },
    // The two entries are made while the person reads the intro and taps Home (started in startDeletedPractice_; it used to start only
    // after the Home tap, a wait of several seconds on a phone).
    { target: '.nav-btn[data-screen="entries"]', text: () => tr("spot.d.s1"), tap: '.nav-btn[data-screen="entries"]' },
    { key: "edit", target: "#entries-edit-btn", text: () => tr("spot.d.s2"), until: () => entriesEditing_, wait: 20000, poke: pokeHome,
      before: async () => { if (!(await (practiceDMaking_ || practiceDMake_()))) return false; },
      after: () => { prefetchEntriesDeletePreview_(practiceDIds_()); } },   // the delete sheet then opens with its choices ready
    { key: "tick1", target: homeRow(0), text: () => tr("spot.d.s3"), until: picked(0), ok: picked(0), holdsUntil: "del", wait: 20000, poke: pokeHome },
    { key: "tick2", target: homeRow(1), text: () => tr("spot.d.s4"), until: picked(1), ok: picked(1), holdsUntil: "del", wait: 20000, poke: pokeHome,
      after: () => { const t = [...entriesSelected_]; if (t.slice().sort().join(",") !== practiceDIds_().slice().sort().join(",")) prefetchEntriesDeletePreview_(t); } },
    { key: "del", target: "#entries-delete-selected-btn", text: (fix) => tr(fix ? "spot.d.s5fix" : "spot.d.s5"), tap: "#entries-delete-selected-btn" },
    { target: "#entries-bulk-go", text: () => tr("spot.d.s6"), tap: "#entries-bulk-go", wait: 20000 },
    // (The note about the 10-second Undo is part of the next step's text. The rows already show "Deleting…"; the server's answer is awaited only where it is needed, at the batch.)
    { target: '.nav-btn[data-screen="more"]', text: () => tr("spot.d.s8"), tap: '.nav-btn[data-screen="more"]' },
    // More remembers the sub-screen it was left on, so usually this already shows Recently deleted and the next two steps drop out.
    { target: "#more-my-data-btn", text: () => tr("spot.d.s9"), tap: "#more-my-data-btn",
      before: async () => { await sleep(500); return !deletedShown() && el("screen-my-data").hidden; } },
    { target: "#more-deleted-btn", text: () => tr("spot.d.s10"), tap: "#more-deleted-btn",
      before: async () => { await sleep(150); return !deletedShown(); } },
    { target: restoreBtn, text: () => tr("spot.d.s12"), until: () => !!(practiceD_ && (practiceD_.restored || practiceD_.restoreTapped)), wait: 20000, poke: pokeDeleted,
      before: async () => {
        for (let i = 0; i < 100 && !(practiceD_ && practiceD_.deleted); i++) await sleep(400);   // up to 40 s for the server (usually long done)
        if (!(practiceD_ && practiceD_.deleted)) { alert(tr("spot.d.deleteFailed")); Spotlight.stop("skipped"); return false; }
        if (!batch()) pokeDeleted();   // the screen opened before the delete landed
        return true;
      } },
    { target: forgetBtn, text: () => tr("spot.d.s13"), until: () => !!(practiceD_ && (practiceD_.forgot || practiceD_.forgetTapped)), wait: 15000, poke: pokeDeleted },
    { text: () => tr("spot.d.s14"), button: () => tr("spot.d.finish") }
  ];
}

// Adds the two practice entries and refreshes Home so they show. False = it could not (the practice stops, the usual cleanup runs).
async function practiceDMake_() {
  setEntriesEditing_(false);
  practiceD_.made = true;   // (marked BEFORE the call: if the app is closed in the middle, the cleanup is simply a harmless no-op)
  practiceDSave_();
  try {
    const res = await callApi("createPracticeDeleted", { lang: I18n.getLang() });
    practiceD_.ids = (res.ids || []).map(String);
    practiceDSave_();
    await refreshEntryList();
    return true;
  } catch (err) {
    alert(tr("spot.d.createFailed", { error: err.message || String(err) }));
    Spotlight.stop("skipped");
    return false;
  }
}

function startDeletedPractice_() {
  if (practiceDRemoving_) { showToast_(tr("spot.d.stillRemoving")); return false; }
  const open = ["exchange-modal-backdrop", "edit-entry-modal-backdrop", "drilldown-modal-backdrop", "currency-modal-backdrop", "entries-bulk-backdrop"].some((id) => { const e = document.getElementById(id); return e && !e.hidden; });
  if (open || newEntrySheetOpen_ || entriesEditing_) { showToast_(tr("spot.x.busy")); return false; }
  practiceD_ = { made: false, ids: [], deleted: false, restored: false, forgot: false, startedOn: todayLocalISO() };
  practiceDSave_();
  practiceDMaking_ = practiceDMake_();
  runTip_(practiceDSteps_(), async () => {
    closeEntriesBulkSheet_();
    setEntriesEditing_(false);
    showToast_(tr("spot.d.removing"));
    practiceDRemove_().then((ok) => { if (ok) showToast_(tr("spot.d.removed")); });
  }, tr("spot.d.note"));
  return true;
}

async function practiceDRemove_() {
  if (practiceDRemoving_) return false;
  const p = practiceD_ || practiceDLoad_();
  if (!p) return true;
  practiceDRemoving_ = true;
  try {
    let ok = true;
    if (p.made) {
      for (let i = 0; i < 40 && perfInflight_ > 0; i++) await sleep(400);   // a delete / restore still on its way lands first
      try { await callApi("removePracticeDeleted", {}); }
      catch (err) { ok = false; practiceCleanupFailed_("d", err); }
    }
    if (ok) { practiceD_ = null; practiceDSave_(); }
    if (!document.getElementById("screen-deleted-entries").hidden) refreshDeletedScreen_().catch(() => {});   // the practice batch leaves the list
    refreshEntryList().catch(() => {});
    refreshHomeGlance_(true);
    return ok;
  } finally { practiceDRemoving_ = false; }
}

// A practice left behind (the app was closed midway): offered once when the app opens.
function practiceDLeftover_() {
  if (practiceDue_("d")) return;   // already being retried, nothing to ask
  if (practiceDLeftoverAsked_ || practiceDRemoving_ || Spotlight.isRunning() || !(practiceDLoad_() || {}).made) return;
  practiceDLeftoverAsked_ = true;
  if (confirm(tr("spot.d.leftover"))) practiceDRemove_().then((ok) => { if (ok) showToast_(tr("spot.d.removed")); });
}

async function showTidyScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-tidy"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  tidySkipped_.clear();
  const list = document.getElementById("tidy-list");
  list.textContent = "…";
  try {
    await loadTidy_();
    offerTidyTip_();   // only now that the list has arrived (loading standard)
  } catch (err) {
    list.textContent = err.message || String(err);
  }
}

async function loadTidy_() {
  const data = await callApi("listTidyGroups", practiceY_ && practiceY_.made ? { pinPractice: true } : {});   // (the practice's own group is listed first)
  tidyGroups_ = data.groups || [];
  tidyData_ = data;
  renderTidy_();
}

function tidyCategoryOptions_(selectedId) {
  return `<option value="">${escapeHtml(tr("tidy.pick"))}</option>` +
    sortedCategories_(pickableCategories_(meta.categories.filter((c) => c.type === "expense"), selectedId))
      .map((c) => `<option value="${escapeHtml(c.id)}"${c.id === selectedId ? " selected" : ""}>${escapeHtml(c.name)}</option>`).join("");
}

function renderTidy_() {
  const data = tidyData_;
  const groups = tidyGroups_.filter((g) => !tidySkipped_.has(g.key));
  const list = document.getElementById("tidy-list");
  const visibleEntries = groups.reduce((n, g) => n + g.count, 0);
  document.getElementById("tidy-empty").hidden = (data.totalEntries || 0) > 0;
  const summary = document.getElementById("tidy-summary");
  summary.hidden = !(data.totalEntries > 0);
  if (!summary.hidden) {
    summary.textContent = groups.length
      ? tr("tidy.summary", { n: data.groupCount > tidyGroups_.length ? data.totalEntries : visibleEntries, g: data.groupCount > tidyGroups_.length ? data.groupCount : groups.length })
      : tr("tidy.allSkipped");
  }
  const withSuggestion = groups.filter((g) => g.suggestion);
  const allBtn = document.getElementById("tidy-apply-all-btn");
  allBtn.hidden = !withSuggestion.length;
  allBtn.textContent = tr("tidy.applyAll", { n: withSuggestion.length });
  const more = document.getElementById("tidy-more");
  more.hidden = !(data.groupCount > data.shown);
  if (!more.hidden) more.textContent = tr("tidy.more", { shown: data.shown });
  list.innerHTML = groups.map((g) => {
    const dates = g.firstDate === g.lastDate ? I18n.fmtDateMedium(new Date(g.lastDate + "T00:00:00"))
      : I18n.fmtDateMedium(new Date(g.firstDate + "T00:00:00")) + " – " + I18n.fmtDateMedium(new Date(g.lastDate + "T00:00:00"));
    const sug = g.suggestion;
    return `<div class="tidy-group" data-key="${escapeHtml(g.key)}">
      <div class="tidy-group-top">
        <span class="tidy-group-name">${escapeHtml(g.label)}</span>
        <span class="tidy-group-total">${escapeHtml(data.main)} ${moneyFmt(g.totalMain)}</span>
      </div>
      <div class="hint tidy-group-meta">${escapeHtml(tr("tidy.count", { n: g.count }))} · ${escapeHtml(dates)}
        ${sug ? `<br>${escapeHtml(tr(sug.similar ? "tidy.suggestedSimilar" : "tidy.suggested", { category: sug.categoryName, n: sug.n, total: sug.total }))}` : ""}</div>
      <div class="tidy-group-row">
        <select class="tidy-select">${tidyCategoryOptions_(sug ? sug.categoryId : "")}</select>
        <button type="button" class="add-inline tidy-apply">${escapeHtml(tr("tidy.apply"))}</button>
        <button type="button" class="add-inline tidy-lines">${escapeHtml(tr("tidy.showLines"))}</button>
        <button type="button" class="add-inline tidy-skip">${escapeHtml(tr("tidy.skip"))}</button>
      </div>
      <ul class="tidy-samples" hidden>${g.samples.map((e) =>
        `<li><span>${escapeHtml(I18n.fmtDateMedium(new Date(e.date + "T00:00:00")))} · ${escapeHtml(e.description)}</span><span>${formatAmount(e.amount, e.currency)}</span></li>`).join("")}</ul>
    </div>`;
  }).join("");
}

// Fills the groups, then offers Undo; the list is reloaded so what is left (and any new suggestion) shows.
async function applyTidy_(items, buttons) {
  buttons.forEach((b) => { b.disabled = true; });
  showToast_(tr("common.savingToast"));
  try {
    const res = await callApi("applyTidyGroups", { items });
    if (!res.count) {
      showToast_(tr("tidy.nothingApplied"));
    } else {
      const mine = practiceYGroup_();
      const practiceApplied = !!(mine && items.some((it) => it.key === mine.key));
      if (practiceApplied && practiceY_) { practiceY_.applied = true; practiceYSave_(); }
      showUndoToast_(tr("tidy.applied", { n: res.count }), async () => {
        await callApi("undoCategoryFollow", { changes: res.changes, annualIds: res.annualIds });
        showToast_(tr("tidy.undone"));
        await loadTidy_();
        refreshEntryList().catch(() => {});
      }, practiceApplied ? "practice-tidy" : "");
      refreshEntryList().catch(() => {});
      refreshHomeGlance_(true);
    }
    await loadTidy_();
  } catch (err) {
    alert(err.message || String(err));
  } finally {
    buttons.forEach((b) => { b.disabled = false; });
  }
}

document.getElementById("tidy-list").addEventListener("click", (ev) => {
  const row = ev.target.closest(".tidy-group");
  if (!row) return;
  const key = row.dataset.key;
  if (ev.target.closest(".tidy-lines")) {
    const samples = row.querySelector(".tidy-samples");
    samples.hidden = !samples.hidden;
  } else if (ev.target.closest(".tidy-skip")) {
    tidySkipped_.add(key);
    renderTidy_();
  } else if (ev.target.closest(".tidy-apply")) {
    const categoryId = row.querySelector(".tidy-select").value;
    if (!categoryId) { alert(tr("review.pickCategoryFirst")); return; }
    applyTidy_([{ key, categoryId }], [ev.target.closest(".tidy-apply")]);
  }
});
document.getElementById("tidy-apply-all-btn").addEventListener("click", (ev) => {
  const items = tidyGroups_.filter((g) => g.suggestion && !tidySkipped_.has(g.key)).map((g) => ({ key: g.key, categoryId: g.suggestion.categoryId }));
  if (items.length) applyTidy_(items, [ev.currentTarget]);
});
document.getElementById("data-tidy-btn").addEventListener("click", showTidyScreen);
document.getElementById("tidy-back-btn").addEventListener("click", showMyDataScreen);

// ---- First-use practice: Tidy my history (owner's design, 2026-11-03) ----
// Offered on More → My data → Tidy my history. Tidy lists only entries WITHOUT a category, so the practice first adds three made-up
// ones ("Practice coffee shop", one server call: createPracticeTidy; the list is asked to show that group first, `pinPractice`), then the
// person looks at the group, shows its lines, picks a category once and taps the real Apply (applyTidyGroups, undoable as always).
// Only the practice's own group is ever lit up and tappable, so a real group is never touched. Cleanup = one call (removePracticeTidy),
// in the background like the other practices, also on Exit and, if the app was closed midway, the next time it opens (it asks first).
const PRACTICE_Y_KEY_ = "tipPracticeTidy";
let practiceY_ = null;          // { made, applied, startedOn }
let practiceYRemoving_ = false;
let practiceYLeftoverAsked_ = false;

function practiceYLoad_() { try { return JSON.parse(localStorage.getItem(PRACTICE_Y_KEY_) || "null"); } catch (e) { return null; } }
function practiceYSave_() {
  try { if (practiceY_) localStorage.setItem(PRACTICE_Y_KEY_, JSON.stringify(practiceY_)); else localStorage.removeItem(PRACTICE_Y_KEY_); } catch (e) { /* ignore */ }
}

function offerTidyTip_() {
  const caps = (meta && meta.capabilities) || {};
  if (!caps.practiceTidy) return;   // an older backend could not make the practice entries or clean them up
  if (!(meta.categories || []).some((c) => c.type === "expense")) return;   // nothing to pick from
  offerTip_("tidy", "tidy-tip-invite", tr("spot.y.invite"), startTidyPractice_);
}

// The practice's own group in the list the phone holds (the server marks it), and its box on screen.
function practiceYGroup_() { return tidyGroups_.find((g) => g.practice) || null; }
function practiceYBox_() {
  const g = practiceYGroup_();
  return g ? Array.from(document.querySelectorAll("#tidy-list .tidy-group")).find((b) => b.dataset.key === g.key) || null : null;
}

function practiceYSteps_() {
  const part = (sel) => () => { const b = practiceYBox_(); return b ? b.querySelector(sel) : null; };
  const picked = () => { const s = practiceYBox_() && practiceYBox_().querySelector(".tidy-select"); return !!s && !!s.value; };
  return [
    { key: "intro", text: () => tr("spot.y.intro"), button: () => tr("spot.y.start") },
    { target: part(".tidy-lines"), text: () => tr("spot.y.s2"), wait: 30000,
      before: async () => {
        if (!(await practiceYMake_())) return false;
      },
      until: () => { const b = practiceYBox_(); return !!b && !b.querySelector(".tidy-samples").hidden; } },
    { key: "pick", target: part(".tidy-select"), text: (fix) => tr(fix ? "spot.y.s3fix" : "spot.y.s3"), until: picked, ok: picked, holdsUntil: "apply" },
    { key: "apply", target: part(".tidy-apply"), text: () => tr("spot.y.s4"), until: () => !!(practiceY_ && practiceY_.applied) },
    { text: () => tr("spot.y.s5"), button: () => tr("spot.y.finish") }
  ];
}

// Adds the three practice entries and shows the list with their group first. False = it could not (the practice stops, the usual cleanup runs).
async function practiceYMake_() {
  practiceY_.made = true;   // (marked BEFORE the call: if the app is closed in the middle, the cleanup is simply a harmless no-op)
  practiceYSave_();
  try {
    await callApi("createPracticeTidy", { lang: I18n.getLang() });
    await loadTidy_();
    refreshEntryList().catch(() => {});
    return true;
  } catch (err) {
    alert(tr("spot.y.createFailed", { error: err.message || String(err) }));
    Spotlight.stop("skipped");
    return false;
  }
}

function startTidyPractice_() {
  if (practiceYRemoving_) { showToast_(tr("spot.y.stillRemoving")); return false; }
  const open = ["exchange-modal-backdrop", "edit-entry-modal-backdrop", "drilldown-modal-backdrop", "currency-modal-backdrop"].some((id) => { const e = document.getElementById(id); return e && !e.hidden; });
  if (open || newEntrySheetOpen_) { showToast_(tr("spot.x.busy")); return false; }
  practiceY_ = { made: false, applied: false, startedOn: todayLocalISO() };
  practiceYSave_();
  runTip_(practiceYSteps_(), async () => {
    dropUndoKind_("practice-tidy");
    showToast_(tr("spot.y.removing"));
    practiceYRemove_().then((ok) => { if (ok) showToast_(tr("spot.y.removed")); });
  }, tr("spot.y.note"));
  return true;
}

async function practiceYRemove_() {
  if (practiceYRemoving_) return false;
  const p = practiceY_ || practiceYLoad_();
  if (!p) return true;
  practiceYRemoving_ = true;
  try {
    let ok = true;
    if (p.made) {
      try { await callApi("removePracticeTidy", {}); }
      catch (err) { ok = false; practiceCleanupFailed_("y", err); }
    }
    if (ok) { practiceY_ = null; practiceYSave_(); }
    if (!document.getElementById("screen-tidy").hidden) loadTidy_().catch(() => {});   // the practice group leaves the list
    refreshEntryList().catch(() => {});
    refreshHomeGlance_(true);
    return ok;
  } finally { practiceYRemoving_ = false; }
}

// A practice left behind (the app was closed midway): offered once when the app opens.
function practiceYLeftover_() {
  if (practiceDue_("y")) return;   // already being retried, nothing to ask
  if (practiceYLeftoverAsked_ || practiceYRemoving_ || Spotlight.isRunning() || !(practiceYLoad_() || {}).made) return;   // (a practice closed before it made anything has nothing to remove)
  practiceYLeftoverAsked_ = true;
  if (confirm(tr("spot.y.leftover"))) practiceYRemove_().then((ok) => { if (ok) showToast_(tr("spot.y.removed")); });
}

// ---- More → My data: one row for everything about getting data in, tidying it and taking it out (owner's design, 2026-11-03) ----
// A small hub: Bank statements and Import from another app (the two modes of the Statements screen), Tidy my history (what a statement or an
// import leaves without a category), Export my data. Each row opens its own screen as before; their Back buttons return here.
function showMyDataScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-my-data"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  window.scrollTo(0, 0);
}
document.getElementById("more-my-data-btn").addEventListener("click", showMyDataScreen);
document.getElementById("my-data-back-btn").addEventListener("click", () => showScreen("more"));

// ---- More → Bank emails: a full screen since 2026-11-03; it also holds what used to be "Not captured automatically" ----
// (backend/BankCoverage.gs + backend/ManualGaps.gs; specs/review-telegram-email.md § Bank emails screen). One question, two views:
//  - By bank: for each bank the person uses, which KINDS of transaction its emails cover. "✓ arrived in your mailbox" only after one really
//    arrived in THIS person's copy; "○ can arrive" when the app can read it but none has yet (the bank's alert may be off); "✗ no email" only
//    for what the owner confirmed. Yape and Plin are wallets: drawn inside the bank account they are linked to, never as a bank of their own.
//  - By transaction: what the person added by hand in the last 90 days, in three groups by how necessary that was (must / check / optional),
//    each kind opening to its newest entries; then the bank emails the app couldn't read.
const beEl_ = (id) => document.getElementById(id);
let be_ = { view: "bank", data: null };

async function showBankEmailsScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-bank-emails"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  // Loading standard: the screen opens at once and shows its content only when everything it needs has arrived.
  beEl_("be-loading").hidden = false;
  beEl_("be-loading").textContent = tr("common.loading");
  beEl_("be-body").hidden = true;
  try {
    const data = await callApi("getManualGaps", {});
    be_.data = data;
    beEl_("be-groups").innerHTML = "";   // a new visit starts with every group closed
    beWhySendQueued_();   // an answer that could not reach JP last time
    // The same answer carries the freshest coverage (which kinds arrived and when), so the bank view is never older than the list beside it.
    if (meta && data.coverage) meta.emailInfo = Object.assign({}, meta.emailInfo || {}, { coverage: data.coverage, seen: data.seen || (meta.emailInfo || {}).seen });
    renderBankEmails_();
    beEl_("be-loading").hidden = true;
    beEl_("be-body").hidden = false;
  } catch (err) {
    beEl_("be-loading").textContent = err.message || String(err);
  }
}

function renderBankEmails_() {
  const info = (meta && meta.emailInfo) || {};
  const reading = !!(meta && meta.capabilities && meta.capabilities.bankEmails);
  beEl_("be-body").querySelectorAll(".bm-reading").forEach((el) => { el.hidden = !reading; });
  beEl_("be-address").textContent = info.address || tr("bankMail.noAddress");
  beEl_("be-address2").textContent = info.address || tr("bankMail.noAddress");
  beEl_("be-copy-btn").hidden = !info.address;
  beEl_("be-msg").textContent = "";
  beEl_("be-teach").hidden = perfIsOwnerCopy_();   // the owner writes the e-mail rules himself
  beEl_("be-tabs").hidden = !reading;
  renderMailHealth_();
  renderBeBanks_();
  renderBeTx_(be_.data || {});
  setBeView_(reading ? be_.view : "tx");
}

function setBeView_(view) {
  be_.view = view;
  beEl_("be-view-bank").hidden = view !== "bank";
  beEl_("be-view-tx").hidden = view !== "tx";
  [["bank", "be-tab-bank"], ["tx", "be-tab-tx"]].forEach(([v, id]) => {
    beEl_(id).classList.toggle("active", v === view);
    beEl_(id).setAttribute("aria-selected", v === view ? "true" : "false");
  });
}

// The bank a wallet's linked account belongs to ("BCP" for Yape), or "" when no account is linked.
function beWalletBank_(slotKeys) {
  const st = (meta && meta.settings) || {}, pms = (meta && meta.paymentMethods) || [], banks = (meta && meta.banks) || [];
  for (const key of slotKeys) {
    if (!st[key]) continue;
    const pm = pms.find((p) => String(p.id) === String(st[key]));
    const bank = pm && banks.find((b) => b.id === pm.bank_id);
    if (bank && bank.name) return String(bank.name).trim();
  }
  return "";
}

// One list of kinds: "✓ arrived" / "○ can arrive" for the kinds the rules read, "✗ no email" for the confirmed ones.
function beKindList_(kinds, none) {
  const ul = document.createElement("ul");
  ul.className = "be-kinds";
  kinds.forEach((k) => {
    const day = /^\d{4}-\d{2}-\d{2}$/.test(k.seen || "") ? k.seen : "";
    const li = document.createElement("li");
    li.className = day ? "ok" : "can";
    li.innerHTML = `<strong>${escapeHtml(tr("bankKind." + k.key))}</strong><span class="hint">${escapeHtml(day ? tr("be.state.seen", { date: I18n.fmtDateMedium(new Date(day + "T00:00:00")) }) : tr("be.state.can"))}</span>`;
    ul.appendChild(li);
  });
  (none || []).forEach((key) => {
    const li = document.createElement("li");
    li.className = "none";
    li.innerHTML = `<strong>${escapeHtml(tr("bankKind." + key))}</strong><span class="hint">${escapeHtml(tr("be.state.none"))}</span>`;
    ul.appendChild(li);
  });
  return ul;
}

function renderBeBanks_() {
  const box = beEl_("be-banks");
  box.innerHTML = "";
  const info = (meta && meta.emailInfo) || {};
  const seen = info.seen || {}, cov = info.coverage || null, readable = info.banks || [];
  const canTeach = !perfIsOwnerCopy_() && !!info.banks;   // an older pinned backend sends no emailInfo: do not call every bank unreadable
  const st = (meta && meta.settings) || {};
  const yapeLinked = !!(st.yape_pen || st.yape_usd);
  const yapeBank = beWalletBank_(["yape_pen", "yape_usd"]).toLowerCase();
  const plinBank = beWalletBank_(["plin_pen"]).toLowerCase();
  // Banks the person has an account at. Yape is a wallet of one of them; only a Yape linked to no known account gets a row of its own.
  const names = bmBanksInUse_().filter((n) => !(n.toLowerCase() === "yape" && yapeBank));
  const walletOnly = yapeLinked && !yapeBank && !names.some((n) => n.toLowerCase() === "yape");   // "(wallet)" only when there is no account called Yape
  if (walletOnly) names.push("Yape");
  names.forEach((used) => {
    const bank = readable.find((b) => b.toLowerCase() === used.toLowerCase());
    if (!bank && !canTeach) return;
    const key = used.toLowerCase();
    const row = document.createElement("details");
    row.className = "bm-bank";
    const sum = document.createElement("summary");
    const name = document.createElement("b");
    name.textContent = walletOnly && key === "yape" ? tr("be.wallet.yapeAlone") : (bank || used);
    sum.appendChild(name);
    const status = document.createElement("span");
    if (bank) {
      const day = seen[bank];
      status.className = "bm-status " + (day ? "ok" : "wait");
      status.textContent = day ? tr("bankMail.seen", { date: I18n.fmtDateMedium(new Date(day + "T00:00:00")) }) : tr("bankMail.notSeen");
    } else {
      status.className = "bm-status wait";
      status.textContent = tr("bankMail.notReadable");
    }
    sum.appendChild(status);
    row.appendChild(sum);
    const mine = bank && cov && cov[bank];
    if (mine) {
      const hasYape = yapeLinked && key === yapeBank, hasPlin = key === plinBank;
      const own = mine.kinds.filter((k) => !(hasYape && k.key === "yape_in") && !(hasPlin && k.key === "plin_out"));
      if (own.length || mine.none.length) row.appendChild(beKindList_(own, mine.none));
      const wallet = (titleKey, kinds, tipKey, none) => {
        const h = document.createElement("h4");
        h.className = "be-wallet";
        h.textContent = tr(titleKey);
        row.appendChild(h);
        row.appendChild(beKindList_(kinds, none || []));
        if (tipKey) { const t = document.createElement("p"); t.className = "hint"; t.textContent = tr(tipKey); row.appendChild(t); }
      };
      if (hasYape) wallet("be.wallet.yape", mine.kinds.filter((k) => k.key === "yape_in").concat((cov.Yape && cov.Yape.kinds) || []), "be.tip.yape");
      if (hasPlin) wallet("be.wallet.plin", mine.kinds.filter((k) => k.key === "plin_out"), null, ["plin_whatsapp"]);   // owner, 2026-11-05: a Plin made from WhatsApp sends no email
    }
    const tip = document.createElement("p");
    tip.className = "hint";
    tip.textContent = bank ? tr(BM_TIP_KEYS_[bank] || "bankMail.tip.generic") : tr("bankNote.text", { banks: used });
    row.appendChild(tip);
    if (!bank) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "add-inline";
      btn.textContent = tr("bankMail.teachBank");
      btn.addEventListener("click", () => openBankSampleModal_());
      row.appendChild(btn);
    }
    box.appendChild(row);
  });
  beEl_("be-foot").hidden = !cov;
}

// ---- By transaction ----
const BE_NEEDS_ = ["must", "check", "optional"];

// ---- "Why didn't an email come?" (owner, 2026-11-05) ----
// For the kinds whose reason the app cannot know (GAP_REASON_KINDS_ in ManualGaps.gs), the person picks one. The answer is kept on their copy
// (saveGapReason), names and places the group (a WhatsApp Plin or one under the alert's minimum must be added by hand), and goes to JP as a
// feedback note (kind 'email_gap'), so every case can be gathered and revised. A note that could not be sent waits in localStorage.
const BE_WHY_KINDS_ = ["yape_in", "yape_out", "plin_out", "other_manual"];
const BE_WHY_OUTBOX_ = "gapReasonOutbox";
// Asked only where the app cannot know the reason: a kind in "Add these for now" (an email exists but none came), or a Yape received / Plin
// sent with no email at all. Not where it is known: money received at a bank, a Yape under S/ 10 (both "must" for a stated reason).
function beWhyApplies_(k) {
  return !!(meta && meta.capabilities && meta.capabilities.gapReasons) && BE_WHY_KINDS_.includes(k.key)
    && (k.need === "check" || (k.need === "must" && (k.key === "yape_in" || k.key === "plin_out")));
}
function beWhyReasons_(key) { return (key === "plin_out" ? ["whatsapp"] : []).concat(["alert_off", "under_min", "dont_know", "other"]); }
// The kinds as the person explained them: a WhatsApp Plin joins "Plin sent from WhatsApp"; WhatsApp and "under the minimum" are must-add.
function beApplyReasons_(kinds, reasons) {
  const out = kinds.map((k) => {
    if (!beWhyApplies_(k)) return k;
    const r = reasons && reasons[k.key];
    if (!r) return Object.assign({}, k, { why: true });
    return Object.assign({}, k, { why: true, reason: r.reason, note: r.note || "", need: r.reason === "whatsapp" || r.reason === "under_min" ? "must" : k.need });
  });
  const wa = out.find((k) => k.key === "plin_out" && k.reason === "whatsapp");
  const own = out.find((k) => k.key === "plin_out_whatsapp");
  if (!wa || !own) return out;
  const merged = Object.assign({}, own, {
    count: own.count + wa.count, last: [own.last, wa.last].filter(Boolean).sort().pop() || "",
    items: own.items && wa.items ? own.items.concat(wa.items).sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 20) : own.items,
    totals: own.totals && wa.totals ? Object.keys(Object.assign({}, own.totals, wa.totals)).reduce((t, c) => { t[c] = (own.totals[c] || 0) + (wa.totals[c] || 0); return t; }, {}) : own.totals,
    why: true, reason: "whatsapp", note: "", whyKey: "plin_out"
  });
  return out.filter((k) => k !== wa && k !== own).concat([merged]);
}
function beWhyHtml_(k) {
  const key = k.whyKey || k.key;
  const chips = beWhyReasons_(key).map((r) => `<button type="button" class="be-why-opt${k.reason === r ? " on" : ""}" data-why-kind="${escapeHtml(key)}" data-why="${r}" aria-pressed="${k.reason === r ? "true" : "false"}">${escapeHtml(tr("be.why." + r))}</button>`).join("");
  const other = `<div class="be-why-other"${k.reason === "other" ? "" : " hidden"}><textarea rows="2" maxlength="300" data-why-note="${escapeHtml(key)}" placeholder="${escapeHtml(tr("be.why.otherPh"))}">${escapeHtml(k.note || "")}</textarea><button type="button" class="add-inline" data-why-save="${escapeHtml(key)}">${escapeHtml(tr("common.save"))}</button></div>`;
  const sent = perfIsOwnerCopy_() ? "" : `<p class="hint">${escapeHtml(tr("be.why.sent"))}</p>`;
  return `<div class="be-why"><p class="be-why-q">${escapeHtml(tr("be.why.q"))}</p><div class="be-why-opts">${chips}</div>${other}${sent}</div>`;
}
function beWhySendQueued_() {
  let box;
  try { box = JSON.parse(localStorage.getItem(BE_WHY_OUTBOX_)) || []; } catch (e) { box = []; }
  if (!box.length) return;
  const standalone = navigator.standalone || (window.matchMedia && matchMedia("(display-mode: standalone)").matches);
  const note = box[0];
  fetch(perfReportUrl_(), {
    method: "POST", headers: { "Content-Type": "text/plain;charset=utf-8" },
    body: JSON.stringify({ action: "reportFeedback", payload: {
      install: perfInstallId_(), label: perfShareState_().label || "", kind: "email_gap", screen: "bank_emails", language: I18n.getLang(),
      app: appRelease_(), device: PerfShare.deviceKind(navigator.userAgent, standalone), text: note } })
  }).then((res) => res.json()).then((json) => {
    if (!(json && json.ok)) return;
    let now;
    try { now = JSON.parse(localStorage.getItem(BE_WHY_OUTBOX_)) || []; } catch (e) { now = []; }
    localStorage.setItem(BE_WHY_OUTBOX_, JSON.stringify(now.filter((x) => x !== note)));
    beWhySendQueued_();   // the next one, if any
  }).catch(() => { /* tried again the next time the screen opens */ });
}
function beWhySave_(kind, reason, note) {
  const data = be_.data || {};
  const before = Object.assign({}, data.reasons || {});
  data.reasons = Object.assign({}, before, { [kind]: { reason, note: note || "" } });
  renderBeTx_(data);
  callApi("saveGapReason", { kind, reason, note: note || "" }).then((res) => {
    if (res && res.reasons) { data.reasons = res.reasons; renderBeTx_(data); }
    // The kind, the answer and its words, in English, so JP can gather the same case from every copy.
    const text = PerfShare.cleanFeedback(`[${kind}] ${reason}${note ? ": " + note : ""}`);
    let box;
    try { box = JSON.parse(localStorage.getItem(BE_WHY_OUTBOX_)) || []; } catch (e) { box = []; }
    box.push(text);
    localStorage.setItem(BE_WHY_OUTBOX_, JSON.stringify(box.slice(-20)));
    beWhySendQueued_();
  }).catch((err) => {
    data.reasons = before;
    renderBeTx_(data);
    alert(tr("common.notSaved", { error: err.message || String(err) }));
  });
}
beEl_("be-groups").addEventListener("click", (ev) => {
  const opt = ev.target.closest(".be-why-opt");
  if (opt) {
    ev.preventDefault();
    if (opt.dataset.why === "other") {
      const box = opt.closest(".be-why").querySelector(".be-why-other");
      box.hidden = false;
      box.querySelector("textarea").focus();
      return;
    }
    beWhySave_(opt.dataset.whyKind, opt.dataset.why, "");
    return;
  }
  const save = ev.target.closest("[data-why-save]");
  if (save) {
    const kind = save.dataset.whySave;
    const note = save.closest(".be-why-other").querySelector("textarea").value.trim();
    if (!note) { alert(tr("be.why.needNote")); return; }
    beWhySave_(kind, "other", note);
  }
});

function beKindName_(k) {
  if (k.reason === "whatsapp") return tr("notauto.kind.plin_out_whatsapp");
  if (k.need === "must") return k.key === "yape_out" ? tr("be.kind.must.yape_out") : tr("notauto.kind." + k.key);
  return tr(k.need ? "be.kind." + k.key : "notauto.kind." + k.key);
}

function beItemsHtml_(k) {
  if (!k.items || !k.items.length) return "";
  const rows = k.items.map((it) => {
    const day = /^\d{4}-\d{2}-\d{2}$/.test(it.date || "") ? I18n.fmtDateMedium(new Date(it.date + "T00:00:00")) : "";
    const amount = it.currency ? formatAmount(it.amount, it.currency, it.direction === "in" ? "+" : "−") : "";
    return `<li><span class="be-item-date">${escapeHtml(day)}</span><span class="be-item-text">${escapeHtml(it.description || "")}${it.source === "statement" ? ` <em class="hint">· ${escapeHtml(tr("be.tx.fromStatement"))}</em>` : ""}</span><span class="be-item-amt ${it.direction === "in" ? "in" : ""}">${escapeHtml(amount)}</span></li>`;
  }).join("");
  const more = k.count > k.items.length ? `<p class="hint">${escapeHtml(tr("be.tx.newest", { n: k.items.length, total: k.count }))}</p>` : "";
  return `<ul class="be-items">${rows}</ul>${more}`;
}

function beKindHtml_(k, owner) {
  const totals = owner && k.totals
    ? Object.keys(k.totals).map((cur) => `${escapeHtml(cur)} ${moneyFmt(k.totals[cur])}`).join(" · ")
    : "";
  const meta_ = tr("notauto.count", { n: k.count }) + (k.last ? " · " + tr("notauto.last", { date: I18n.fmtDateMedium(new Date(k.last + "T00:00:00")) }) : "")
    + (totals ? " · " + totals : "");
  // "must" kinds say how to add them; "check" / "optional" are explained once by their group's heading. An answer to "Why didn't an
  // email come?" says what to do about it instead.
  const tip = k.reason === "whatsapp" ? notAutoTip_("plin_out_whatsapp")
    : (k.reason === "under_min" || k.reason === "alert_off") ? tr("be.why.tip." + k.reason)
    : !k.need || k.need === "must" ? (k.need === "must" && k.key === "yape_out" ? tr("be.tip.must.yape_out") : notAutoTip_(k.key)) : "";
  const head = `<strong>${escapeHtml(beKindName_(k))}</strong><div class="hint" style="margin:2px 0;">${escapeHtml(meta_)}</div>`;
  const tipHtml = tip ? `<div class="hint" style="margin:2px 0;">${escapeHtml(tip)}</div>` : "";
  if (!k.items) return `<div class="more-list-item" style="display:block;">${head}${tipHtml}</div>`;   // an older backend: the plain list
  const why = k.why ? beWhyHtml_(k) : "";
  return `<details class="be-kind"${be_.openKinds && be_.openKinds.has(k.whyKey || k.key) ? " open" : ""} data-kind="${escapeHtml(k.whyKey || k.key)}"><summary>${head}</summary>${tipHtml}${why}${beItemsHtml_(k)}</details>`;
}

function renderBeTx_(data) {
  // A redraw after an answer keeps the groups that were open (the answer moves a group; it must not snap shut under the finger).
  be_.openKinds = new Set([...beEl_("be-groups").querySelectorAll("details.be-kind[open]")].map((d) => d.dataset.kind));
  const kinds = beApplyReasons_(data.kinds || [], data.reasons);
  const unread = data.unread || [];
  beEl_("be-empty").hidden = kinds.length > 0 || unread.length > 0;
  beEl_("be-unread").hidden = !unread.length;
  beEl_("be-unread-list").innerHTML = unread.map((u) => {
    // An older backend may still hand the date back in a form that is not yyyy-mm-dd: then say nothing rather than "Invalid Date".
    const meta_ = tr("notauto.unread.count", { n: u.count }) + (/^\d{4}-\d{2}-\d{2}$/.test(u.last || "") ? " · " + tr("notauto.last", { date: I18n.fmtDateMedium(new Date(u.last + "T00:00:00")) }) : "");
    return `<div class="more-list-item" style="display:block;">
      <strong>${escapeHtml(u.subject || u.sender)}</strong>
      <div class="hint" style="margin:2px 0;">${escapeHtml(u.sender)} · ${escapeHtml(meta_)}</div>
      <div class="hint" style="margin:2px 0;">${escapeHtml(tr("notauto.unread." + u.kind))}</div>
      ${perfIsOwnerCopy_() ? "" : `<button type="button" class="add-inline notauto-send" data-sender="${escapeHtml(u.sender)}" data-shape="${escapeHtml(u.subject)}">${escapeHtml(tr("notauto.unread.send"))}</button>`}
    </div>`;
  }).join("");
  const share = beEl_("be-share");
  share.hidden = !(data.owner && data.manualShare && data.manualShare.total);
  if (!share.hidden) share.textContent = tr("notauto.share", { manual: data.manualShare.manual, total: data.manualShare.total });
  const owner = !!data.owner;
  const grouped = kinds.some((k) => k.need);
  beEl_("be-groups").innerHTML = !grouped
    ? kinds.map((k) => beKindHtml_(k, owner)).join("")
    : BE_NEEDS_.map((need) => {
      const list = kinds.filter((k) => k.need === need);
      if (!list.length) return "";
      return `<div class="be-group be-${need}"><h3>${escapeHtml(tr("be.need." + need))}</h3><p class="hint">${escapeHtml(tr("be.need." + need + ".sub"))}</p>${list.map((k) => beKindHtml_(k, owner)).join("")}</div>`;
    }).join("");
}

