// ---- Performance log screen (More tab) ----

function showPerfScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-perf"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  renderPerfScreen();
}

function perfStats_(values) {
  const v = values.filter((x) => typeof x === "number").sort((a, b) => a - b);
  if (!v.length) return null;
  const pick = (q) => v[Math.min(v.length - 1, Math.floor(q * v.length))];
  return { n: v.length, median: pick(0.5), p90: pick(0.9), max: v[v.length - 1] };
}

function perfSummaryRows_() {
  let log = [];
  try { log = JSON.parse(localStorage.getItem(PERF_LOG_KEY) || "[]"); } catch (err) { /* empty */ }
  const groups = {};
  log.forEach((e) => {
    const key = `${e.kind === "startup" ? "◆ " : ""}${e.name}`;
    (groups[key] = groups[key] || []).push(e);
  });
  return Object.keys(groups).sort().map((key) => {
    const es = groups[key];
    const total = perfStats_(es.map((e) => e.totalMs));
    const server = perfStats_(es.map((e) => e.serverMs));
    return {
      name: key, total, server,
      cold: es.filter((e) => e.cold).length,
      retried: es.filter((e) => e.attempts > 1).length,
      failed: es.filter((e) => e.ok === false).length
    };
  });
}

function perfReportText_() {
  const rows = perfSummaryRows_();
  const first = (() => { try { return JSON.parse(localStorage.getItem(PERF_LOG_KEY) || "[]")[0]; } catch (e) { return null; } })();
  const lines = [`Performance report — since ${first ? new Date(first.t).toISOString() : "n/a"} — app ${document.querySelector('link[rel=stylesheet]').href.split("?v=")[1]}`,
    "name | n | median ms | p90 ms | max ms | server median ms | cold | retried | failed"];
  rows.forEach((r) => {
    lines.push([r.name, r.total.n, r.total.median, r.total.p90, r.total.max,
      r.server ? r.server.median : "-", r.cold, r.retried, r.failed].join(" | "));
  });
  return lines.join("\n");
}

function renderPerfScreen() {
  const box = document.getElementById("perf-summary");
  const rows = perfSummaryRows_();
  if (!rows.length) {
    box.innerHTML = `<div class="status-msg">${escapeHtml(tr("perf.empty"))}</div>`;
    return;
  }
  const fmt = (ms) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${ms}ms`);
  box.innerHTML = rows.map((r) => `
    <div class="perf-row">
      <div class="perf-name">${escapeHtml(r.name)} <span class="hint">×${r.total.n}</span></div>
      <div class="hint">${[tr("perf.median", { v: fmt(r.total.median) }), tr("perf.p90", { v: fmt(r.total.p90) }), tr("perf.max", { v: fmt(r.total.max) }),
        r.server ? tr("perf.server", { v: fmt(r.server.median) }) : "",
        r.cold ? tr("perf.cold", { n: r.cold }) : "", r.retried ? tr("perf.retried", { n: r.retried }) : "", r.failed ? tr("perf.failed", { n: r.failed }) : ""].filter(Boolean).join(" · ")}</div>
    </div>`).join("");
}

// ---- Exchange rates (More tab) ----

let ratesCache_ = [];            // the last list the server sent (the Add sheet finds an existing month in it)
const ratesOpen_ = new Set();    // currencies whose history is open (kept while the screen is redrawn)
const ratesAll_ = new Set();     // currencies showing all their months, not only the last 12
// Redraws from what the phone already holds (opening a currency's history needs no server call).
function refreshExchangeRatesFromCache_() { return refreshExchangeRates(ratesCache_); }

// ---- Add an exchange rate (More → Currencies, +; owner 2026-11-07): currency and month, then the usual rate window ----
function openRatesAdd_() {
  const sel = document.getElementById("rates-add-currency");
  const used = [...new Set(ratesCache_.map((r) => r.currency))];
  const choices = [...new Set(["USD", ...used])].filter((c) => c !== homeCur());
  sel.innerHTML = choices.map((c) => `<option value="${c}">${findCurrency(c).flag} ${c}</option>`).join("");
  sel.value = choices[0] || "";
  currencyPickOn_(sel);
  const now = new Date();   // this month on the phone's own calendar
  document.getElementById("rates-add-month").value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  document.getElementById("rates-add-error").textContent = "";
  const backdrop = document.getElementById("rates-add-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}
function ratesAddClose_() { document.getElementById("rates-add-modal-backdrop").hidden = true; }
document.getElementById("rates-add-btn").addEventListener("click", openRatesAdd_);
document.getElementById("rates-add-modal-close").addEventListener("click", ratesAddClose_);
document.getElementById("rates-add-next").addEventListener("click", async () => {
  const cur = String(document.getElementById("rates-add-currency").value || "").toUpperCase();
  const month = document.getElementById("rates-add-month").value;
  const err = document.getElementById("rates-add-error");
  if (!/^[A-Z]{3}$/.test(cur)) return;
  if (cur === homeCur()) { err.textContent = tr("rates.addMain", { cur }); return; }
  if (!/^\d{4}-\d{2}$/.test(month)) { err.textContent = tr("rates.addNoMonth"); return; }
  ratesAddClose_();
  // A month already on file opens with its rate, so it is edited, never doubled.
  const known = ratesCache_.find((r) => r.currency === cur && r.month === month);
  const usd = ratesUsdOn_();
  const existing = known ? (usd && known.per_usd > 0 ? known.per_usd : known.rate) : undefined;
  const newRate = await openRateModal(cur, month, /* required */ false, existing);
  if (newRate != null) { ratesOpen_.add(cur); refreshExchangeRates(); }
});

async function refreshExchangeRates(cached) {
  const list = document.getElementById("exchange-rates-list");
  const emptyNote = document.getElementById("exchange-rates-empty-note");
  let rates = cached;
  if (!rates) list.innerHTML = loadingHtml_();
  try {
    if (!rates) rates = await callApi("listExchangeRates");
  } catch (err) {
    list.innerHTML = `<div class="status-msg">${escapeHtml(tr("drill.loadFailed", { error: err.message }))}</div>`;
    return;
  }

  list.innerHTML = "";
  emptyNote.hidden = rates.length > 0;
  ratesCache_ = rates;

  // Friends' copies read every rate against the US dollar, the way banks and the news quote them ("USD 1 = EUR 0.92"); the
  // owner's own copy reads "X 1 = main" until its rates are stored against the dollar. Only the reading changes.
  const usd = ratesUsdOn_() && rates.every((r) => r.per_usd > 0);   // stored "1 USD = x": the server says each row's x
  const quotes = usd || perfIsOwnerCopy_() ? [] : RateQuotes.usdQuotes(rates, homeCur());
  renderRatesUsdOffer_(rates);
  // Each row as a pair: `per` units of b for one a (written with the stronger one as 1).
  const pair = (r, i) => (usd && r.per_usd > 0 ? { a: "USD", b: usdRateTarget_(r.currency), per: r.per_usd }
    : quotes[i] ? { a: "USD", b: quotes[i].target, per: quotes[i].per } : { a: r.currency, b: homeCur(), per: r.rate });
  // One row per currency (owner, 2026-11-07: too many rows with years of history): the latest rate, its month and how many
  // months are on file; a tap opens the history in place, newest first, with the change from the month before.
  const groups = new Map();
  rates.forEach((r, i) => {
    if (!groups.has(r.currency)) groups.set(r.currency, []);
    groups.get(r.currency).push({ r, p: pair(r, i) });
  });
  const codes = [...groups.keys()].sort((x, y) => (x === "USD" ? -1 : y === "USD" ? 1 : x < y ? -1 : 1));
  const monthWords = (m) => { const [y, mo] = m.split("-").map(Number); return `${I18n.monthShort(mo - 1, true)} ${y}`; };   // "Nov 2026": one line on a phone
  codes.forEach((code) => {
    const items = groups.get(code).sort((x, y) => (x.r.month < y.r.month ? 1 : -1));
    const latest = items[0];
    const s = strongRate_(latest.p.a, latest.p.b, latest.p.per);
    // Every month is written in the latest one's direction, so the changes compare like with like.
    const shown = (it) => (s && s.one === it.p.a ? it.p.per : 1 / it.p.per);
    const open = ratesOpen_.has(code);
    const group = document.createElement("div");
    group.className = "rates-group";
    group.dataset.currency = code;
    const head = document.createElement("div");
    head.className = "recurring-row rates-group-head";
    head.setAttribute("role", "button");
    head.setAttribute("aria-expanded", open ? "true" : "false");
    head.innerHTML = `
      <div>
        <div class="recurring-row-name">${findCurrency(code).flag} ${escapeHtml(code)}</div>
        <div class="recurring-row-sub">${escapeHtml(tr(items.length === 1 ? "rates.groupSubOne" : "rates.groupSub", { month: monthWords(latest.r.month), n: items.length }))}</div>
      </div>
      <div class="recurring-row-amount"><span class="rates-num">${escapeHtml(s ? rateLine2_(s.one, s.other, s.rate) : "")}</span> <span class="rates-chevron" aria-hidden="true">${open ? "⌄" : "›"}</span></div>`;
    head.addEventListener("click", () => {
      if (ratesOpen_.has(code)) ratesOpen_.delete(code); else ratesOpen_.add(code);
      refreshExchangeRatesFromCache_();
    });
    group.appendChild(head);
    if (open) {
      const box = document.createElement("div");
      box.className = "rates-history";
      const limit = ratesAll_.has(code) ? items.length : Math.min(items.length, 12);
      items.slice(0, limit).forEach((it, k) => {
        const older = items[k + 1];
        const v = shown(it);
        let change = "";
        if (older) {
          const pct = (v / shown(older) - 1) * 100;
          const t = Math.abs(pct) < 0.05 ? "=" : `${pct > 0 ? "+" : "−"}${Math.abs(pct).toFixed(1)}%`;
          change = `<span class="rates-change${Math.abs(pct) > 10 ? " rates-jump" : ""}" aria-label="${escapeHtml(tr("rates.changeAria"))}">${t}</span>`;
        }
        const row = document.createElement("div");
        row.className = "rates-month-row";
        row.innerHTML = `<span class="rates-month-name">${escapeHtml(monthWords(it.r.month))}</span>
          <span class="rates-month-rate rates-num">${escapeHtml(s ? rateLine2_(s.one, s.other, v) : "")}</span>${change || "<span></span>"}`;
        row.addEventListener("click", async () => {
          const newRate = await openRateModal(it.r.currency, it.r.month, /* required */ false, usd && it.r.per_usd > 0 ? it.r.per_usd : it.r.rate);
          if (newRate != null) refreshExchangeRates();
        });
        box.appendChild(row);
      });
      if (limit < items.length) {
        const more = document.createElement("button");
        more.type = "button";
        more.className = "add-inline rates-older-btn";
        more.textContent = tr("rates.showOlder", { n: items.length - limit });
        more.addEventListener("click", () => { ratesAll_.add(code); refreshExchangeRatesFromCache_(); });
        box.appendChild(more);
      }
      group.appendChild(box);
    }
    list.appendChild(group);
  });
  offerExchangeTip_();   // only now that everything has arrived (loading standard)
}

// ---- Rates against the US dollar (backend RatesUsd.gs, release B of the rates plan) ----
// The owner's copy is offered the conversion until it is done; the preview lists every rate before → after and every month whose
// expenses would read differently, and nothing is saved before "Store them against the dollar".
function renderRatesUsdOffer_(rates) {
  const box = document.getElementById("rates-usd-offer");
  box.hidden = !(((meta && meta.capabilities) || {}).ratesUsdConvert && !ratesUsdOn_() && rates.length);
}
function ratesUsdClose_() { document.getElementById("rates-usd-modal-backdrop").hidden = true; }
async function openRatesUsdPreview_() {
  const backdrop = document.getElementById("rates-usd-modal-backdrop"), body = document.getElementById("rates-usd-body");
  const actions = document.getElementById("rates-usd-actions");
  body.innerHTML = loadingHtml_();
  document.getElementById("rates-usd-rows").innerHTML = "";
  actions.hidden = true;
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
  let p;
  try { p = await callApi("previewRatesToUsd", {}); } catch (err) { body.innerHTML = `<p class="charge-line-error">${escapeHtml(err.message)}</p>`; return; }
  if (backdrop.hidden) return;
  if (p.done) { meta.settings.rate_base = "USD"; meta.settings.rate_form = "per_base"; ratesUsdClose_(); refreshExchangeRates(); return; }
  if (p.needsUsd) { body.innerHTML = `<p class="hint">${escapeHtml(tr("ratesUsd.needsUsd"))}</p>`; return; }
  const before = (b) => (b && strongRateLine_(b.currency, homeCur(), b.rate)) || "—";
  const rows = p.rows.map((r) => `
    <div class="rates-usd-row">
      <div class="rates-usd-row-name">${findCurrency(r.currency).flag} ${escapeHtml(r.currency)} <span class="hint">${escapeHtml(r.month)}</span></div>
      <div class="rates-usd-row-was">${escapeHtml(before(r.before))}</div>
      <div class="rates-usd-row-now">→ ${escapeHtml(strongRateLine_("USD", r.currency, r.per_usd))}</div>
    </div>`).join("");
  const months = p.months.length
    ? p.months.map((m) => {
        const [y, mo] = m.month.split("-").map(Number);
        return `<div class="rates-usd-month"><span>${escapeHtml(I18n.fmtMonthYear(new Date(y, mo - 1, 1), true))}</span><span>${escapeHtml(tr("ratesUsd.monthLine", { cur: p.main, before: moneyFmt(m.before), after: moneyFmt(m.after), n: m.entries }))}</span></div>`;
      }).join("")
    : `<p class="hint">${escapeHtml(tr("ratesUsd.noMonths"))}</p>`;
  // The buttons come before the (long) list of rates, so the choice never needs a scroll to the bottom.
  body.innerHTML = `
    <p class="hint">${escapeHtml(tr("ratesUsd.previewIntro"))}</p>
    <h3>${escapeHtml(tr("ratesUsd.monthsTitle"))}</h3>${months}
    <p class="hint">${escapeHtml(tr("ratesUsd.backupNote"))}</p>`;
  document.getElementById("rates-usd-rows").innerHTML = `<h3>${escapeHtml(tr("ratesUsd.rowsTitle", { n: p.rows.length }))}</h3>${rows}`;
  actions.hidden = false;
}
document.getElementById("rates-usd-preview-btn").addEventListener("click", openRatesUsdPreview_);
document.getElementById("rates-usd-modal-close").addEventListener("click", ratesUsdClose_);
document.getElementById("rates-usd-cancel").addEventListener("click", ratesUsdClose_);
document.getElementById("rates-usd-apply").addEventListener("click", () => {
  ratesUsdClose_();
  saveBehindScreen_(async () => {
    await callApi("convertRatesToUsd", {});
    meta.settings.rate_base = "USD";
    meta.settings.rate_form = "per_base";
    knownRateMonths_.clear();
  }, async () => {
    refreshExchangeRates();
    refreshHomeGlance_(true);   // amounts in a third currency now go through the dollar
    refreshEntryList().catch(() => {});
  });
});

// ---- Accounts & cards (More tab) ----
// The list reads meta.paymentMethods (already loaded for the entry form), and a
// save updates meta in place, so nothing is re-fetched. Cards show only the
// last 4 digits — the app never asks for a full number.

// "transfer" is not offered for a new account any more (owner, 2026-11-02); an account that already has it keeps it.
const PM_TYPES_ = ["credit", "debit", "cash", "wallet"];
// The built-in Cash account every copy has (backend ensureCashAccount_): renamed freely, never deleted, hidden or retyped.
function isBasicCashPm_(pm) { const id = String((meta && meta.settings && meta.settings.cash_account_id) || ""); return !!pm && !!id && String(pm.id) === id; }
// One Delete that hides an account with history (backend removePaymentMethod); an older backend keeps Delete + Hide.
function pmRemoveOne_() { return !!(meta && meta.capabilities && meta.capabilities.pmRemove); }
function pmBulkRemove_() { return pmRemoveOne_() && !!(meta && meta.capabilities && meta.capabilities.pmBulkRemove); }
let accountsHiddenOpen_ = false; // the "Hidden accounts" group on the accounts screen starts collapsed
let pmModalState = null; // { id } while the window is open; id is null when adding

function showAccountsScreen() {
  document.querySelectorAll(".screen").forEach((el) => { el.hidden = el.id !== "screen-accounts"; });
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.screen === "more");
  });
  renderAccountsList_();
  // The list is built from what the phone already holds (nothing to wait for): offer the first-use practices, Accounts first
  // (Investments is offered only once the Accounts one was seen, so the two cards never show together).
  offerAccountsTip_();
  offerInvestmentsTip_();
  refreshAccountSuggestions_();
}

// Suggested currencies for older accounts (owner, 2026-11-06): shown once they have arrived, editable, and nothing is saved until Apply.
// "Not now" hides it until the screen is next opened. Only the owner's copy gets any rows.
async function refreshAccountSuggestions_() {
  const card = document.getElementById("accounts-suggest-card");
  let finished = false;
  try { finished = localStorage.getItem("accountCurSuggestDone") === "1"; } catch (err) { /* private mode */ }
  if (finished || !((meta && meta.capabilities) || {}).accountCurrencySuggest || Spotlight.isRunning()) { card.hidden = true; return; }
  let res;
  try { res = await callApi("getAccountCurrencySuggestions", {}); } catch (err) { card.hidden = true; return; }
  if (!res.accounts.length || document.getElementById("screen-accounts").hidden) { card.hidden = true; return; }
  const picked = {};
  card.innerHTML = `<h2 style="margin-top:0;">${escapeHtml(tr("acur.title"))}</h2><p class="hint">${escapeHtml(tr("acur.hint"))}</p>`;
  res.accounts.forEach((a) => {
    picked[a.id] = a.proposed.slice();
    const row = document.createElement("div");
    row.className = "acur-row";
    const share = Object.keys(a.counts).sort((x, y) => a.counts[y] - a.counts[x]).map((c) => `${c} ${Math.round(a.counts[c] / a.total * 100)}%`).join(", ");
    const why = a.source === "name" ? tr("acur.fromName") : a.source === "entries" ? tr("acur.fromEntries", { n: a.total, list: share }) : tr("acur.none", { n: a.total });
    row.innerHTML = `<div class="acur-name">${escapeHtml(a.nickname)}</div><div class="hint">${escapeHtml(why)}</div><div class="acur-ticks"></div>`;
    const codes = [...new Set([...a.proposed, ...Object.keys(a.counts), homeCur(), "USD"])];
    codes.forEach((c) => {
      const label = document.createElement("label");
      label.className = "checkbox-row";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.checked = a.proposed.includes(c);
      input.addEventListener("change", () => { picked[a.id] = input.checked ? [...picked[a.id], c] : picked[a.id].filter((x) => x !== c); });
      const text = document.createElement("span");
      text.textContent = `${findCurrency(c).flag} ${c}`;
      label.appendChild(input);
      label.appendChild(text);
      row.querySelector(".acur-ticks").appendChild(label);
    });
    card.appendChild(row);
  });
  const apply = document.createElement("button");
  apply.type = "button";
  apply.className = "primary";
  apply.id = "accounts-suggest-apply";
  apply.textContent = tr("acur.apply");
  apply.addEventListener("click", () => {
    card.hidden = true;
    try { localStorage.setItem("accountCurSuggestDone", "1"); } catch (err) { /* private mode */ }   // (accounts left empty are not asked about again)
    const items = Object.keys(picked).filter((id) => picked[id].length).map((id) => ({ id, currencies: picked[id] }));
    saveBehindScreen_(() => callApi("applyAccountCurrencySuggestions", { items }), async () => { await loadMeta(); renderAccountsList_(); });
  });
  const later = document.createElement("button");
  later.type = "button";
  later.className = "add-inline";
  later.textContent = tr("acur.notNow");
  later.addEventListener("click", () => { card.hidden = true; });
  card.appendChild(apply);
  card.appendChild(later);
  card.hidden = false;
}

function renderAccountsList_() {
  const list = document.getElementById("accounts-list");
  const bankName = (id) => { const b = (meta.banks || []).find((x) => x.id === id); return b ? b.name : ""; };
  const rows = meta.paymentMethods.slice().sort((a, b) => a.nickname.localeCompare(b.nickname));
  document.getElementById("accounts-empty-note").hidden = rows.length > 0;
  const selectable = rows.filter((pm) => !isBasicCashPm_(pm));
  document.getElementById("accounts-edit-btn").hidden = !(pmBulkRemove_() && selectable.length);
  if (accountsEditing_ && !selectable.length) setAccountsEditing_(false, false);
  const stillThere = new Set(selectable.map((pm) => pm.id));
  accountsSelected_ = new Set([...accountsSelected_].filter((id) => stillThere.has(id)));
  list.innerHTML = "";
  fillBankNote_(document.getElementById("accounts-bank-note"), rows.filter((pm) => pm.type === "credit" || pm.type === "debit").map((pm) => bankName(pm.bank_id)));
  // Three groups (owner, 2026-10-19): bank accounts + credit cards, wallets + cash + transfer, investment platforms.
  const groupOf = (pm) => (pm.type === "investment" ? "platform" : pm.type === "credit" || pm.type === "debit" ? "bank" : "wallet");
  const addRow_ = (pm, parent) => {
    const row = document.createElement("div");
    const isCash = isBasicCashPm_(pm);   // the built-in Cash can never be deleted or hidden: no checkbox in Edit mode
    row.className = "recurring-row" + (pmHidden_(pm) ? " inactive" : "") + (accountsEditing_ ? " friends-check-row" : "");
    delKey_(row, "pm:" + pm.id);
    const sub = [tr(`accounts.type.${pm.type}`), bankName(pm.bank_id)].filter(Boolean).join(" · ");
    const lead = !accountsEditing_ ? ""
      : isCash ? `<span class="friends-check-spacer"></span>`
      : `<input type="checkbox" class="friends-check" tabindex="-1" aria-hidden="true"${accountsSelected_.has(pm.id) ? " checked" : ""}>`;
    row.innerHTML = `
      ${lead}
      <div>
        <div class="recurring-row-name">${escapeHtml(pm.nickname)}</div>
        <div class="recurring-row-sub">${escapeHtml(sub)}</div>
      </div>
      <div class="recurring-row-amount">${pm.last_4 ? escapeHtml(tr("accounts.digits", { last4: pm.last_4 })) : ""}</div>
    `;
    row.addEventListener("click", () => {
      if (!accountsEditing_) { openPmModal_(pm); return; }   // Edit mode: a tap ticks instead of opening
      if (isCash) return;
      const { next, switched } = tickOneKind_(accountsSelected_, pm.id, accountTickHidden_);
      accountsSelected_ = next;
      if (switched) { renderAccountsList_(); return; }
      row.querySelector(".friends-check").checked = accountsSelected_.has(pm.id);
      syncAccountsEditBar_();
    });
    parent.appendChild(row);
  };
  ["bank", "wallet", "platform"].forEach((g) => rows.filter((pm) => !pmHidden_(pm) && groupOf(pm) === g).forEach((pm, i) => {
    if (i === 0) {
      const head = document.createElement("h3");
      head.className = "accounts-group-title";
      head.textContent = tr(`accounts.group.${g}`);
      list.appendChild(head);
    }
    addRow_(pm, list);
  }));
  // Hidden accounts live in their own collapsed group at the bottom (owner, 2026-10-23).
  const hiddenRows = rows.filter(pmHidden_);
  if (hiddenRows.length) {
    const head = document.createElement("button");
    head.type = "button";
    head.className = "accounts-group-title accounts-hidden-toggle";
    const box = document.createElement("div");
    box.hidden = !accountsHiddenOpen_ && !accountsEditing_;
    const paint = () => { const open = accountsHiddenOpen_ || accountsEditing_; head.textContent = `${open ? "▾" : "▸"} ${tr("accounts.group.hidden")} (${hiddenRows.length})`; };
    head.addEventListener("click", () => { if (accountsEditing_) return; accountsHiddenOpen_ = !accountsHiddenOpen_; box.hidden = !accountsHiddenOpen_; paint(); });   // (every account stays reachable while Edit is on)
    paint();
    hiddenRows.forEach((pm) => addRow_(pm, box));
    list.appendChild(head);
    list.appendChild(box);
  }
  syncAccountsEditBar_();
}

function fillPmBankOptions_(selectedId) {
  const sel = document.getElementById("pm-bank");
  sel.innerHTML = "";
  const none = document.createElement("option");
  none.value = "";
  none.textContent = tr("accounts.noBank");
  sel.appendChild(none);
  (meta.banks || []).slice().sort((a, b) => a.name.localeCompare(b.name)).forEach((b) => {
    const o = document.createElement("option");
    o.value = b.id;
    o.textContent = b.name;
    sel.appendChild(o);
  });
  const add = document.createElement("option");
  add.value = "__add__";
  add.textContent = tr("accounts.addBank");
  sel.appendChild(add);
  sel.value = selectedId || "";
}

function openPmModal_(pm) {
  const linked = (meta && meta.settings) || {};
  pmModalState = { id: pm ? pm.id : null, lastBank: pm ? pm.bank_id || "" : "",
    wallets: pm ? ["yape_pen", "yape_usd", "plin_pen"].filter((k) => String(linked[k] || "") === String(pm.id) || (k === "plin_pen" && plinMoreIds_().includes(String(pm.id)))) : [], kind: pm ? pm.alias_kind || "" : "" };
  document.getElementById("pm-modal-title").textContent = tr(pm ? "accounts.editTitle" : "accounts.addTitle");
  const typeSel = document.getElementById("pm-type");
  typeSel.innerHTML = "";
  // "Investment platform" is offered to everyone (a copy that skipped the welcome step has no other way to add a platform).
  const types = [...PM_TYPES_, ...(pm && pm.type === "transfer" ? ["transfer"] : []), "investment"];
  types.forEach((t) => {
    const o = document.createElement("option");
    o.value = t;
    o.textContent = tr(`accounts.type.${t}`);
    typeSel.appendChild(o);
  });
  typeSel.value = pm ? pm.type : "credit";
  pmModalState.cur = kindCurrency_(pmModalState.kind);
  pmModalState.currencies = pm ? accountCurrencyList_(pm) : null;   // (an existing account shows what it has, even nothing; a new one starts on a default)
  const basicCash = isBasicCashPm_(pm);
  typeSel.disabled = basicCash;
  document.getElementById("pm-cash-hint").hidden = !basicCash;
  // A wallet tied to a bank account must not be added as a wallet: the bank account behind it is the account (owner's rule, 2026-10-18).
  const walletWarn = () => { document.getElementById("pm-wallet-warning").hidden = typeSel.value !== "wallet"; };
  typeSel.onchange = () => { if (!pmModalState.id) pmModalState.currencies = null; walletWarn(); renderPmCurrency_(); renderPmWallets_(); };
  walletWarn();
  renderPmCurrency_();
  document.getElementById("pm-nickname").value = pm ? pm.nickname : "";
  document.getElementById("pm-last4").value = pm ? pm.last_4 || "" : "";
  fillPmBankOptions_(pmModalState.lastBank);
  renderPmWallets_();
  document.getElementById("pm-form-error").textContent = "";
  // Delete only exists for an account that is already saved, and never for the built-in Cash. One Delete decides by itself
  // (unused = deleted, with history = hidden); the other button only shows to bring a hidden account back (or on an older backend).
  document.getElementById("pm-manage").hidden = !pm || basicCash;
  if (pm) {
    const one = pmRemoveOne_();
    const hideBtn = document.getElementById("pm-hide-btn");
    hideBtn.hidden = one && !pmHidden_(pm);
    hideBtn.textContent = tr(pmHidden_(pm) ? "accounts.show" : "accounts.hide");
    document.getElementById("pm-manage-hint").textContent = tr(one ? "accounts.deleteHint" : "accounts.hideHint");
  }
  const backdrop = document.getElementById("pm-modal-backdrop");
  bringModalToFront_(backdrop);
  guidedLift_(backdrop);
  backdrop.hidden = false;
  if (!pm) document.getElementById("pm-nickname").focus();
}

// The account's currency (2026-11-04): a savings / debit / salary account names one (the main one by default); a card is soles and
// dollars unless it is in one currency only. Only on a backend that stores it (capability accountCurrencyEdit).
function renderPmCurrency_() {
  if (!pmModalState) return;
  const type = document.getElementById("pm-type").value;
  const box = document.getElementById("pm-cur-box");
  box.hidden = !((meta && meta.capabilities) || {}).accountCurrencyEdit || (type !== "debit" && type !== "credit");
  if (box.hidden) return;
  const sel = document.getElementById("pm-currency");
  if (accountListOn_()) {
    sel.hidden = true;
    const label = document.getElementById("pm-cur-label");
    label.textContent = tr("accounts.currencies");
    label.removeAttribute("for");
    if (!pmModalState.currencies) pmModalState.currencies = type === "credit" ? [...new Set([homeCur(), "USD"])] : [homeCur()];
    const codes = [...new Set([homeCur(), ...getRecentCurrencies(), ...CURRENCIES.map((c) => c.code)])];
    renderCurrencyChecks_(document.getElementById("pm-cur-checks"), codes, pmModalState.currencies, (list) => { pmModalState.currencies = list; renderPmWallets_(); });
    return;
  }
  sel.innerHTML = "";
  if (type === "credit") { const o = document.createElement("option"); o.value = ""; o.textContent = tr("accounts.curTwo"); sel.appendChild(o); }
  const codes = [...new Set([homeCur(), ...getRecentCurrencies(), ...CURRENCIES.map((c) => c.code)])];
  codes.forEach((c) => { const o = document.createElement("option"); o.value = c; o.textContent = `${findCurrency(c).flag} ${c} — ${tr("currency." + c)}`; sel.appendChild(o); });
  const was = pmModalState.cur || "";
  sel.value = type === "credit" ? (/^credit_/.test(pmModalState.kind || "") ? was : "") : (was || homeCur());
}
function pmKindNow_() {
  const type = document.getElementById("pm-type").value;
  if (accountListOn_()) {   // (only chooses the wallet boxes now: several or none offer what the account's type allows)
    const list = pmModalState.currencies || [];
    return list.length === 1 ? (type === "credit" ? `credit_${list[0].toLowerCase()}` : `debit_${list[0].toLowerCase()}`) : type;
  }
  const cur = document.getElementById("pm-cur-box").hidden ? "" : document.getElementById("pm-currency").value;
  if (type === "credit") return cur ? `credit_${cur.toLowerCase()}` : "credit";
  if (type === "debit") return /^sueldo/.test(pmModalState.kind || "") ? (cur === "PEN" ? "sueldo" : `sueldo_${cur.toLowerCase()}`) : `debit_${(cur || homeCur()).toLowerCase()}`;
  return pmModalState.kind || "";
}
document.getElementById("pm-currency").addEventListener("change", (e) => {
  if (!pmModalState) return;
  pmModalState.cur = e.target.value;
  pmModalState.kind = pmKindNow_();
  renderPmWallets_();
});

// Wallet boxes of the account window: which of Yape / Plin ride on this account (Settings yape_pen, yape_usd, plin_pen).
// Saved together with the account, so a new account can be ticked before it has an id.
function pmBankName_() {
  const b = (meta.banks || []).find((x) => x.id === document.getElementById("pm-bank").value);
  return b ? b.name : "";
}
function pmWalletSlots_() { return walletSlots_(pmBankName_(), document.getElementById("pm-type").value, document.getElementById("pm-cur-box").hidden ? pmModalState.kind : pmKindNow_()); }
function renderPmWallets_() {
  if (!pmModalState) return;
  const slots = pmWalletSlots_();
  document.getElementById("pm-wallets").hidden = !slots.length;
  const settings = (meta && meta.settings) || {};
  renderWalletBoxes_(document.getElementById("pm-wallet-boxes"), slots, pmModalState.wallets, (key, on) => {
    if (!on) { pmModalState.wallets = pmModalState.wallets.filter((k) => k !== key); return; }
    const holder = key === "plin_pen" && plinManyOn_() ? "" : String(settings[key] || "");   // (several accounts can have Plin: nothing to move)
    const other = holder && holder !== String(pmModalState.id) && meta.paymentMethods.find((p) => String(p.id) === holder);
    if (other && !confirm(tr("wallets.replace", { wallet: tr(`wa.rail.${key}`), name: other.nickname }))) return false;
    pmModalState.wallets.push(key);
  });
}

function closePmModal_() {
  document.getElementById("pm-modal-backdrop").hidden = true;
  pmModalState = null;
}

document.getElementById("pm-bank").addEventListener("change", async (e) => {
  if (!pmModalState) return;
  if (e.target.value !== "__add__") { pmModalState.lastBank = e.target.value; renderPmWallets_(); return; }
  const name = await askName_(tr("accounts.bankPrompt"));
  if (!pmModalState) return;
  if (!name || !name.trim()) { e.target.value = pmModalState.lastBank; return; }
  try {
    const bank = await callApi("addBank", { name: name.trim() });
    if (!meta.banks.some((b) => b.id === bank.id)) meta.banks.push(bank);
    pmModalState.lastBank = bank.id;
    fillPmBankOptions_(bank.id);
    renderPmWallets_();
  } catch (err) {
    document.getElementById("pm-form-error").textContent = err.message;
    e.target.value = pmModalState.lastBank;
  }
});

document.getElementById("pm-last4").addEventListener("input", (e) => {
  const digits = e.target.value.replace(/\D/g, "").slice(0, 4);
  if (digits !== e.target.value) e.target.value = digits;
});

document.getElementById("pm-save-btn").addEventListener("click", async () => {
  if (!pmModalState) return;
  const errorEl = document.getElementById("pm-form-error");
  errorEl.textContent = "";
  const nickname = document.getElementById("pm-nickname").value.trim();
  const last4 = document.getElementById("pm-last4").value.trim();
  if (!nickname) { errorEl.textContent = tr("accounts.errName"); return; }
  if (last4 && !/^\d{4}$/.test(last4)) { errorEl.textContent = tr("accounts.errLast4"); return; }
  // Plin and Yape are wallets that ride on a bank account (owner, 2026-10-23): Plin is never an account, Yape alone asks first.
  const plain = (t) => t.normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
  const before = pmModalState.id && meta.paymentMethods.find((p) => p.id === pmModalState.id);
  const renamed = !before || plain(before.nickname) !== plain(nickname);
  if (renamed && plain(nickname) === "plin") { errorEl.textContent = tr("wallets.plinNotAccount"); return; }
  if (renamed && plain(nickname) === "yape" && !confirm(tr("wallets.yapeAlone"))) return;
  // Closes at once and saves behind the screen (a refusal, such as a repeated name, comes back as an alert).
  const state = { id: pmModalState.id, wallets: pmModalState.wallets, selectIn: pmModalState.selectIn || "" };
  const type = document.getElementById("pm-type").value;
  const bankId = document.getElementById("pm-bank").value === "__add__" ? "" : document.getElementById("pm-bank").value;
  const slotsNow = pmWalletSlots_();
  const curField = document.getElementById("pm-cur-box").hidden ? {} : accountListOn_() ? { currencies: pmModalState.currencies || [] } : { currency: document.getElementById("pm-currency").value };
  closePmModal_();
  saveBehindScreen_(practiceATrack_(practiceITrack_(async () => {
    const saved = await callApi("savePaymentMethod", {
      id: state.id || undefined,
      nickname,
      type,
      bank_id: bankId,
      last_4: last4,
      ...curField
    });
    const i = meta.paymentMethods.findIndex((p) => p.id === saved.id);
    if (i >= 0) meta.paymentMethods[i] = { ...meta.paymentMethods[i], ...saved };
    else meta.paymentMethods.push(saved);
    // Wallet links: ticked slots point at this account; slots it no longer offers (or that were unticked) are released.
    const slots = slotsNow, settings = meta.settings || (meta.settings = {}), links = {};
    const id = String(saved.id), plinMany = plinManyOn_(), more = plinMoreIds_();
    ["yape_pen", "yape_usd", "plin_pen"].forEach((k) => {
      if (k === "plin_pen" && plinMany) {
        const main = String(settings.plin_pen || ""), want = slots.includes(k) && state.wallets.includes(k);
        if (want && !main) links.plin_pen = id;
        else if (want && main !== id && !more.includes(id)) links.plin_pen_more = [...more, id].join(",");
        else if (!want && main === id) { links.plin_pen = more[0] || ""; links.plin_pen_more = more.slice(1).join(","); }   // the next one becomes the main one
        else if (!want && more.includes(id)) links.plin_pen_more = more.filter((x) => x !== id).join(",");
        return;
      }
      if (slots.includes(k) && state.wallets.includes(k)) { if (String(settings[k] || "") !== String(saved.id)) links[k] = saved.id; }
      else if (String(settings[k] || "") === String(saved.id)) links[k] = "";
    });
    if (Object.keys(links).length) { await callApi("saveRailLinks", links); Object.assign(settings, links); }
    // Rebuild the entry form's pickers without losing what's already chosen there.
    const keep = ["payment_method", "to_payment_method"].map((id) => document.getElementById(id).value);
    populatePaymentMethodOptions();
    populateToPaymentMethodOptions();
    ["payment_method", "to_payment_method"].forEach((id, k) => {
      const sel = document.getElementById(id);
      if (keep[k] && Array.from(sel.options).some((o) => o.value === keep[k])) sel.value = keep[k];
    });
    if (state.selectIn) { const sel = document.getElementById(state.selectIn); sel.value = saved.id; sel.dispatchEvent(new Event("change")); }
  }, { nickname, type }), nickname), () => renderAccountsList_());
});

// After a hide / show / delete the pickers are rebuilt the same way a save does it.
function refreshAccountPickers_() {
  const keep = ["payment_method", "to_payment_method"].map((id) => document.getElementById(id).value);
  populatePaymentMethodOptions();
  populateToPaymentMethodOptions();
  ["payment_method", "to_payment_method"].forEach((id, k) => {
    const sel = document.getElementById(id);
    if (keep[k] && Array.from(sel.options).some((o) => o.value === keep[k])) sel.value = keep[k];
  });
}

document.getElementById("pm-hide-btn").addEventListener("click", async () => {
  if (!pmModalState || !pmModalState.id) return;
  const errorEl = document.getElementById("pm-form-error");
  errorEl.textContent = "";
  const pm = meta.paymentMethods.find((p) => p.id === pmModalState.id);
  if (!pm) return;
  try {
    const res = await callApi("setPaymentMethodHidden", { id: pm.id, hidden: !pmHidden_(pm) });
    pm.hidden = res.hidden;
    refreshAccountPickers_();
    closePmModal_();
    renderAccountsList_();
  } catch (err) { errorEl.textContent = err.message; }
});

document.getElementById("pm-delete-btn").addEventListener("click", async () => {
  if (!pmModalState || !pmModalState.id) return;
  const errorEl = document.getElementById("pm-form-error");
  errorEl.textContent = "";
  const pm = meta.paymentMethods.find((p) => p.id === pmModalState.id);
  const one = pmRemoveOne_();
  if (!pm || (!practiceNoConfirm_(isPracticeAccountName_(pm.nickname)) && !confirm(tr(one ? "accounts.confirmRemove" : "accounts.confirmDelete", { name: pm.nickname })))) return;
  // Saving standard: back to the list at once; the account's row says "Deleting…" until the server is done.
  markDeleting_("pm:" + pm.id);
  closePmModal_();
  if (practiceA_ && isPracticeAccountName_(pm.nickname)) { practiceA_.deleted = true; practiceASave_(); }   // (the first-use practice's last real step: counts from the tap)
  try {
    const res = await callApi(one ? "removePaymentMethod" : "deletePaymentMethod", { id: pm.id });
    if (res && res.hidden === "yes") {
      // It has history: hidden instead (its past entries keep it), like a friend with history.
      unmarkDeleting_("pm:" + pm.id);
      pm.hidden = "yes";
      showToast_(tr("accounts.hiddenInstead", { name: pm.nickname }));
    } else {
      meta.paymentMethods = meta.paymentMethods.filter((p) => p.id !== pm.id);
    }
    refreshAccountPickers_();
    renderAccountsList_();
  } catch (err) {
    unmarkDeleting_("pm:" + pm.id);
    alert(err.message);   // in use: the message says so and points to Hide
  }
});

// ---- Accounts: Edit mode (tick several accounts, delete them at once; owner's request, 2026-11-03) ----
// The same pencil, checkboxes and fixed bar as Friends / Programmed items / Budgets. Delete asks ONE question for the whole batch; the server then
// applies the single Delete's rule to each account (removePaymentMethods): unused → deleted, with history → hidden (its records keep it), the built-in
// Cash and the ones linked to Yape / Plin are left as they are. The result names everyone.
function setAccountsEditing_(on, redraw = true) {
  if (on === accountsEditing_ && redraw) return;
  accountsEditing_ = on;
  accountsSelected_ = new Set();
  setEditIcon_(document.getElementById("accounts-edit-btn"), on);
  document.getElementById("accounts-add-btn").hidden = on;
  document.getElementById("accounts-editbar").hidden = !on;
  document.getElementById("screen-accounts").classList.toggle("accounts-editing", on);
  placeAccountsEditBar_();
  if (redraw) renderAccountsList_();
}
function placeAccountsEditBar_() {
  const nav = document.getElementById("bottom-nav");
  if (nav && nav.offsetHeight) document.getElementById("accounts-editbar").style.bottom = nav.offsetHeight + "px";
}
window.addEventListener("resize", () => { if (accountsEditing_) placeAccountsEditBar_(); });
// Only where the backend can show accounts again in bulk is a hidden account a different kind of tick (otherwise it is one more account to delete).
const accountTickHidden_ = (id) => { const pm = ((meta && meta.paymentMethods) || []).find((x) => x.id === id); return bulkShowAgain_() && !!pm && pmHidden_(pm); };
const accountsSelectable_ = () => ((meta && meta.paymentMethods) || []).filter((pm) => !isBasicCashPm_(pm));
function syncAccountsEditBar_() {
  const n = accountsSelected_.size;
  const hiddenKind = n > 0 && [...accountsSelected_].some(accountTickHidden_);
  syncOneKindBar_(document.getElementById("accounts-delete-selected-btn"), document.getElementById("accounts-selectall-btn"), n, hiddenKind,
    hiddenKind ? accountsSelectable_().filter((pm) => accountTickHidden_(pm.id)).length : bulkShowAgain_() ? accountsSelectable_().filter((pm) => !pmHidden_(pm)).length : accountsSelectable_().length);
}
document.getElementById("accounts-edit-btn").addEventListener("click", () => setAccountsEditing_(!accountsEditing_));
document.getElementById("accounts-done-btn").addEventListener("click", () => setAccountsEditing_(false));
document.getElementById("accounts-back-btn").addEventListener("click", () => setAccountsEditing_(false));
document.getElementById("accounts-selectall-btn").addEventListener("click", () => {
  const sel = accountsSelectable_();
  accountsSelected_ = selectAllOneKind_(accountsSelected_, sel.filter((pm) => !accountTickHidden_(pm.id)).map((pm) => pm.id), sel.filter((pm) => accountTickHidden_(pm.id)).map((pm) => pm.id), accountTickHidden_);
  renderAccountsList_();
});
function showAccountsAgainFlow_(chosen) {
  const ids = chosen.map((pm) => pm.id);
  dropUndoKind_("accounts");
  let result = null;
  saveBehindScreen_(async () => {
    result = await callApi("restorePaymentMethods", { show: ids });
    meta.paymentMethods.forEach((pm) => { if (ids.includes(pm.id)) pm.hidden = ""; });
    refreshAccountPickers_();
  }, renderAccountsList_, {
    busy: "bulkShow.busy",
    done: () => result ? tr("bulkShow.done", { n: result.shown, names: shortNames_(chosen.map((pm) => pm.nickname)) }) : "",
  });
}
document.getElementById("accounts-delete-selected-btn").addEventListener("click", () => {
  const picked = meta.paymentMethods.filter((pm) => accountsSelected_.has(pm.id)).sort((a, b) => a.nickname.localeCompare(b.nickname));
  if (picked.length && picked.every((pm) => accountTickHidden_(pm.id))) { setAccountsEditing_(false); showAccountsAgainFlow_(picked); return; }
  const chosen = picked;
  if (!chosen.length) return;
  const names = chosen.map((pm) => pm.nickname).join(", ");
  if (!confirm(tr(chosen.length === 1 ? "accounts.confirmRemove" : "accounts.confirmDeleteMany", { n: chosen.length, names, name: names }))) return;
  const ids = chosen.map((pm) => pm.id);
  setAccountsEditing_(false);
  const delKeys = ids.map((id) => "pm:" + id);
  delKeys.forEach(markDeleting_);
  let result = null;
  saveBehindScreen_(async () => {
    result = await callApi("removePaymentMethods", { ids });
    const gone = new Set(result.deleted.map((d) => d.id));
    const hid = new Set(result.hidden.map((h) => h.id));
    meta.paymentMethods = meta.paymentMethods.filter((pm) => !gone.has(pm.id));
    meta.paymentMethods.forEach((pm) => { if (hid.has(pm.id)) pm.hidden = "yes"; });
    refreshAccountPickers_();
  }, async () => {
    renderAccountsList_();
    if (!result) return;
    const by = (reason) => result.kept.filter((k) => k.reason === reason).map((k) => k.name).filter(Boolean);
    const other = result.kept.filter((k) => k.reason === "cash" || k.reason === "missing").map((k) => k.name).filter(Boolean);
    const deletedRows = result.deletedRows || { accounts: [], balances: [] };
    const canUndo = bulkShowAgain_() && (result.hidden.length || (deletedRows.accounts || []).length);
    if (!result.hidden.length && !result.kept.length && !canUndo) return;   // everything was simply deleted: the "done" toast names them
    if (result.kept.length || !canUndo) {   // something was left as it was: say why (the Undo toast alone would not)
      const lines = [];
      if (result.deleted.length) lines.push(tr("accounts.resultDeleted", { n: result.deleted.length, names: result.deleted.map((d) => d.name).join(", ") }));
      if (result.hidden.length) lines.push(tr("accounts.resultHidden", { names: result.hidden.map((h) => h.name).join(", ") }));
      if (by("rail").length) lines.push(tr("accounts.resultRail", { names: by("rail").join(", ") }));
      if (by("hiddenAlready").length) lines.push(tr("accounts.resultHiddenAlready", { names: by("hiddenAlready").join(", ") }));
      if (other.length) lines.push(tr("accounts.resultKept", { names: other.join(", ") }));
      alert(lines.join("\n\n"));
    }
    if (canUndo) offerBulkUndo_(result.deleted.map((d) => d.name), result.hidden.map((h) => h.name), async () => {
      const back = await callApi("restorePaymentMethods", { show: result.hidden.map((h) => h.id), rows: deletedRows });
      await loadMeta();
      refreshAccountPickers_();
      renderAccountsList_();
      showToast_(undoneText_(back.skipped));
      alertNotRestored_(back.skipped);
    }, "accounts");
  }, {
    busy: "common.deletingToast", release: delKeys,
    done: () => result && !result.hidden.length && !result.kept.length && result.deleted.length && !(bulkShowAgain_() && ((result.deletedRows || {}).accounts || []).length)
      ? tr("accounts.resultDeleted", { n: result.deleted.length, names: shortNames_(result.deleted.map((d) => d.name)) }) : "",
  });
});

document.getElementById("pm-modal-close").addEventListener("click", closePmModal_);
document.getElementById("pm-cancel-btn").addEventListener("click", closePmModal_);
document.getElementById("pm-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "pm-modal-backdrop") closePmModal_();
});
document.getElementById("more-accounts-btn").addEventListener("click", showAccountsScreen);
document.getElementById("accounts-back-btn").addEventListener("click", () => showScreen("more"));
document.getElementById("accounts-add-btn").addEventListener("click", () => openPmModal_(null));

// ---- More → Categories: create / change / hide / delete a category (top-level only, no sub-categories) ----

