// ---- Remind on WhatsApp (specs/loans.md § Reminders; the message itself is written by docs/loan-reminder.js) ----
// The person reads and edits the text, then WhatsApp opens with it; nothing is sent by the app. A number typed here is remembered on
// the friend (setFriendPhone) when the backend can; without one, WhatsApp asks which chat.
let loanRemind_ = null;

function openLoanRemind_(friendId, friendName, loans) {
  const friend = (meta.friends || []).find((f) => f.id === friendId) || {};
  const text = LoanReminder.build({ name: friendName, loans, today: todayLocalISO() });
  loanRemind_ = { friendId, text, phone: friend.phone || "" };
  document.getElementById("loan-remind-title").textContent = tr("remind.title", { name: friendName });
  document.getElementById("loan-remind-text").value = text;
  document.getElementById("loan-remind-phone").value = friend.phone || "";
  document.getElementById("loan-remind-error").textContent = "";
  document.getElementById("loan-remind-stuck").hidden = true;
  const backdrop = document.getElementById("loan-remind-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}

function closeLoanRemind_() {
  document.getElementById("loan-remind-modal-backdrop").hidden = true;
  loanRemind_ = null;
}

// Remembers a new / changed / cleared number in the background; the reminder never waits for it.
function rememberLoanRemindPhone_(phone) {
  const r = loanRemind_;
  if (!r || LoanReminder.phoneDigits(phone) === LoanReminder.phoneDigits(r.phone)) return;
  if (!((meta && meta.capabilities) || {}).friendPhone) return;
  r.phone = phone;
  callApi("setFriendPhone", { id: r.friendId, phone })
    .then((res) => {
      const f = (meta.friends || []).find((x) => x.id === r.friendId);
      if (f) f.phone = res.phone;
    })
    .catch((err) => alert(tr("common.notSaved", { error: err.message })));
}

document.getElementById("loan-remind-close").addEventListener("click", closeLoanRemind_);
document.getElementById("loan-remind-reset").addEventListener("click", () => {
  if (loanRemind_) document.getElementById("loan-remind-text").value = loanRemind_.text;
});
document.getElementById("loan-remind-send").addEventListener("click", () => {
  const text = document.getElementById("loan-remind-text").value.trim();
  const phone = document.getElementById("loan-remind-phone").value.trim();
  const error = document.getElementById("loan-remind-error");
  if (!text) { error.textContent = tr("remind.errEmpty"); return; }
  if (phone && !LoanReminder.phoneOk(phone)) { error.textContent = tr("remind.errPhone"); return; }
  error.textContent = "";
  rememberLoanRemindPhone_(phone);
  const homeScreen = isHomeScreenApp_();
  const url = LoanReminder.whatsappUrl(phone, text, homeScreen);
  if (!homeScreen) { window.open(url, "_blank", "noopener"); return; }
  location.href = url;
  // Still here after a moment: WhatsApp did not take over (not installed?), so point to copying the message instead.
  setTimeout(() => { if (!document.hidden && loanRemind_) document.getElementById("loan-remind-stuck").hidden = false; }, 2000);
});
document.getElementById("loan-remind-copy").addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText(document.getElementById("loan-remind-text").value);
    showToast_(tr("remind.copied"), false, 4000);
  } catch (err) { /* not allowed: the text is still there to select by hand */ }
});

function closeLoanDetail() {
  document.getElementById("loan-detail-modal-backdrop").hidden = true;
  currentDrilldown = null;
  loanDetailScope_ = { friendId: null, projectId: "" };
  // A project screen underneath shows what is owed: it may have just changed.
  if (!document.getElementById("screen-business-detail").hidden) refreshBusinessDetail_();
  if (!document.getElementById("screen-business-people").hidden) refreshPeopleList_();
}

document.getElementById("loan-detail-modal-close").addEventListener("click", closeLoanDetail);
document.getElementById("loan-detail-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "loan-detail-modal-backdrop") closeLoanDetail();
});

// ---- Add / edit loan (Phase 5.3) ----
// A standalone cash loan — money lent/borrowed directly, not tied to any
// expense. Always lands as `origin: 'cash'` (see addLoan/updateLoan in
// Loans.gs), distinct from the loans the split-entry UI creates with
// `origin: 'entry'`, which aren't editable from here at all (see
// openLoanDetail's `editable` check, above) — those are edited by
// editing the expense itself.

let loanDirection = "they_owe_me";
let editingLoanId = null;
let loanModalApplyLoan_ = null;   // the loan being edited, kept for its "Apply to a loan" button
// Set when this modal was opened from a friend's loan-detail sheet, so a
// save/delete can refresh that sheet's contents too, not just the main
// Loans tab list underneath it.
let loanModalReturnFriend = null;

function populateLoanFriendOptions() {
  const select = document.getElementById("loan-friend");
  select.innerHTML = "";
  plainFriends_().forEach((f) => {
    const opt = document.createElement("option");
    opt.value = f.id;
    opt.textContent = friendLabel_(f);
    select.appendChild(opt);
  });
  const addOpt = document.createElement("option");
  addOpt.value = "__add__";
  addOpt.textContent = tr("common.addFriend");
  select.appendChild(addOpt);
}

document.getElementById("loan-friend").addEventListener("change", async (e) => {
  if (e.target.value !== "__add__") return;
  const name = await askName_(tr("prompt.friendName"));
  e.target.value = meta.friends.length ? meta.friends[0].id : "";
  if (name && name.trim()) {
    loanFriendAdding_ = true;   // (the first-use loan practice waits for the new friend to be picked)
    try {
      const friend = await callApi("addFriend", { name: name.trim() });
      meta.friends.push(friend);
      refreshFriendChips_();
      populateLoanFriendOptions();
      document.getElementById("loan-friend").value = friend.id;
    } finally { loanFriendAdding_ = false; }
  }
});

function populateLoanPaymentMethodOptions() {
  const select = document.getElementById("loan-payment-method");
  select.innerHTML = "";
  // Just the accounts (no platforms). A new loan starts on the top one (owner, 2026-11-05: an empty box with "Optional" was confusing); the
  // rare loan that moved through none of them says so with a named LAST choice, never an empty box.
  const accounts = meta.paymentMethods.filter((pm) => pm.type !== "investment" && !pmHidden_(pm));
  accounts.forEach((pm) => {
    const opt = document.createElement("option");
    opt.value = pm.id;
    opt.textContent = pmPickLabel_(pm);
    select.appendChild(opt);
  });
  const noneOpt = document.createElement("option");
  noneOpt.value = "";
  noneOpt.textContent = tr(accounts.length ? "loanModal.noAccount" : "form.noneAccount");
  select.appendChild(noneOpt);
}

// The "from before the app" choice: no account (nothing moved now), no automatic due date, and the date is a rough "since when".
function updateLoanOpeningUi_(fresh) {
  const on = document.getElementById("loan-opening").checked;
  document.getElementById("loan-opening-hint").hidden = !on;
  document.getElementById("loan-pm-field").hidden = on;
  const label = document.getElementById("loan-date-label");
  label.textContent = on ? tr("loanModal.openingDate") : tr("field.date");
  if (fresh) {
    const date = document.getElementById("loan-date").value;
    document.getElementById("loan-due-date").value = on ? "" : defaultDueDate_(date);
  }
}
document.getElementById("loan-opening").addEventListener("change", () => updateLoanOpeningUi_(true));

function setLoanDirection_(direction) {
  loanDirection = direction;
  document.querySelectorAll("#loan-direction-tabs .type-tab").forEach((t) => {
    t.classList.toggle("active", t.dataset.direction === direction);
  });
}

document.querySelectorAll("#loan-direction-tabs .type-tab").forEach((tab) => {
  tab.addEventListener("click", () => setLoanDirection_(tab.dataset.direction));
});

// ---- Credit card warning for money moving to or from a person (owner's request, 2026-11-01) ----
// A credit card does not normally receive money from a person or lend it to one, so picking one in the loan form, the
// repayment form or the Transfer tab's Repayment / New loan asks once ("Use it anyway?"). Cancel puts the previous account
// back. Only a pick by hand asks: an account already saved on an entry never does, and nothing is ever blocked.
function warnCreditCardPick_(select, moneyComesIn) {
  const pm = (meta.paymentMethods || []).find((p) => p.id === select.value);
  if (!pm || pm.type !== "credit") { select.dataset.prev = select.value; return; }
  if (confirm(tr(moneyComesIn ? "creditCard.warnIn" : "creditCard.warnOut", { name: pm.nickname }))) { select.dataset.prev = select.value; return; }
  select.value = select.dataset.prev || "";
}
function watchCreditCardPick_(selectId, moneyComesIn) {
  const select = document.getElementById(selectId);
  select.addEventListener("focus", () => { select.dataset.prev = select.value; });
  select.addEventListener("change", () => { if (select.value !== "__add__") warnCreditCardPick_(select, moneyComesIn()); });
}
watchCreditCardPick_("loan-payment-method", () => loanDirection === "i_owe_them");          // I borrowed: the money comes in
watchCreditCardPick_("settlement-payment-method", () => repaymentDirection === "they_owe_me");   // they pay me: it comes in
document.getElementById("payment_method").addEventListener("focus", (e) => { e.target.dataset.prev = e.target.value; });
// An account in one currency (a dollar account, a card in dollars only) sets the entry's currency when it is picked, unless the person
// already tapped a currency for this entry (2026-11-04). A card in soles and dollars, cash or a wallet changes nothing.
document.getElementById("payment_method").addEventListener("change", (e) => {
  if (entryCurrencyTouched_ || editingEntryId) return;
  const pm = (meta.paymentMethods || []).find((p) => String(p.id) === e.target.value);
  const list = accountCurrencyList_(pm), cur = list.length === 1 ? list[0] : "";
  if (cur && cur !== document.getElementById("currency").value && CURRENCIES.some((c) => c.code === cur)) selectCurrency(cur, "entry");
});
document.getElementById("payment_method").addEventListener("change", (e) => {
  if (e.target.value === "__add__" || typeof repaymentActive_ !== "function" || !repaymentActive_()) return;
  warnCreditCardPick_(e.target, repaymentDirectionChoice !== "i_owe_them");   // "I paid them" = money goes out
});

// ---- What the account really charged (owner, 2026-11-06; backend/Charges.gs) ----
// The form's box. In a currency the account does not have (ARS on a USD card) it asks what was charged; empty = the charge is pending.
// In a currency it has, a small link offers what was paid, optional. Only for an expense the person paid from a card or account with a
// known list, never during a practice.
let chargeEntry_ = null, chargeOpen_ = false, chargeLastCur_ = "";
const chargeOn_ = () => !!((meta && meta.capabilities) || {}).chargeFill;
const paidByForCharge_ = () => { const el = document.getElementById("paid_by"); return el ? el.value : "me"; };
function resetChargeBox_(entry) {
  chargeEntry_ = entry && entry.type === "expense" ? entry : null;
  chargeOpen_ = false;
  chargeLastCur_ = "";
  document.getElementById("charge-amount").value = chargeEntry_ && Number(chargeEntry_.paid_amount) > 0 ? chargeEntry_.paid_amount : "";
  document.getElementById("charge-open").hidden = true;
  document.getElementById("charge-box").hidden = true;
}
function chargeMode_() {
  if (!chargeOn_() || typeof selectedType === "undefined" || selectedType !== "expense" || Spotlight.isRunning()) return "";
  if (paidByForCharge_() !== "me") return "";
  const sel = document.getElementById("payment_method");
  const pm = sel && (meta.paymentMethods || []).find((p) => String(p.id) === String(sel.value));
  const list = accountCurrencyList_(pm);
  if (!list.length) return "";
  return { pm, list, off: !list.includes(document.getElementById("currency").value) };
}
function updateChargeBox_() {
  const mode = chargeMode_();
  const open = document.getElementById("charge-open"), box = document.getElementById("charge-box");
  if (!mode) { open.hidden = true; box.hidden = true; return; }
  const cur = document.getElementById("currency").value;
  const hasPaid = !mode.off && chargeEntry_ && Number(chargeEntry_.paid_amount) > 0;
  const showBox = mode.off || chargeOpen_ || hasPaid;
  open.hidden = showBox;
  box.hidden = !showBox;
  if (!showBox) return;
  const sel = document.getElementById("charge-currency");
  const kind = mode.off ? "off:" + mode.list.join(",") : "paid";
  if (chargeLastCur_ !== kind) {
    chargeLastCur_ = kind;
    sel.innerHTML = exchangeCurrencyOptions_("");
    const paidCur = chargeEntry_ && chargeEntry_.paid_currency;
    sel.value = mode.off ? mode.list[0] : (paidCur || (cur === homeCur() ? "USD" : homeCur()));
  }
  document.getElementById("charge-label").textContent = tr(mode.off ? (mode.pm.type === "credit" ? "charge.card" : "charge.account") : "charge.paidLabel");
  document.getElementById("charge-hint").textContent = tr(mode.off ? "charge.hint" : "charge.paidHint");
  updateChargeRate_();
}
document.getElementById("charge-open").addEventListener("click", () => { chargeOpen_ = true; updateChargeBox_(); });
currencyPickOn_(document.getElementById("charge-currency"));
["change", "click"].forEach((ev) => document.getElementById("entry-form").addEventListener(ev, () => setTimeout(updateChargeBox_, 0)));

// The rate the two amounts imply, the stronger currency as 1 (owner, 2026-11-07: a check that the charge was typed right).
function chargeRateText_(amountA, curA, amountB, curB) {
  const a = Number(amountA), b = Number(amountB);
  if (!(a > 0) || !(b > 0) || !curA || !curB || curA === curB) return "";
  const [strong, weak, rate] = b / a >= 1 ? [curA, curB, b / a] : [curB, curA, a / b];
  const shown = rate.toLocaleString("en-US", { maximumFractionDigits: rate >= 100 ? 2 : 4 });
  return tr("charge.rate", { strong, weak, rate: shown });
}
function updateChargeRate_() {
  const el = document.getElementById("charge-rate");
  const text = document.getElementById("charge-box").hidden ? "" : chargeRateText_(document.getElementById("amount").value, document.getElementById("currency").value,
    document.getElementById("charge-amount").value, document.getElementById("charge-currency").value);
  el.textContent = text;
  el.hidden = !text;
}
["charge-amount", "amount"].forEach((id) => document.getElementById(id).addEventListener("input", updateChargeRate_));
document.getElementById("charge-currency").addEventListener("change", updateChargeRate_);

// What a save sends. `amount`, `currency` and `splits` become what was charged when that is known; `fields` holds the rest.
function chargeForSave_(amount, currency, splits, type, paidBy) {
  const plain = { amount, currency, splits, fields: {} };
  const had = chargeEntry_ && (Number(chargeEntry_.paid_amount) > 0 || String(chargeEntry_.charge_pending || "") === "1");
  const cleared = had ? { paid_amount: "", paid_currency: "", charge_pending: "" } : {};
  const mode = chargeMode_();
  if (!mode || type !== "expense" || paidBy !== "me") return { ...plain, fields: cleared };
  const box = document.getElementById("charge-box");
  const typed = box.hidden ? 0 : parseFloat(document.getElementById("charge-amount").value);
  const other = document.getElementById("charge-currency").value;
  if (mode.off) {
    if (typed > 0) {
      const ratio = typed / amount;
      return { amount: typed, currency: other, fields: { paid_amount: amount, paid_currency: currency, charge_pending: "" },
        splits: splits ? splits.map((s) => ({ ...s, amount: Math.round(Number(s.amount) * ratio * 1e6) / 1e6 })) : splits };
    }
    // An older entry that is only being corrected stays as it was; only a new purchase, or a changed account or currency, starts waiting.
    const same = chargeEntry_ && !confirmingPendingId && chargeEntry_.currency === currency && String(chargeEntry_.payment_method_id) === String(mode.pm.id);
    if (same && String(chargeEntry_.charge_pending || "") !== "1") return { ...plain, fields: cleared };
    return { ...plain, fields: { paid_amount: "", paid_currency: "", charge_pending: "1" } };
  }
  if (typed > 0 && other !== currency) return { ...plain, fields: { paid_amount: typed, paid_currency: other, charge_pending: "" } };
  return { ...plain, fields: cleared };
}

// Home's list of charges to fill in. One line each; it opens at once, and shows its lines when they have arrived.
let chargesList_ = [];
function chargesModalClose_() { document.getElementById("charges-modal-backdrop").hidden = true; }
document.getElementById("charges-modal-close").addEventListener("click", chargesModalClose_);
async function openChargesModal_() {
  const backdrop = document.getElementById("charges-modal-backdrop"), box = document.getElementById("charges-list");
  box.innerHTML = loadingHtml_();
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
  try {
    chargesList_ = await callApi("listPendingCharges", {});
    renderChargesList_();
  } catch (err) {
    box.innerHTML = `<p class="charge-line-error">${escapeHtml(err.message)}</p>`;
  }
}
function chargeDoneRefresh_() {
  renderChargesList_();
  refreshHomeGlance_(true);
  refreshEntryList();
}
function renderChargesList_() {
  const box = document.getElementById("charges-list");
  box.innerHTML = "";
  if (!chargesList_.length) { box.innerHTML = `<p class="hint">${escapeHtml(tr("charges.none"))}</p>`; return; }
  chargesList_.forEach((c) => {
    const pm = (meta.paymentMethods || []).find((p) => String(p.id) === String(c.payment_method_id));
    const list = accountCurrencyList_(pm);
    const line = document.createElement("div");
    line.className = "charge-line";
    const name = c.description || (findCategory(c.category_id) ? categoryName(c.category_id) : tr("confirm.thisEntry"));
    line.innerHTML = `
      <div class="charge-line-top"><span class="charge-line-name">${c.old ? "⏰ " : ""}${escapeHtml(name)}</span><span class="charge-line-amount">${escapeHtml(formatAmount(c.amount, c.currency))}</span></div>
      <p class="hint">${escapeHtml(listDate_(c.date))}${c.account ? " · " + escapeHtml(c.account) : ""}</p>
      <label>${escapeHtml(tr(pm && pm.type !== "credit" ? "charge.account" : "charge.card"))}</label>
      <div class="charge-line-row"><select class="charge-line-cur">${exchangeCurrencyOptions_(list[0] || homeCur())}</select><input type="text" inputmode="decimal" class="charge-line-input" placeholder="0.00"><button type="button" class="add-inline charge-save">${escapeHtml(tr("charges.save"))}</button></div>
      <p class="hint charge-rate" hidden></p>
      <p class="charge-line-error" hidden></p>
      <div class="charge-line-row charge-line-actions"><button type="button" class="add-inline charge-keep">${escapeHtml(tr("charges.keep", { currency: c.currency }))}</button><button type="button" class="add-inline charge-delete">${escapeHtml(tr("charges.delete"))}</button></div>`;
    const curSel = line.querySelector(".charge-line-cur");
    currencyPickOn_(curSel);
    const rateEl = line.querySelector(".charge-rate");
    const showRate = () => { const t = chargeRateText_(c.amount, c.currency, line.querySelector(".charge-line-input").value, curSel.value); rateEl.textContent = t; rateEl.hidden = !t; };
    line.querySelector(".charge-line-input").addEventListener("input", showRate);
    curSel.addEventListener("change", showRate);
    const drop = () => { chargesList_ = chargesList_.filter((x) => x.id !== c.id); };
    line.querySelector(".charge-save").addEventListener("click", async () => {
      const amount = parseFloat(line.querySelector(".charge-line-input").value);
      const error = line.querySelector(".charge-line-error");
      if (!(amount > 0)) { error.textContent = tr("charges.needAmount"); error.hidden = false; return; }
      const currency = curSel.value;
      await ensureExchangeRate(currency, c.date);
      drop();
      renderChargesList_();
      saveBehindScreen_(() => callApi("fillEntryCharge", { id: c.id, amount, currency }), chargeDoneRefresh_);
    });
    line.querySelector(".charge-keep").addEventListener("click", () => {
      drop();
      renderChargesList_();
      saveBehindScreen_(() => callApi("keepEntryCharge", { id: c.id }), chargeDoneRefresh_);
    });
    line.querySelector(".charge-delete").addEventListener("click", async () => {
      const summary = describeForConfirm_(c.description || "", formatAmount(c.amount, c.currency), c.date);
      const done = await confirmAndDiscardEntry_(c.id, "expense", summary, () => { drop(); renderChargesList_(); });
      if (done) chargeDoneRefresh_();
    });
    box.appendChild(line);
  });
}
document.getElementById("home-charges").addEventListener("click", openChargesModal_);

// `loan` is null to add a new one, or an existing loan (from
// getFriendLoanDetail) to edit it. `returnFriend` is {id, name} when
// opened from that friend's detail sheet, so it can be refreshed after.
function openLoanModal(loan, returnFriend, opts) {
  editingLoanId = loan ? loan.id : null;
  loanModalReturnFriend = returnFriend || null;
  loanModalApplyLoan_ = loan || null;

  document.getElementById("loan-modal-title").textContent = loan ? tr("loanModal.edit") : tr("loanModal.add");
  document.getElementById("loan-delete-btn").hidden = !loan;
  // A "paid earlier, no loan" payment can be put on loans from here too (same as the button on the person's screen).
  document.getElementById("loan-apply-btn").hidden = !(loan && returnFriend && (loan.unapplied || loan.unapplied_sources) && loan.status !== "forgiven" && loan.remaining > 0.004);
  document.getElementById("loan-form-error").textContent = "";
  populateLoanFriendOptions();
  populateLoanPaymentMethodOptions();
  document.getElementById("loan-friend").value = loan ? loan.friend_id : ((opts && opts.friendId) || (meta.friends.length ? meta.friends[0].id : ""));
  setLoanDirection_(loan ? loan.direction : "they_owe_me");
  document.getElementById("loan-amount").value = loan ? loan.amount : "";
  document.getElementById("loan-currency").value = loan ? loan.currency : homeCur();
  renderCurrencyChips("loan");
  const entryDate = loan ? loan.date : todayLocalISO();
  document.getElementById("loan-date").value = entryDate;
  document.getElementById("loan-due-date").value = loan ? (loan.due_date || "") : defaultDueDate_(entryDate);
  const loanPmSelect = document.getElementById("loan-payment-method");
  loanPmSelect.value = loan ? (loan.payment_method_id || "") : (loanPmSelect.options.length ? loanPmSelect.options[0].value : "");
  document.getElementById("loan-description").value = loan ? (loan.description || "") : "";
  populateLoanProjectOptions_(loan ? (loan.project_id || "") : "");
  // "From before the app": a choice for a NEW loan; an existing one shows what it is and cannot be switched.
  const openingBox = document.getElementById("loan-opening");
  openingBox.checked = loan ? loan.opening === "1" || loan.opening === 1 : !!(opts && opts.opening);
  openingBox.disabled = !!loan;
  const openingOk = !!((meta && meta.capabilities) || {}).openingLoan;   // an older backend would make a normal loan with a money entry
  document.getElementById("loan-opening-row").hidden = !openingOk || (!!loan && !openingBox.checked);   // an ordinary loan being edited: the choice does not apply
  if (!openingOk) openingBox.checked = false;
  updateLoanOpeningUi_(!loan);

  const backdrop = document.getElementById("loan-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}

// Business pack: a cash loan may belong to a project (shown only when the pack is on and a project exists).
function populateLoanProjectOptions_(keep) {
  const field = document.getElementById("loan-project-field");
  const sel = document.getElementById("loan-project");
  const show = businessOn() && (meta.projects || []).length > 0;
  field.hidden = !show;
  sel.innerHTML = "";
  const none = document.createElement("option");
  none.value = "";
  none.textContent = tr("business.pickNone");
  sel.appendChild(none);
  (meta.projects || []).filter((p) => p.status !== "closed" || p.id === keep).forEach((p) => {
    const company = (meta.companies || []).find((c) => c.id === p.company_id);
    const o = document.createElement("option");
    o.value = p.id;
    o.textContent = company ? `${company.name} › ${p.name}` : p.name;
    sel.appendChild(o);
  });
  sel.value = keep || "";
}

function closeLoanModal() {
  document.getElementById("loan-modal-backdrop").hidden = true;
  editingLoanId = null;
  moneyReopen_ = null;   // closed without saving: the failed item stays as it was
}

// After a save/delete: the main Loans list always refreshes, and if this
// modal was reached through a friend's detail sheet (still open
// underneath it), that gets refreshed too rather than left showing
// stale data.
async function refreshAfterLoanModalChange_() {
  refreshEntriesInBackground_();
  await refreshLoans();
  if (loanModalReturnFriend) {
    await openLoanDetail(loanModalReturnFriend.id, loanModalReturnFriend.name);
  }
}

document.getElementById("loan-apply-btn").addEventListener("click", () => {
  const loan = loanModalApplyLoan_;
  const friend = loanModalReturnFriend;
  if (!loan || !friend) return;
  closeLoanModal();
  openApplyUnapplied_(loan, friend);
});
document.getElementById("add-loan-btn").addEventListener("click", () => openLoanModal(null, null));
document.getElementById("loan-modal-close").addEventListener("click", closeLoanModal);
document.getElementById("loan-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "loan-modal-backdrop") closeLoanModal();
});

document.getElementById("loan-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("loan-form-error");
  errorEl.textContent = "";
  const saveBtn = document.getElementById("loan-save-btn");

  try {
    const friendId = document.getElementById("loan-friend").value;
    const amount = parseFloat(document.getElementById("loan-amount").value);
    const currency = document.getElementById("loan-currency").value.toUpperCase();
    const date = document.getElementById("loan-date").value;
    const dueDate = document.getElementById("loan-due-date").value;
    const paymentMethodId = document.getElementById("loan-payment-method").value;
    const description = document.getElementById("loan-description").value.trim();

    if (!friendId || friendId === "__add__") throw new Error(tr("error.pickFriend"));
    if (!amount || amount <= 0) throw new Error(tr("error.validAmount"));
    if (!date) throw new Error(tr("error.dateRequired"));
    const opening = document.getElementById("loan-opening").checked;
    // (No account is now a choice the person picks by name, "Not through my accounts": no second question.)

    const fields = {
      friend_id: friendId,
      direction: loanDirection,
      amount,
      currency,
      date,
      due_date: dueDate,
      payment_method_id: opening ? "" : paymentMethodId,
      description
    };
    if (opening && !editingLoanId) fields.opening = true;
    if (businessOn()) fields.project_id = document.getElementById("loan-project").value;
    if (!editingLoanId) tipNoteLoanSaved_(fields);   // the first-use practice remembers its own loan

    if (moneyBackground_()) {
      // The server's refusals for an edit are checked here first (same rules as updateLoan in Loans.gs), so the message shows
      // in the open form; only what the phone could not foresee comes back later as a "couldn't save" item.
      const existing = editingLoanId ? loanModalApplyLoan_ : null;
      if (existing && typeof existing.remaining === "number") {
        const settled = Number(existing.amount) - existing.remaining;
        if (settled > 0.004) {
          if (friendId !== existing.friend_id || loanDirection !== existing.direction || currency !== existing.currency) throw new Error(tr("loanModal.errLocked"));
          if (amount < settled - 0.004) throw new Error(tr("loanModal.errBelowSettled", { settled: settled.toFixed(2) }));
        }
      }
      const friend = meta.friends.find((f) => f.id === friendId);
      const ctx = { friendId: loanModalReturnFriend ? loanModalReturnFriend.id : friendId, friendName: loanModalReturnFriend ? loanModalReturnFriend.name : (friend ? friend.name : "") };
      const loanId = editingLoanId;
      const replaces = takeMoneyReopen_("loan");
      closeLoanModal();
      queueMoneyAction_(loanId ? "updateLoan" : "addLoan", loanId ? { id: loanId, ...fields } : fields, `${tr("money.labelLoan")} · ${friend ? friend.name : ""} ${currency} ${moneyFmt(amount)}`, ctx, replaces);
      return;
    }

    saveBtn.disabled = true;
    if (editingLoanId) {
      await callApi("updateLoan", { id: editingLoanId, ...fields });
    } else {
      await callApi("addLoan", fields);
    }
    closeLoanModal();
    await refreshAfterLoanModalChange_();
  } catch (err) {
    errorEl.textContent = err.message;
  } finally {
    saveBtn.disabled = false;
  }
});

document.getElementById("loan-delete-btn").addEventListener("click", async () => {
  if (!editingLoanId) return;
  const loanFriend = document.getElementById("loan-friend");
  const loanWho = loanFriend && loanFriend.selectedOptions[0] ? loanFriend.selectedOptions[0].textContent : "";
  const loanDesc = document.getElementById("loan-description").value.trim();
  const loanAmt = document.getElementById("loan-amount").value.trim();
  const loanCur = document.getElementById("loan-currency").value;
  const errorEl = document.getElementById("loan-form-error");
  errorEl.textContent = "";

  try {
    // With repayments recorded against it the person chooses what happens to them; otherwise the usual OK / Cancel.
    const info = await callApi("getLoanDeleteInfo", { id: editingLoanId });
    let repayments;
    if (info.hasRepayments) {
      repayments = await askRepaymentChoice_("repayChoice.loanTitle", [{ friend: loanWho, currency: info.currency, total: info.paid }]);
      if (!repayments) return;
    } else if (!practiceNoConfirm_(isPracticeLoanText_(loanDesc)) && !confirm(tr("loanModal.confirmDelete", { what: describeForConfirm_(loanDesc || loanWho, loanAmt ? `${loanCur} ${loanAmt}` : "", loanDesc && loanWho ? loanWho : "") }))) {
      return;
    }
    // Saving standard: the form closes at once; the loan's row says "Deleting…" until the server is done.
    const loanId = editingLoanId;
    markDeleting_("loan:" + loanId);
    // The first-use practice's loan counts as deleted from the tap: the form closes now, and a walkthrough that waited for the
    // server's answer saw "form closed, loan not deleted" and went back a step (bank-loan practice, found 2026-11-02). A refused
    // delete changes nothing for it: the practice's cleanup removes its loan anyway.
    tipNoteLoanDeleted_(loanDesc);
    closeLoanModal();
    try { await callApi("deleteLoan", { id: loanId, repayments }); }
    catch (e) { unmarkDeleting_("loan:" + loanId); throw e; }
    await refreshAfterLoanModalChange_();
  } catch (err) {
    if (document.getElementById("loan-modal-backdrop").hidden) alert(err.message);   // the form already closed
    else errorEl.textContent = err.message;
  }
});

// ---- Settlements / repayments (Phase 5.4, consolidated 2026-09-17) ----
// Recording a repayment is friend-+-currency-level, not single-loan — the
// backend (recordRepayment in Loans.gs) works out on its own which
// loan(s) it applies to via a two-phase FIFO: first netting opposite-
// direction debt (e.g. a loan they gave you cancels against the oldest
// expenses you covered for them), then applying the real amount to
// whatever's left. Never touches Entries, income/expense totals, or
// budgets directly (per CLAUDE.md's Settlements section) — except for the
// one deliberate exception below (an overpayment becoming real income).

let repaymentFriendId = null;
let repaymentFriendName = null;
let repaymentNetByCurrency = {};
let repaymentCurrency = null;
// 'they_owe_me' or 'i_owe_them' — which debt this repayment pays down,
// always derived from the sign of the friend's net in the selected
// currency, never picked directly (see openRepaymentModal).
let repaymentDirection = null;
let editingSettlementId = null;
// Set only while the overpayment section is showing — the amount still
// needs a category before it can become a real income entry.
let pendingOverpay = null;

function populateSettlementPaymentMethodOptions() {
  const select = document.getElementById("settlement-payment-method");
  select.innerHTML = "";
  // Like the new-entry form: just the accounts (no platforms), no "None" row. Only with no account at all does it say so.
  const accounts = meta.paymentMethods.filter((pm) => pm.type !== "investment" && !pmHidden_(pm));
  if (!accounts.length) {
    const noneOpt = document.createElement("option");
    noneOpt.value = "";
    noneOpt.textContent = tr("form.noneAccount");
    select.appendChild(noneOpt);
  }
  accounts.forEach((pm) => {
    const opt = document.createElement("option");
    opt.value = pm.id;
    opt.textContent = pmPickLabel_(pm);
    select.appendChild(opt);
  });
}

// `type` is "income" (they overpaid you) or "expense" (you overpaid
// them) — mirror images, see recordRepayment/createOverpaymentEntry_ in
// Loans.gs.
function populateOverpayCategoryOptions(type) {
  document.getElementById("settlement-overpay-category-label").textContent =
    tr("settle.categoryOf", { type: TYPE_LABELS[type].toLowerCase() });
  populateCategoryOptionsForSelect_("settlement-overpay-category", type);
}

function renderSettlementCurrencyChips_() {
  const container = document.getElementById("settlement-currency-chips");
  const currencies = Object.keys(repaymentNetByCurrency);
  container.hidden = currencies.length < 2;
  container.innerHTML = "";
  currencies.forEach((cur) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "currency-chip" + (cur === repaymentCurrency ? " active" : "");
    chip.innerHTML = `<span>${findCurrency(cur).flag}</span><span>${cur}</span>`;
    chip.addEventListener("click", () => switchRepaymentCurrency_(cur));
    container.appendChild(chip);
  });
}

function settlementFriendContext_() {
  const net = repaymentNetByCurrency[repaymentCurrency] || 0;
  const amount = Math.abs(net);
  return repaymentDirection === "they_owe_me"
    ? tr("settle.contextTheyOwe", { name: repaymentFriendName, cur: repaymentCurrency, amount: moneyFmt(amount) })
    : tr("settle.contextIOwe", { name: repaymentFriendName, cur: repaymentCurrency, amount: moneyFmt(amount) });
}

// A new repayment starts on an account, never on "None": the one used for the last repayment recorded on this phone, else the first account.
function defaultRepaymentAccount_() {
  const select = document.getElementById("settlement-payment-method");
  const ids = Array.from(select.options).map((o) => o.value).filter(Boolean);
  let last = "";
  try { last = localStorage.getItem("lastRepaymentAccount") || ""; } catch (e) { /* no storage */ }
  return ids.includes(last) ? last : (ids[0] || "");
}

// Back to "add a new repayment" — the default state the form opens in,
// and where "Cancel edit" returns it to without closing the whole modal.
function resetSettlementForm_() {
  editingSettlementId = null;
  document.getElementById("settlement-save-btn").textContent = tr("settle.save");
  document.getElementById("settlement-cancel-edit-btn").hidden = true;
  document.getElementById("settlement-delete-btn").hidden = true;
  document.getElementById("settlement-form-error").textContent = "";
  document.getElementById("settlement-amount").value = Math.abs(repaymentNetByCurrency[repaymentCurrency] || 0).toFixed(2);
  document.getElementById("settlement-date").value = todayLocalISO();
  document.getElementById("settlement-payment-method").value = defaultRepaymentAccount_();
  document.getElementById("settlement-description").value = "";
  document.getElementById("settlement-form").hidden = false;
  document.getElementById("settlement-overpay-section").hidden = true;
  pendingOverpay = null;
  editingSettlementLoanId_ = "";
  document.getElementById("settlement-loan-field").hidden = true;
  renderSettlementChoose_();
}

// ---- "Which loan this pays": fixing a recorded repayment that went to the wrong loan ----

let editingSettlementLoanId_ = "";   // the loan the repayment being edited is on now

// Only shown while editing one recorded repayment, and only when the person has another loan of the same kind and currency
// to move it to (a fully paid loan can't take more; the current one is always listed, paid or not).
function renderSettlementLoanField_(s) {
  editingSettlementLoanId_ = s.loan_id;
  const field = document.getElementById("settlement-loan-field");
  const select = document.getElementById("settlement-loan");
  select.innerHTML = "";
  const label = (l) => tr("settle.loanOption", { date: I18n.fmtDateMedium(new Date(l.date + "T00:00:00")), what: l.description || tr("transfer.kind.loan"), cur: l.currency, amount: moneyFmt(l.remaining) });
  const candidates = repaymentAllLoans_.filter((l) =>
    l.direction === repaymentDirection && l.currency === repaymentCurrency && l.status !== "forgiven" && (l.id === s.loan_id || l.remaining > 0.004));
  candidates.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  candidates.forEach((l) => {
    const opt = document.createElement("option");
    opt.value = l.id;
    // The current loan shows no balance: after this very repayment it often reads "0.00 left", which only confuses.
    opt.textContent = l.id === s.loan_id
      ? tr("settle.loanCurrent", { label: `${I18n.fmtDateMedium(new Date(l.date + "T00:00:00"))} · ${l.description || tr("transfer.kind.loan")}` })
      : label(l);
    select.appendChild(opt);
  });
  if (!candidates.some((l) => l.id === s.loan_id)) {   // current loan outside the screen's scope: still show it, so nothing looks changed
    const opt = document.createElement("option");
    opt.value = s.loan_id;
    opt.textContent = tr("settle.loanCurrent", { label: s.loan_description || tr("transfer.kind.loan") });
    select.insertBefore(opt, select.firstChild);
  }
  select.value = s.loan_id;
  field.hidden = select.options.length < 2;
}

// ---- "Choose which loans this pays": FIFO (oldest first) unless the person assigns amounts to particular loans ----

function settlementChoosableLoans_() {
  return repaymentLoans_
    .filter((l) => l.direction === repaymentDirection && l.currency === repaymentCurrency && l.status !== "forgiven" && l.remaining > 0.004)
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}

// The ticked loans are paid in order (oldest first) until the payment runs out: no amounts to type per loan.
function settlementAssignments_() {
  const paid = parseFloat(document.getElementById("settlement-amount").value) || 0;
  const open = {};
  settlementChoosableLoans_().forEach((l) => { open[l.id] = l.remaining; });
  const out = [];
  let left = paid;
  document.querySelectorAll("#settlement-choose-list input[data-loan]").forEach((input) => {
    if (!input.checked || left <= 0.004) return;
    const amount = Math.round(Math.min(open[input.dataset.loan] || 0, left) * 100) / 100;
    if (amount > 0) { out.push({ loan_id: input.dataset.loan, amount }); left -= amount; }
  });
  return out;
}

function renderSettlementChooseSummary_() {
  const paid = parseFloat(document.getElementById("settlement-amount").value) || 0;
  const assignments = settlementAssignments_();
  const assigned = assignments.reduce((n, a) => n + a.amount, 0);
  // Each ticked loan shows how much of the payment it takes.
  document.querySelectorAll("#settlement-choose-list input[data-loan]").forEach((input) => {
    const a = assignments.find((x) => x.loan_id === input.dataset.loan);
    input.closest("label").querySelector(".settle-choose-assigned").textContent = a ? `${repaymentCurrency} ${moneyFmt(a.amount)}` : "";
  });
  // What is left of the payment continues oldest-first over the loans that were not selected: name them, so nothing surprises.
  const cur = repaymentCurrency;
  let rest = Math.round(Math.max(0, paid - assigned) * 100) / 100;
  const parts = [tr("settle.chooseAssigned", { assigned: `${cur} ${moneyFmt(assigned)}` })];
  if (rest > 0.004) {
    const picked = new Set(assignments.map((a) => a.loan_id));
    const others = [];
    for (const l of settlementChoosableLoans_()) {
      if (rest <= 0.004) break;
      if (picked.has(l.id)) continue;
      const take = Math.round(Math.min(l.remaining, rest) * 100) / 100;
      others.push(`${l.description || tr("transfer.kind.loan")} (${cur} ${moneyFmt(take)})`);
      rest = Math.round((rest - take) * 100) / 100;
    }
    if (others.length) parts.push(tr("settle.chooseRestTo", { list: others.join(", ") }));
    if (rest > 0.004) parts.push(tr(repaymentDirection === "they_owe_me" ? "settle.chooseExtraIncome" : "settle.chooseExtraExpense", { extra: `${cur} ${moneyFmt(rest)}` }));
  }
  document.getElementById("settlement-choose-summary").textContent = parts.join(" · ");
}

// Shown only when there is a real choice (two or more open loans in the direction and currency being paid) and not while fixing
// one recorded repayment. Closed and empty each time the sheet is reset, so a choice never leaks into the next repayment.
function renderSettlementChoose_() {
  const wrap = document.getElementById("settlement-choose");
  if (!wrap) return;
  document.getElementById("settlement-choose-panel").hidden = true;
  document.getElementById("settlement-choose-list").innerHTML = "";
  document.getElementById("settlement-choose-btn").textContent = tr("settle.chooseLoans");
  wrap.hidden = !!editingSettlementId || settlementChoosableLoans_().length < 2;
}

document.getElementById("settlement-choose-btn").addEventListener("click", () => {
  const panel = document.getElementById("settlement-choose-panel");
  if (!panel.hidden) { renderSettlementChoose_(); return; }   // "Back to oldest first"
  const list = document.getElementById("settlement-choose-list");
  list.innerHTML = "";
  settlementChoosableLoans_().forEach((l) => {
    const row = document.createElement("label");
    row.className = "settle-choose-row";
    const text = document.createElement("span");
    text.textContent = tr("settle.chooseRow", { date: I18n.fmtDateMedium(new Date(l.date + "T00:00:00")), what: l.description || tr("transfer.kind.loan"), cur: l.currency, amount: moneyFmt(l.remaining) });
    const input = document.createElement("input");
    input.type = "checkbox";
    input.dataset.loan = l.id;
    input.addEventListener("change", renderSettlementChooseSummary_);
    const assignedEl = document.createElement("span");
    assignedEl.className = "settle-choose-assigned";
    row.appendChild(input);
    row.appendChild(text);
    row.appendChild(assignedEl);
    list.appendChild(row);
  });
  panel.hidden = false;
  document.getElementById("settlement-choose-btn").textContent = tr("settle.chooseOff");
  renderSettlementChooseSummary_();
});
document.getElementById("settlement-amount").addEventListener("input", () => {
  if (!document.getElementById("settlement-choose-panel").hidden) renderSettlementChooseSummary_();
});

function loadSettlementIntoForm_(s) {
  editingSettlementId = s.id;
  renderSettlementChoose_();
  document.getElementById("settlement-save-btn").textContent = tr("settle.saveChanges");
  document.getElementById("settlement-cancel-edit-btn").hidden = false;
  document.getElementById("settlement-delete-btn").hidden = false;
  document.getElementById("settlement-form-error").textContent = "";
  document.getElementById("settlement-amount").value = s.amount;
  document.getElementById("settlement-date").value = s.date;
  document.getElementById("settlement-payment-method").value = s.payment_method_id || "";
  renderSettlementLoanField_(s);
}

function renderSettlementList_(settlements) {
  const list = document.getElementById("settlement-list");
  const emptyNote = document.getElementById("settlement-list-empty-note");
  list.innerHTML = "";

  if (settlements.length === 0) {
    emptyNote.hidden = false;
    return;
  }
  emptyNote.hidden = true;

  settlements.forEach((s) => {
    const pm = meta.paymentMethods.find((p) => p.id === s.payment_method_id);
    const row = document.createElement("div");
    const isOffset = !!s.offset_loan_id;
    row.className = "loan-detail-row" + (isOffset ? "" : " editable");

    const desc = isOffset
      ? tr("settle.offsetAgainst", { desc: escapeHtml(s.offset_loan_description) })
      : `${listDate_(s.date)}${pm ? " · " + escapeHtml(pm.nickname) : ""}`;

    row.innerHTML = `
      <div class="loan-detail-row-top">
        <span class="loan-detail-row-desc">${desc}${isOffset ? "" : '<span class="loan-detail-row-chevron">›</span>'}</span>
        <span class="loan-detail-row-amount i-owe">${repaymentCurrency} ${moneyFmt(s.amount)}</span>
      </div>
      <div class="loan-detail-row-meta">${escapeHtml(s.loan_description)}${isOffset ? " · " + s.date : ""}</div>
    `;
    if (!isOffset) {
      row.addEventListener("click", () => loadSettlementIntoForm_(s));
    }
    list.appendChild(row);
  });
}

async function refreshSettlementList_() {
  const settlements = await callApi("listSettlementsForFriendCurrency", {
    friendId: repaymentFriendId,
    currency: repaymentCurrency
  });
  renderSettlementList_(settlements);
}

async function switchRepaymentCurrency_(currency) {
  repaymentCurrency = currency;
  repaymentDirection = (repaymentNetByCurrency[currency] || 0) > 0 ? "they_owe_me" : "i_owe_them";
  renderSettlementCurrencyChips_();
  document.getElementById("settlement-friend-context").textContent = settlementFriendContext_();
  resetSettlementForm_();
  await refreshSettlementList_();
}

// `netByCurrency` comes straight from openLoanDetail's own already-loaded
// loan list (see there) — no extra fetch needed just to open this.
let repaymentProjectId_ = "";   // Business pack: set when the repayment is recorded from a project's debts
let repaymentLoans_ = [];       // the person's open loans (in the scope the sheet was opened with), for "Choose which loans this pays"
let repaymentAllLoans_ = [];    // the same scope including paid ones, for "Which loan this pays" when fixing a recorded repayment
async function openRepaymentModal(friendId, friendName, netByCurrency, projectId, openLoans, allLoans) {
  repaymentLoans_ = openLoans || [];
  repaymentAllLoans_ = allLoans || openLoans || [];
  repaymentProjectId_ = projectId || "";
  repaymentFriendId = friendId;
  repaymentFriendName = friendName;
  repaymentNetByCurrency = netByCurrency;

  document.getElementById("settlement-modal-title").textContent = tr("transfer.kind.repayment");
  populateSettlementPaymentMethodOptions();

  const currencies = Object.keys(netByCurrency);
  await switchRepaymentCurrency_(currencies[0]);

  const backdrop = document.getElementById("settlement-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}

function closeSettlementModal() {
  document.getElementById("settlement-modal-backdrop").hidden = true;
  editingSettlementId = null;
  // Closed without picking a category for the extra: nothing is lost — the
  // server already saved it as a pending entry. Say so and show it.
  if (pendingOverpay) {
    const p = pendingOverpay;
    pendingOverpay = null;
    alert(tr(p.entryType === "income" ? "settle.extraSavedIncome" : "settle.extraSavedExpense", { cur: p.currency, amount: moneyFmt(p.amount) }));
    refreshReviewQueue().catch(() => {});
  }
}

async function refreshAfterSettlementChange_() {
  refreshEntriesInBackground_();
  await refreshLoans();
  await openLoanDetail(repaymentFriendId, repaymentFriendName);
}

document.getElementById("settlement-modal-close").addEventListener("click", closeSettlementModal);
document.getElementById("settlement-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "settlement-modal-backdrop") closeSettlementModal();
});
document.getElementById("settlement-cancel-edit-btn").addEventListener("click", resetSettlementForm_);

document.getElementById("settlement-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("settlement-form-error");
  errorEl.textContent = "";

  // Checked while the modal is still open, so a typo is shown right there.
  const amount = parseFloat(document.getElementById("settlement-amount").value);
  const date = document.getElementById("settlement-date").value;
  const paymentMethodId = document.getElementById("settlement-payment-method").value;
  const description = document.getElementById("settlement-description").value.trim();
  if (!amount || amount <= 0) { errorEl.textContent = tr("error.validAmount"); return; }
  if (!date) { errorEl.textContent = tr("error.dateRequired"); return; }
  // "Choose which loans this pays" (only when the person opened it and typed amounts): otherwise FIFO, exactly as before.
  const allocations = !editingSettlementId && !document.getElementById("settlement-choose-panel").hidden ? settlementAssignments_() : [];
  if (allocations.reduce((n, a) => n + a.amount, 0) > amount + 0.004) { errorEl.textContent = tr("settle.chooseTooMuch"); return; }
  // Moving a recorded repayment to another loan: checked here too, so the message shows in the open sheet.
  const newLoanId = editingSettlementId && !document.getElementById("settlement-loan-field").hidden ? document.getElementById("settlement-loan").value : "";
  if (newLoanId && newLoanId !== editingSettlementLoanId_) {
    const target = repaymentAllLoans_.find((l) => l.id === newLoanId);
    if (target && amount > target.remaining + 0.004) {
      errorEl.textContent = tr("settle.loanTooMuch", { cur: target.currency, amount: moneyFmt(target.remaining) });
      return;
    }
  }

  // Everything from here on runs after the modal has closed — the owner
  // doesn't sit and wait for the server. A failure is reported with an alert
  // (the modal is gone), and the lists are re-fetched so they show the truth.
  // Captured first: closing the modal resets the editing state.
  if (!editingSettlementId && paymentMethodId) { try { localStorage.setItem("lastRepaymentAccount", paymentMethodId); } catch (e) { /* no storage */ } }
  const settlementId = editingSettlementId;
  const friendId = repaymentFriendId;
  const friendName = repaymentFriendName;
  const direction = repaymentDirection;
  const currency = repaymentCurrency;
  closeSettlementModal();

  try {
    if (settlementId && moneyBackground_()) {
      // Safe to send again (it sets one row to these values), so it waits in the money queue like the others: it survives
      // closing the app and a refusal comes back as a "couldn't save" item.
      queueMoneyAction_("updateSettlement", { id: settlementId, amount, date, payment_method_id: paymentMethodId, loan_id: newLoanId || undefined },
        `${tr("money.labelRepaymentEdit")} · ${friendName} ${currency} ${moneyFmt(amount)}`, { friendId, friendName });
      return;
    }
    if (settlementId) {
      // Fixing a specific real settlement's own typo — doesn't re-run
      // FIFO, just corrects that one row (see updateSettlement in
      // Loans.gs).
      await callApi("updateSettlement", { id: settlementId, amount, date, payment_method_id: paymentMethodId, loan_id: newLoanId || undefined });
      await refreshAfterSettlementChange_();
      return;
    }

    if (moneyBackground_()) {
      // Sent behind the screen like the others. The extra beyond what was owed (if any) is not asked about here: the
      // server records it in the review queue to be categorised there, and the phone says so once the save lands.
      queueMoneyAction_("recordRepayment", {
        friend_id: friendId,
        direction,
        amount,
        currency,
        date,
        payment_method_id: paymentMethodId,
        description,
        project_id: repaymentProjectId_ || undefined,
        allocations: allocations.length ? allocations : undefined
      }, `${tr("money.labelRepayment")} · ${friendName} ${currency} ${moneyFmt(amount)}`, { friendId, friendName });
      return;
    }

    const result = await callApi("recordRepayment", {
      friend_id: friendId,
      direction,
      amount,
      currency,
      date,
      payment_method_id: paymentMethodId,
      description,
      project_id: repaymentProjectId_ || undefined,   // only that project's debts are paid down (Loans.gs)
      allocations: allocations.length ? allocations : undefined   // the loans the person chose; none = oldest first
    });

    refreshEntriesInBackground_();
    await refreshLoans();
    await openLoanDetail(friendId, friendName);

    if (result.overpaid > 0.004) {
      // Mirror images: they overpaying YOU is your income; YOU overpaying
      // them is your expense (paid_by: "me", no split — see
      // createOverpaymentEntry_ in Loans.gs). Needs the owner's category
      // pick, so the modal comes back, showing just that step.
      const isIncome = direction === "they_owe_me";
      pendingOverpay = { amount: result.overpaid, currency: result.currency, date, paymentMethodId, entryType: isIncome ? "income" : "expense" };
      document.getElementById("settlement-overpay-note").textContent = isIncome
        ? tr("settle.overpaidIncome", { name: friendName, cur: result.currency, amount: moneyFmt(result.overpaid) })
        : tr("settle.overpaidExpense", { name: friendName, cur: result.currency, amount: moneyFmt(result.overpaid) });
      populateOverpayCategoryOptions(pendingOverpay.entryType);
      document.getElementById("settlement-overpay-error").textContent = "";
      document.getElementById("settlement-form").hidden = true;
      document.getElementById("settlement-overpay-section").hidden = false;
      const backdrop = document.getElementById("settlement-modal-backdrop");
      bringModalToFront_(backdrop);
      backdrop.hidden = false;
    }
  } catch (err) {
    alert(tr("settle.saveFailed", { error: err.message }));
    refreshAfterSettlementChange_().catch(() => {});
  }
});

document.getElementById("settlement-delete-btn").addEventListener("click", async () => {
  if (!editingSettlementId) return;
  const repAmt = document.getElementById("settlement-amount").value.trim();
  const repDate = document.getElementById("settlement-date").value;
  if (!confirm(tr("settle.confirmDelete", { what: describeForConfirm_(repaymentFriendName || "", repAmt ? `${repaymentCurrency} ${repAmt}` : "", repDate) }))) return;

  // Closes first, finishes in the background (same as the save button).
  const settlementId = editingSettlementId;
  closeSettlementModal();
  try {
    await callApi("deleteSettlement", { id: settlementId });   // the whole repayment goes; a failure is undone and announced just below
    await refreshAfterSettlementChange_();
  } catch (err) {
    alert(tr("settle.saveFailed", { error: err.message }));
    refreshAfterSettlementChange_().catch(() => {});
  }
});

document.getElementById("settlement-overpay-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("settlement-overpay-error");
  errorEl.textContent = "";
  if (!pendingOverpay) return;
  const categoryId = document.getElementById("settlement-overpay-category").value;
  if (!categoryId) { errorEl.textContent = tr("error.pickCategory"); return; }

  const saveBtn = document.getElementById("settlement-overpay-save-btn");
  if (moneyBackground_()) {
    const o = pendingOverpay;
    pendingOverpay = null;   // resolved: no "saved in your review queue" notice
    closeSettlementModal();
    queueMoneyAction_(o.entryType === "income" ? "recordOverpaymentIncome" : "recordOverpaymentExpense", {
      friend_id: repaymentFriendId,
      amount: o.amount,
      currency: o.currency,
      date: o.date,
      payment_method_id: o.paymentMethodId,
      category_id: categoryId
    }, `${tr("money.labelOverpay")} · ${o.currency} ${moneyFmt(o.amount)}`, {});
    return;
  }
  saveBtn.disabled = true;
  try {
    const action = pendingOverpay.entryType === "income" ? "recordOverpaymentIncome" : "recordOverpaymentExpense";
    await callApi(action, {
      friend_id: repaymentFriendId,
      amount: pendingOverpay.amount,
      currency: pendingOverpay.currency,
      date: pendingOverpay.date,
      payment_method_id: pendingOverpay.paymentMethodId,
      category_id: categoryId
    });
    pendingOverpay = null;   // resolved: no "saved in your review queue" notice
    closeSettlementModal();
    await refreshEntryList();
    refreshReviewQueue().catch(() => {});
  } catch (err) {
    errorEl.textContent = err.message;
  } finally {
    saveBtn.disabled = false;
  }
});

// ---- Forgiving a loan (Phase 5.5) ----
// Applies to either kind of loan and either direction (see "🙏 Forgive"
// in openLoanDetail, above) — a status change, not an edit, so it isn't
// origin-restricted the way updateLoan is. Optionally converts whatever
// was still outstanding into a real expense or income entry, mirroring
// the same direction logic recordRepayment's overpayment handling uses
// (see forgiveLoan in Loans.gs).

let forgiveLoanTarget = null;
let forgiveReturnFriend = null;

function populateCategoryOptionsForSelect_(selectId, type) {
  const select = document.getElementById(selectId);
  select.innerHTML = "";
  sortedCategories_(pickableCategories_(meta.categories.filter((c) => c.type === type))).forEach((c) => {
    const opt = document.createElement("option");
    opt.value = c.id;
    opt.textContent = (c.icon ? c.icon + " " : "") + c.name;
    select.appendChild(opt);
  });
}

function openForgiveModal(loan, returnFriend) {
  forgiveLoanTarget = loan;
  forgiveReturnFriend = returnFriend;

  document.getElementById("forgive-form-error").textContent = "";
  document.getElementById("forgive-context").textContent =
    tr("forgive.context", { name: loan.description || tr("loan.word"), cur: loan.currency, amount: moneyFmt(loan.remaining) });

  const hasBalance = loan.remaining > 0.004;
  // The whole balance to start with; a smaller amount forgives only that part (forgiveLoan, `amount`).
  document.getElementById("forgive-amount-field").hidden = !hasBalance;
  document.getElementById("forgive-amount").value = hasBalance ? String(Math.round(loan.remaining * 100) / 100) : "";
  const checkbox = document.getElementById("forgive-convert-checkbox");
  // No opt-out any more: forgiving a debt always registers what was still
  // owed as an expense/income entry (see forgiveLoan in Loans.gs), so the
  // checkbox stays hidden and checked.
  const convertRow = checkbox.closest(".checkbox-row");
  convertRow.hidden = true;
  checkbox.checked = hasBalance;

  // "Convert to expense" when the owner is the one being owed and
  // writing it off (that's their own spending); "convert to income"
  // when someone else is the one forgiving what the owner owed them
  // (that's free money from the owner's side) — same direction logic as
  // an overpayment.
  const entryType = loan.direction === "they_owe_me" ? "expense" : "income";
  document.getElementById("forgive-convert-label").textContent = tr(entryType === "expense" ? "forgive.convert" : "forgive.convertIncome");
  if (hasBalance) {
    document.getElementById("forgive-context").textContent +=
      tr(entryType === "expense" ? "forgive.recordedExpense" : "forgive.recordedIncome");
  }
  populateCategoryOptionsForSelect_("forgive-category", entryType);
  document.getElementById("forgive-date").value = todayLocalISO();
  document.getElementById("forgive-convert-fields").hidden = !hasBalance || !checkbox.checked;
  // Which budget the forgiven amount will count in, and where that leaves it (owner, 2026-11-07: forgiving silently pushed Restaurants
  // to 117%). Fetched behind the open form; the line shows once it has arrived and follows the amount, category and date.
  forgiveBudgets_ = null;
  document.getElementById("forgive-budget-note").hidden = true;
  if (hasBalance && entryType === "expense") {
    const forLoan = loan;
    callApi("listBudgets", {}).then((data) => {
      if (forgiveLoanTarget !== forLoan) return;
      forgiveBudgets_ = data.budgets || [];
      updateForgiveBudgetNote_();
    }).catch(() => {});
  }

  const backdrop = document.getElementById("forgive-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}

let forgiveBudgets_ = null;
function updateForgiveBudgetNote_() {
  const note = document.getElementById("forgive-budget-note");
  const loan = forgiveLoanTarget;
  const categoryId = document.getElementById("forgive-category").value;
  const date = document.getElementById("forgive-date").value;
  const amount = parseFloat(document.getElementById("forgive-amount").value.replace(",", "."));
  note.hidden = true;
  if (!loan || !forgiveBudgets_ || !categoryId || !date || !(amount > 0)) return;
  // Budgets covering this category whose current period holds the date, in the loan's own currency (no conversion guessed here).
  const hits = forgiveBudgets_.filter((b) => {
    const p = b.progress;
    return p && p.spent != null && p.effectiveAmount > 0 && b.currency === loan.currency &&
      (!b.category_ids || b.category_ids.includes(categoryId)) && p.startDate <= date && date <= p.endDate;
  }).map((b) => ({ b, after: b.progress.spent + amount, pct: (b.progress.spent + amount) / b.progress.effectiveAmount * 100 }));
  if (!hits.length) return;
  hits.sort((x, y) => y.pct - x.pct);
  const h = hits[0];
  note.textContent = tr("forgive.budgetAfter", { name: h.b.category_name, pct: Math.round(h.pct), cur: h.b.currency,
    spent: moneyFmt(h.after), amount: moneyFmt(h.b.progress.effectiveAmount) });
  note.classList.toggle("over", h.pct >= 100);
  note.hidden = false;
}
["forgive-amount", "forgive-category", "forgive-date"].forEach((id) => {
  document.getElementById(id).addEventListener("input", updateForgiveBudgetNote_);
  document.getElementById(id).addEventListener("change", updateForgiveBudgetNote_);
});

function closeForgiveModal() {
  document.getElementById("forgive-modal-backdrop").hidden = true;
  forgiveLoanTarget = null;
  moneyReopen_ = null;
}

document.getElementById("forgive-modal-close").addEventListener("click", closeForgiveModal);
document.getElementById("forgive-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "forgive-modal-backdrop") closeForgiveModal();
});
document.getElementById("forgive-convert-checkbox").addEventListener("change", (e) => {
  document.getElementById("forgive-convert-fields").hidden = !e.target.checked;
});

document.getElementById("forgive-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("forgive-form-error");
  errorEl.textContent = "";
  if (!forgiveLoanTarget) return;

  const convert = forgiveLoanTarget.remaining > 0.004;
  const categoryId = document.getElementById("forgive-category").value;
  const date = document.getElementById("forgive-date").value;
  const amount = parseFloat(document.getElementById("forgive-amount").value.replace(",", "."));
  if (convert && !(amount > 0)) { errorEl.textContent = tr("error.validAmount"); return; }
  if (convert && !categoryId) { errorEl.textContent = tr("error.pickCategory"); return; }
  if (convert && !date) { errorEl.textContent = tr("error.dateRequired"); return; }

  if (convert && amount > forgiveLoanTarget.remaining + 0.004) {
    errorEl.textContent = tr("forgive.tooMuchPhone", { remaining: forgiveLoanTarget.remaining.toFixed(2) });
    return;
  }
  if (moneyBackground_()) {
    const target = forgiveLoanTarget;
    const returnFriend = forgiveReturnFriend;
    const replaces = takeMoneyReopen_("forgive");
    closeForgiveModal();
    const friend = meta.friends.find((f) => f.id === target.friend_id);
    queueMoneyAction_("forgiveLoan", {
      id: target.id,
      convert,
      ...(convert ? { amount } : {}),
      category_id: categoryId,
      date
    }, `${tr("money.labelForgive")} · ${friend ? friend.name : ""} ${target.currency} ${moneyFmt(convert ? amount : target.remaining)}`,
    {
      friendId: returnFriend ? returnFriend.id : target.friend_id, friendName: returnFriend ? returnFriend.name : (friend ? friend.name : ""), convert,
      // What the form needs to open again if this save fails.
      loan: { id: target.id, description: target.description, currency: target.currency, remaining: target.remaining, direction: target.direction, friend_id: target.friend_id }
    }, replaces);
    return;
  }

  const saveBtn = document.getElementById("forgive-save-btn");
  saveBtn.disabled = true;
  try {
    await callApi("forgiveLoan", {
      id: forgiveLoanTarget.id,
      convert,
      ...(convert ? { amount } : {}),
      category_id: categoryId,
      date
    });
    const returnFriend = forgiveReturnFriend;
    closeForgiveModal();
    await refreshLoans();
    if (returnFriend) await openLoanDetail(returnFriend.id, returnFriend.name);
    if (convert) await refreshEntryList();
  } catch (err) {
    errorEl.textContent = err.message;
  } finally {
    saveBtn.disabled = false;
  }
});

// ---- Review queue: Mark as repayment / Convert to loan (Phase 5.7) ----
// Email parsing only catches money the owner sent OUT (expenses); a pending
// INCOME comes from a "Te Yapearon" photo or a manual entry. Either way the
// direction follows the entry's type, so there's nothing to pick. For a
// pending EXPENSE:
// - "Mark as repayment" means the owner paying this money down what THEY
//   owed the friend — direction 'i_owe_them', through the exact same
//   recordRepayment FIFO + offset engine the Loans tab's own "Record
//   repayment" uses (see CLAUDE.md's Settlements section).
// - "Convert to loan" means the owner lending this money to the friend
//   — direction 'they_owe_me' (the friend now owes it back), through the
//   same addLoan as the Loans tab's "+ Add loan" (including its own
//   +7-day due-date default when none's given).
// For a pending INCOME the friend is on the other side: "Mark as repayment" =
// they pay back what they owed (they_owe_me paid down, and refused with
// nothing written if no such debt exists — require_owed), "Convert to loan"
// = they lent it to the owner (i_owe_them).
// Either way, the pending entry itself is discarded afterward — it was
// never really an expense/income, so it shouldn't become a confirmed one.

let reviewTransferEntry = null;
let reviewTransferMode = null; // "repay" | "loan"

function populateReviewTransferFriendOptions() {
  const select = document.getElementById("review-transfer-friend");
  select.innerHTML = "";
  plainFriends_().forEach((f) => {
    const opt = document.createElement("option");
    opt.value = f.id;
    opt.textContent = friendLabel_(f);
    select.appendChild(opt);
  });
  const addOpt = document.createElement("option");
  addOpt.value = "__add__";
  addOpt.textContent = tr("common.addFriend");
  select.appendChild(addOpt);
}

document.getElementById("review-transfer-friend").addEventListener("change", async (e) => {
  if (e.target.value !== "__add__") return;
  const name = await askName_(tr("prompt.friendName"));
  e.target.value = meta.friends.length ? meta.friends[0].id : "";
  if (name && name.trim()) {
    const friend = await callApi("addFriend", { name: name.trim() });
    meta.friends.push(friend);
    refreshFriendChips_();
    populateReviewTransferFriendOptions();
    document.getElementById("review-transfer-friend").value = friend.id;
  }
});

function populateReviewTransferPaymentMethodOptions() {
  const select = document.getElementById("review-transfer-payment-method");
  select.innerHTML = "";
  // Like the new-entry form: just the accounts (no platforms), no "None" row. Only with no account at all does it say so.
  const accounts = meta.paymentMethods.filter((pm) => pm.type !== "investment" && !pmHidden_(pm));
  if (!accounts.length) {
    const noneOpt = document.createElement("option");
    noneOpt.value = "";
    noneOpt.textContent = tr("form.noneAccount");
    select.appendChild(noneOpt);
  }
  accounts.forEach((pm) => {
    const opt = document.createElement("option");
    opt.value = pm.id;
    opt.textContent = pmPickLabel_(pm);
    select.appendChild(opt);
  });
}

// Did the money of this waiting entry ARRIVE (an income, an investment withdrawal)? Otherwise it left.
function reviewEntryArrived_(entry) {
  return entry.type === "income" || (entry.type === "investment" && Number(entry.amount) < 0);
}

function openReviewTransferModal(entry, mode) {
  reviewTransferEntry = entry;
  reviewTransferMode = mode;

  document.getElementById("review-transfer-modal-title").textContent =
    mode === "repay" ? tr("review.repayTitle") : tr("review.loanTitle");
  // Say which way the money moves — it follows the entry's type (an income
  // is money that came IN, so the friend is the one paying/lending).
  const incoming = reviewEntryArrived_(entry);
  document.getElementById("review-transfer-context").textContent =
    `${entry.description || tr("review.transactionFallback")} · ${entry.currency} ${moneyFmt(entry.amount)}` +
    (incoming
      ? (mode === "repay" ? tr("review.contextRepay") : tr("review.contextLoan"))
      : "");
  document.getElementById("review-transfer-form-error").textContent = "";

  populateReviewTransferFriendOptions();
  populateReviewTransferPaymentMethodOptions();
  // A place the person turned into a loan / repayment before suggests the same friend (backend/PayeeGuess.gs).
  const hintedFriend = entry.loan_hint && meta.friends.find((f) => f.id === entry.loan_hint.friend_id);
  // Otherwise a repayment starts on the friend with the biggest debt it can pay off (money that left pays what the owner
  // owes; money that arrived, what a friend owes), in the entry's currency: the first friend in the list, owed nothing,
  // turned the whole payment into an "extra" waiting in Needs review again.
  const sign = incoming ? 1 : -1;
  const owedFriend = mode === "repay" && !hintedFriend && (loansLastBalances_ || [])
    .map((b) => ({ id: b.friend_id, net: ((b.balances || []).find((l) => l.currency === entry.currency) || {}).net || 0 }))
    .filter((b) => sign * b.net > 0.004 && plainFriends_().some((f) => f.id === b.id))
    .sort((x, y) => Math.abs(y.net) - Math.abs(x.net))[0];
  document.getElementById("review-transfer-friend").value = hintedFriend ? hintedFriend.id : owedFriend ? owedFriend.id : (meta.friends.length ? meta.friends[0].id : "");
  document.getElementById("review-transfer-amount").value = Math.abs(Number(entry.amount));
  document.getElementById("review-transfer-date").value = entry.date;
  // The account the bank e-mail named stays (it used to be dropped, leaving the repayment / loan with no account).
  // Even a hidden one. With no account (the e-mail named no card the app knows), the box says to pick one instead of
  // showing a blank, and Save asks for it: a repayment saved with no account moved no account's money.
  const pmSelect = document.getElementById("review-transfer-payment-method");
  keepHiddenAccountOption_("review-transfer-payment-method", entry.payment_method_id);
  pmSelect.value = entry.payment_method_id || "";
  if (pmSelect.selectedIndex < 0 && pmSelect.options.length) {
    const pick = document.createElement("option");
    pick.value = "";
    pick.textContent = tr(incoming ? "review.pickAccountEntered" : "review.pickAccountLeft");
    pmSelect.insertBefore(pick, pmSelect.firstChild);
    pmSelect.value = "";
  }
  // Both modes now generate a `transfer` Entry for the real money moved
  // (see CLAUDE.md's Loans/Settlements sections) — this description feeds
  // that entry either way, pre-filled from the original pending
  // transaction but editable, so a custom description actually sticks
  // instead of silently falling back to the pending entry's own text.
  document.getElementById("review-transfer-description").value = entry.description || "";
  document.getElementById("review-transfer-save-btn").textContent =
    mode === "repay" ? tr("review.repayTitle") : tr("review.loanTitle");

  const backdrop = document.getElementById("review-transfer-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;
}

function closeReviewTransferModal() {
  document.getElementById("review-transfer-modal-backdrop").hidden = true;
  reviewTransferEntry = null;
  reviewTransferMode = null;
}

document.getElementById("review-transfer-modal-close").addEventListener("click", closeReviewTransferModal);
document.getElementById("review-transfer-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "review-transfer-modal-backdrop") closeReviewTransferModal();
});

document.getElementById("review-transfer-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("review-transfer-form-error");
  errorEl.textContent = "";
  if (!reviewTransferEntry) return;

  const friendId = document.getElementById("review-transfer-friend").value;
  const friendName = (meta.friends.find((f) => f.id === friendId) || {}).name || "";
  const amount = parseFloat(document.getElementById("review-transfer-amount").value);
  const date = document.getElementById("review-transfer-date").value;
  const paymentMethodId = document.getElementById("review-transfer-payment-method").value;

  if (!friendId || friendId === "__add__") { errorEl.textContent = tr("error.pickFriend"); return; }
  if (!amount || amount <= 0) { errorEl.textContent = tr("error.validAmount"); return; }
  if (!date) { errorEl.textContent = tr("error.dateRequired"); return; }
  const hasAccounts = meta.paymentMethods.some((pm) => pm.type !== "investment" && !pmHidden_(pm));
  if (!paymentMethodId && hasAccounts) {
    errorEl.textContent = tr(reviewEntryArrived_(reviewTransferEntry) ? "error.pickAccountEntered" : "error.pickAccountLeft");
    return;
  }

  const entryId = reviewTransferEntry.id;
  const currency = reviewTransferEntry.currency;
  const description = document.getElementById("review-transfer-description").value.trim() ||
    reviewTransferEntry.description || "";
  const incoming = reviewEntryArrived_(reviewTransferEntry);
  const mode = reviewTransferMode;
  closeReviewTransferModal();
  dropReviewCard_(entryId);   // gone at once; a refusal's refresh below brings it back

  // Saves behind the screen. One server call per swap (convertEntryToRepayment / convertEntryToLoan): everything is checked
  // first and the waiting entry is put back if anything fails, so a refusal (an income with no debt on record, say) leaves
  // the entry exactly as it was and comes back as an alert. A repayment's extra waits in the review queue (overpay_pending_ok).
  saveBehindScreen_(async () => {
    if (mode === "repay") {
      const result = await callApi("convertEntryToRepayment", {
        entry_id: entryId,
        friend_id: friendId,
        direction: incoming ? "they_owe_me" : "i_owe_them",
        amount,
        currency,
        date,
        payment_method_id: paymentMethodId,
        description,
        require_owed: incoming,
        overpay_pending_ok: true
      });
      if (result.overpaid > 0.004) {
        alert(tr(incoming ? "review.overpaidIncoming" : "review.overpaidOutgoing", { name: friendName, cur: currency, amount: moneyFmt(result.overpaid) }));
      }
    } else {
      await callApi("convertEntryToLoan", {
        entry_id: entryId,
        friend_id: friendId,
        direction: incoming ? "i_owe_them" : "they_owe_me",
        amount,
        currency,
        date,
        payment_method_id: paymentMethodId,
        description
      });
    }
  }, async () => {
    refreshEntriesInBackground_();
    await refreshReviewQueue();
    refreshLoans().catch(() => {});
  });
});

// ---- Account balances (Overview) ----
// See Balances.gs. Not period-based — always "right now" — so it's fetched
// when Overview is shown (and after a balance edit), not on every period
// change.

let balanceModalPmId = null;
let balanceModalData = null;

function refreshBalances() { return trackOverviewLoad_(refreshBalancesInner_()); }

async function refreshBalancesInner_() {
  const list = document.getElementById("balances-list");
  const emptyNote = document.getElementById("balances-empty-note");
  const rows = await callApi("listPaymentMethodBalances", {});
  balancesCache = rows;
  list.innerHTML = "";
  emptyNote.hidden = rows.length > 0;
  rows.forEach((r) => {
    const row = document.createElement("div");
    row.className = "balance-row";
    const [main, ...others] = r.balances;
    const otherText = others.filter((b) => Math.abs(b.amount) > 0.004).map((b) => formatSignedBalance_(b.amount, b.currency) + (b.waiting ? ` (${tr("charge.waiting")})` : "")).join(" · ");
    row.innerHTML = `
      <div class="balance-row-name">${escapeHtml(r.nickname)}<span class="loan-detail-row-chevron">›</span>${r.bank_name ? `<div class="balance-row-meta">${escapeHtml(r.bank_name)}</div>` : ""}</div>
      <div class="balance-row-amount ${main.amount < 0 ? "negative" : ""}">${formatSignedBalance_(main.amount, main.currency)}${otherText ? `<div class="balance-row-meta">${escapeHtml(otherText)}</div>` : ""}</div>
    `;
    row.addEventListener("click", () => openBalanceModal(r.id));
    list.appendChild(row);
  });

  // Net per currency across every tracked account (a credit card's
  // negative balance nets against positive ones). No cross-currency
  // conversion — each currency stands on its own.
  const totals = {};
  rows.forEach((r) => r.balances.forEach((b) => { totals[b.currency] = (totals[b.currency] || 0) + b.amount; }));
  const codes = Object.keys(totals).sort((a, b) => (a === homeCur() ? -1 : b === homeCur() ? 1 : a < b ? -1 : 1));
  const totalsWrap = document.getElementById("balances-totals");
  const totalsLines = document.getElementById("balances-totals-lines");
  totalsLines.innerHTML = "";
  totalsWrap.hidden = codes.length === 0;
  balancesRowCount_ = rows.length;
  applyBalancesExpanded_();
  codes.forEach((code) => {
    const amount = Math.round(totals[code] * 100) / 100;
    const line = document.createElement("div");
    line.className = "balances-totals-line" + (amount < 0 ? " negative" : "");
    line.innerHTML = `<span>${code === homeCur() ? "" : findCurrency(code).flag + " "}${code}</span><span>${formatSignedBalance_(amount, code)}</span>`;
    totalsLines.appendChild(line);
  });
}

let balancesCache = [];

// The Balances card opens showing only the net per currency; the accounts
// (this person's own tracked ones) appear when it is expanded.
let balancesExpanded_ = false;
let balancesRowCount_ = 0;
function applyBalancesExpanded_() {
  document.getElementById("balances-list").hidden = !balancesExpanded_;
  const btn = document.getElementById("balances-toggle");
  btn.setAttribute("aria-expanded", String(balancesExpanded_));
  btn.textContent = balancesExpanded_ ? tr("balances.hideAccounts") : tr("balances.showAccounts", { n: balancesRowCount_ });
}
document.getElementById("balances-toggle").addEventListener("click", () => {
  balancesExpanded_ = !balancesExpanded_;
  applyBalancesExpanded_();
});

function formatSignedBalance_(amount, currency) {
  return `${amount < 0 ? "−" : ""}${currency} ${moneyFmt(Math.abs(amount))}`;
}

// `pmId` set → that account's detail; null → "+ Add balance" (pick any
// account that isn't tracked yet).
async function openBalanceModal(pmId) {
  balanceModalPmId = pmId;
  document.getElementById("balance-form-error").textContent = "";
  document.getElementById("balance-check-input").value = "";
  document.getElementById("balance-check-result").textContent = "";

  const pickerWrap = document.getElementById("balance-account-picker-wrap");
  const picker = document.getElementById("balance-account-picker");
  if (!pmId) {
    // Every account is listed, including ones that already have a
    // balance — picking one of those loads its existing rows, so adding
    // another currency to it works from here too.
    picker.innerHTML = "";
    meta.paymentMethods.filter((pm) => pm.type !== "investment" && !pmHidden_(pm)).forEach((pm) => {
      const opt = document.createElement("option");
      opt.value = pm.id;
      const tracked = balancesCache.some((b) => b.id === pm.id);
      opt.textContent = pmPickLabel_(pm) + (tracked ? " ✓" : "");
      picker.appendChild(opt);
    });
    if (!meta.paymentMethods.length) {
      alert(tr("balance.noAccounts"));
      return;
    }
    pickerWrap.hidden = false;
    document.getElementById("balance-modal-title").textContent = tr("balance.addTitle");
    balanceModalData = null;
    document.getElementById("balance-current").hidden = true;
    document.getElementById("balance-movements-wrap").hidden = true;
    document.getElementById("balance-clear-btn").hidden = true;
    picker.onchange = () => { loadBalanceRowsFor_(picker.value); renderBalanceRows_(); };
    loadBalanceRowsFor_(picker.value);
  } else {
    pickerWrap.hidden = true;
    balanceModalData = balancesCache.find((b) => b.id === pmId);
    document.getElementById("balance-modal-title").textContent = balanceModalData.nickname;
    document.getElementById("balance-current").hidden = false;
    document.getElementById("balance-clear-btn").hidden = false;
    loadBalanceRowsFor_(pmId);
    renderBalanceCurrentLines_();
  }
  renderBalanceRows_();

  const backdrop = document.getElementById("balance-modal-backdrop");
  bringModalToFront_(backdrop);
  backdrop.hidden = false;

  if (pmId) await loadBalanceMovements_(pmId);
}

function renderBalanceCurrentLines_() {
  const el = document.getElementById("balance-current-lines");
  el.innerHTML = "";
  balanceModalData.balances.forEach((b, i) => {
    if (i > 0 && Math.abs(b.amount) <= 0.004) return;
    const line = document.createElement("div");
    line.className = "balance-current-line" + (b.amount < 0 ? " negative" : "");
    line.textContent = formatSignedBalance_(b.amount, b.currency) + (b.waiting ? ` · ${tr("charge.waiting")}` : "");
    el.appendChild(line);
  });
  const sel = document.getElementById("balance-check-currency");
  sel.innerHTML = balanceModalData.balances.map((b) => `<option value="${b.currency}">${b.currency}</option>`).join("");
  sel.hidden = balanceModalData.balances.length < 2;
}

async function loadBalanceMovements_(pmId) {
  const wrap = document.getElementById("balance-movements-wrap");
  const list = document.getElementById("balance-movements");
  list.innerHTML = loadingHtml_();
  wrap.hidden = false;
  const moves = await callApi("getPaymentMethodMovements", { paymentMethodId: pmId });
  if (balanceModalPmId !== pmId) return;
  list.innerHTML = "";
  if (!moves.length) {
    list.innerHTML = `<p class="hint">${escapeHtml(tr("balance.nothingSince"))}</p>`;
    return;
  }
  moves.forEach((m) => {
    const row = document.createElement("div");
    row.className = "loan-detail-row";
    const label = m.description || TYPE_LABELS[m.type] || m.type;
    const extra = m.type === "transfer" && m.other_account ? tr(m.signed < 0 ? "balance.moveTo" : "balance.moveFrom", { account: escapeHtml(m.other_account) }) : "";
    row.innerHTML = `
      <div class="loan-detail-row-top">
        <span class="loan-detail-row-desc">${escapeHtml(label)}</span>
        <span class="loan-detail-row-amount ${m.signed > 0 ? "owed-to-me" : "i-owe"}">${m.signed > 0 ? "+" : "−"}${m.currency} ${moneyFmt(Math.abs(m.signed))}</span>
      </div>
      <div class="loan-detail-row-meta">${listDate_(m.date)} · ${m.type}${extra}</div>
    `;
    list.appendChild(row);
  });
}

let balanceFormRows = [];
let balanceFormPmId_ = "";
// A credit card's balance is what is owed on it: its new rows start with "Negative — I owe this" ticked (owner, 2026-11-02).
function balanceNegDefault_() {
  const pm = ((meta && meta.paymentMethods) || []).find((p) => p.id === balanceFormPmId_);
  return !!pm && pm.type === "credit";
}

// Rows for the form: the account's saved balances if it has any, else one
// blank PEN row.
function loadBalanceRowsFor_(pmId) {
  balanceFormPmId_ = pmId || "";
  const existing = balancesCache.find((b) => b.id === pmId);
  balanceFormRows = existing
    ? existing.openings.map((o) => ({
        amount: String(Math.abs(o.amount)),
        negative: o.amount < 0,
        currency: o.currency,
        date: o.date || todayLocalISO(),
        // The saved snapshot, so the note can tell an untouched row (keeps its
        // moment on save — setPaymentMethodOpeningBalance) from a changed one.
        saved: { amount: o.amount, currency: o.currency, date: o.date || "", asOf: o.as_of || "" }
      }))
    : [{ amount: "", negative: balanceNegDefault_(), currency: homeCur(), date: todayLocalISO() }];
}

// What moment a balance row stands for, in words. Mirrors the backend: a row
// left unchanged keeps its saved moment; a row dated today is stamped with the
// moment it is saved ("right now"); any other date counts from the start of
// that day.
function balanceRowAsOfNote_(row) {
  const s = row.saved;
  const text = String(row.amount).trim().replace(/,/g, "").replace(/[−–]/g, "-");
  const parsed = parseFloat(text);
  const amount = isNaN(parsed) ? null : (row.negative ? -Math.abs(parsed) : parsed);
  if (s && s.asOf && s.currency === row.currency && s.date === row.date && amount === s.amount) {
    return tr("balance.asOfSaved", { when: I18n.fmtDateTime(new Date(s.asOf)) });
  }
  if (row.date === todayLocalISO()) return tr("balance.asOfNow", { when: I18n.fmtDateTime(new Date()) });
  if (!row.date) return "";
  return tr("balance.asOfDayStart", { date: I18n.fmtDateMedium(new Date(row.date + "T00:00:00")) });
}

function renderBalanceRows_() {
  const wrap = document.getElementById("balance-rows");
  wrap.innerHTML = "";
  balanceFormRows.forEach((row, i) => {
    const el = document.createElement("div");
    el.className = "balance-form-row";
    const currencyOpts = CURRENCIES.map((c) => `<option value="${c.code}"${c.code === row.currency ? " selected" : ""}>${c.flag} ${c.code}</option>`).join("");
    el.innerHTML = `
      <div class="balance-form-row-main">
        <input type="text" inputmode="decimal" class="balance-row-amount-input" data-amount-kind="signed" placeholder="0.00" value="${escapeHtml(row.amount)}">
        <select class="balance-row-currency-select">${currencyOpts}</select>
        ${balanceFormRows.length > 1 ? `<button type="button" class="balance-row-remove" aria-label="${escapeHtml(tr("balance.remove"))}">✕</button>` : ""}
      </div>
      <label class="checkbox-row"><input type="checkbox" class="balance-row-negative"${row.negative ? " checked" : ""}><span>${tr("balance.negative")}</span></label>
      <label class="balance-row-date-label">${tr("balance.fromDate")}</label>
      <input type="date" class="balance-row-date" value="${row.date}">
      <p class="hint balance-row-asof"></p>
    `;
    const note = el.querySelector(".balance-row-asof");
    const showNote = () => { note.textContent = balanceRowAsOfNote_(row); };
    showNote();
    el.querySelector(".balance-row-amount-input").addEventListener("input", (e) => { row.amount = e.target.value; showNote(); });
    currencyPickOn_(el.querySelector(".balance-row-currency-select"));
    el.querySelector(".balance-row-currency-select").addEventListener("change", (e) => { row.currency = e.target.value; showNote(); });
    el.querySelector(".balance-row-negative").addEventListener("change", (e) => { row.negative = e.target.checked; showNote(); });
    el.querySelector(".balance-row-date").addEventListener("change", (e) => { row.date = e.target.value; showNote(); });
    const rm = el.querySelector(".balance-row-remove");
    if (rm) rm.addEventListener("click", () => { balanceFormRows.splice(i, 1); renderBalanceRows_(); });
    wrap.appendChild(el);
  });
}

document.getElementById("balance-add-row-btn").addEventListener("click", () => {
  const used = new Set(balanceFormRows.map((r) => r.currency));
  const next = ["USD", homeCur(), "EUR"].find((c) => !used.has(c)) || "USD";
  balanceFormRows.push({ amount: "", negative: balanceNegDefault_(), currency: next, date: todayLocalISO() });
  renderBalanceRows_();
});

function closeBalanceModal() {
  document.getElementById("balance-modal-backdrop").hidden = true;
  balanceModalPmId = null;
  balanceModalData = null;
}

document.getElementById("add-balance-btn").addEventListener("click", () => openBalanceModal(null));
document.getElementById("balance-modal-close").addEventListener("click", closeBalanceModal);
document.getElementById("balance-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "balance-modal-backdrop") closeBalanceModal();
});

// "Check against my app": compares what the real app/statement shows with
// what this app computes, in the account's own (starting-balance)
// currency, and says which way the gap goes — nothing is saved.
document.getElementById("balance-check-currency").addEventListener("change", () => document.getElementById("balance-check-input").dispatchEvent(new Event("input")));
document.getElementById("balance-check-input").addEventListener("input", (e) => {
  const result = document.getElementById("balance-check-result");
  const text = e.target.value.trim().replace(/,/g, "").replace(/[−–]/g, "-");
  if (!text || !balanceModalData) { result.textContent = ""; return; }
  const actual = parseFloat(text);
  if (isNaN(actual)) { result.textContent = ""; return; }
  const main = balanceModalData.balances.find((b) => b.currency === document.getElementById("balance-check-currency").value) || balanceModalData.balances[0];
  const diff = Math.round((actual - main.amount) * 100) / 100;
  if (Math.abs(diff) < 0.005) {
    result.style.color = "var(--income)";
    result.textContent = tr("balance.matches");
  } else {
    result.style.color = "#d64545";
    result.textContent = diff > 0
      ? tr("balance.more", { cur: main.currency, amount: moneyFmt(diff) })
      : tr("balance.less", { cur: main.currency, amount: moneyFmt(-diff) });
  }
});

document.getElementById("balance-save-btn").addEventListener("click", async () => {
  const errorEl = document.getElementById("balance-form-error");
  errorEl.textContent = "";
  const saveBtn = document.getElementById("balance-save-btn");
  try {
    const pmId = balanceModalPmId || document.getElementById("balance-account-picker").value;
    if (!pmId) throw new Error(tr("balance.pickAccount"));
    const seen = new Set();
    const balances = balanceFormRows.map((row) => {
      const text = String(row.amount).trim().replace(/,/g, "").replace(/[−–]/g, "-");
      const parsed = parseFloat(text);
      if (!text || isNaN(parsed)) throw new Error(tr("balance.enterStarting", { cur: row.currency }));
      if (!row.date) throw new Error(tr("balance.pickFromDate", { cur: row.currency }));
      if (seen.has(row.currency)) throw new Error(tr("balance.listedTwice", { cur: row.currency }));
      seen.add(row.currency);
      // Typed minus or the checkbox both mean negative; never double-negate.
      return { currency: row.currency, amount: row.negative ? -Math.abs(parsed) : parsed, date: row.date };
    });
    closeBalanceModal();
    saveBehindScreen_(practiceATrackBalance_(pmId, () => callApi("setPaymentMethodOpeningBalance", { id: pmId, balances })), refreshBalances);
  } catch (err) {
    errorEl.textContent = err.message;
  } finally {
    saveBtn.disabled = false;
  }
});

document.getElementById("balance-clear-btn").addEventListener("click", async () => {
  if (!balanceModalPmId) return;
  if (!confirm(tr("balance.confirmStop"))) return;
  const pmId = balanceModalPmId;
  try {
    await callApi("setPaymentMethodOpeningBalance", { id: pmId, balances: [] });
    closeBalanceModal();
    await refreshBalances();
  } catch (err) {
    document.getElementById("balance-form-error").textContent = err.message;
  }
});

// ---- Split a bill by items ----
// A sheet opened from the expense form's split section. The maths lives in
// bill-split.js (tested on its own); this is only the screen. "Use this split"
// fills the normal form: amount = bill + tip, split switched on in Custom mode
// with each friend's total — the entry is then saved the usual way, so
// category, account, date and the debts all go through the existing flow.
let billState = null;
// The text the entry form's photo reader already read: a blank "split by items" starts from it instead of asking for the photo again.
let receiptFormText_ = "";
// The photo itself, kept in the phone's memory only (never saved or sent) until the entry is left, so the items split can read it again.
let receiptFormFile_ = null;
let billItemsEdited = false;    // items typed/changed/inserted by hand since the last photo read
let billApplied = false;        // "Use this split" was pressed in this form session
let billNextId = 1;
let billShowAllFriends = false;

function newBillState_() {
  return {
    total: "",
    people: new Set(),
    items: [],
    adjs: [],
    // A percent and a fixed amount are different numbers — each keeps its own
    // value, so "100" typed as an amount can't turn into 100% on switching tabs.
    tip: { type: "percent", percent: "", amount: "", mode: "proportional" }
  };
}

function billFriendName_(id) {
  if (id === "me") return tr("common.me");
  const f = meta.friends.find((x) => x.id === id);
  return f ? f.name : "?";
}

function billPeopleKeys_() {
  return ["me", ...Array.from(billState.people)];
}

function billInput_() {
  return {
    people: billPeopleKeys_(),
    items: billState.items.map((it) => ({
      id: it.id, name: it.name, people: Array.from(it.people),
      price: it.discount && it.price ? "-" + it.price : it.price     // a discount line is a negative line
    })),
    adjustments: billState.adjs.map((a) => ({
      name: a.name,
      amount: (a.kind === "discount" ? -1 : 1) * (parseFloat(a.amount) || 0),
      mode: a.mode
    })),
    tip: { type: billState.tip.type, mode: billState.tip.mode, value: billState.tip.type === "percent" ? billState.tip.percent : billState.tip.amount },
    printedTotal: billState.total
  };
}

// The stored form of a bill (see backend/EntryBills.gs): plain JSON, versioned,
// holding only what the person typed — never the computed amounts.
function billToJSON_() {
  return {
    v: 1,
    total: billState.total,
    people: Array.from(billState.people),
    items: billState.items.map((it) => ({ id: it.id, name: it.name, price: it.price, people: Array.from(it.people), discount: !!it.discount })),
    adjs: billState.adjs.map((a) => ({ id: a.id, kind: a.kind, name: a.name, amount: a.amount, mode: a.mode })),
    tip: { type: billState.tip.type, percent: billState.tip.percent, amount: billState.tip.amount, mode: billState.tip.mode }
  };
}

// Friends deleted since the bill was saved are quietly dropped.
function billFromJSON_(j) {
  const known = new Set(meta.friends.map((f) => f.id));
  const st = newBillState_();
  st.total = String(j.total || "");
  st.people = new Set((j.people || []).filter((id) => known.has(id)));
  st.items = (j.items || []).map((it) => ({
    id: it.id, name: it.name || "", price: String(it.price || ""), discount: !!it.discount,
    people: new Set((it.people || []).filter((id) => id === "me" || st.people.has(id)))
  }));
  st.adjs = (j.adjs || []).map((a) => ({ id: a.id, kind: a.kind === "charge" ? "charge" : "discount", name: a.name || "", amount: String(a.amount || ""), mode: a.mode === "equal" ? "equal" : "proportional" }));
  const t = j.tip || {};
  st.tip = { type: t.type === "amount" ? "amount" : "percent", percent: String(t.percent || ""), amount: String(t.amount || ""), mode: t.mode === "equal" ? "equal" : "proportional" };
  billNextId = Math.max(billNextId, ...st.items.map((x) => Number(x.id) || 0), ...st.adjs.map((x) => Number(x.id) || 0)) + 1;
  return st;
}

// Does what the bill works out to still equal the entry as it stands in the
// form (its amount and each friend's share)? False after the amount or the
// split was changed by hand since the bill was saved.
function billMatchesForm_() {
  const res = BillSplit.compute(billInput_());
  if (!res.ok) return false;
  const amountCents = Math.round((parseFloat(document.getElementById("amount").value) || 0) * 100);
  if (amountCents !== res.grandCents) return false;
  if (!document.getElementById("split-toggle").checked) return Array.from(billState.people).every((id) => res.perPerson[id].total === 0);
  const now = {};
  getSplitPayload().forEach((x) => { now[x.friend_id] = Math.round(x.amount * 100); });
  return Array.from(billState.people).every((id) => (now[id] || 0) === res.perPerson[id].total) &&
    Object.keys(now).every((id) => billState.people.has(id));
}

async function openBillModal() {
  let loadedSaved = false;
  // Reopening a saved entry: fetch the bill that was stored with it (on demand,
  // so the entry list never has to carry it).
  if (!billState && editingEntryId) {
    const btn = document.getElementById("bill-open-btn");
    const label = btn.textContent;
    btn.disabled = true;
    btn.textContent = tr("bill.loadingSaved");
    try {
      const r = await callApi("getEntryBill", { entryId: editingEntryId });
      if (r && r.bill) { billState = billFromJSON_(r.bill); loadedSaved = true; }
    } catch (err) {
      /* no saved bill (or it could not be read) — start a blank one */
    } finally {
      btn.disabled = false;
      btn.textContent = label;
    }
  }
  if (!billState) {
    billState = newBillState_();
    document.getElementById("bill-photo-status").hidden = true;
    document.getElementById("bill-photo-raw").hidden = true;
    const known = receiptFormText_ ? ReceiptParse.parseReceipt(receiptFormText_) : null;
    if (known && known.items.length) {
      applyReceiptToBill_(known, { noConfirm: true });
      document.getElementById("bill-photo-text").value = receiptFormText_;
      document.getElementById("bill-photo-raw").hidden = false;
      const dishes = known.items.filter((i) => !i.discount).length;
      billPhotoSay_(tr("bill.fromFormPhoto", { n: dishes }) + (known.warnings.length ? " " + known.warnings.join(" ") : ""), known.warnings.length > 0);
    }
  }
  document.getElementById("bill-photo-again").hidden = !receiptFormFile_;
  document.getElementById("bill-currency").textContent = (document.getElementById("currency").value || homeCur()).toUpperCase();
  document.getElementById("bill-total").value = billState.total;
  syncBillTabs_();
  renderBillPeople_();
  renderBillItems_();
  renderBillAdjs_();
  recomputeBill_();
  const stale = document.getElementById("bill-stale-note");
  stale.hidden = !(loadedSaved && !billMatchesForm_());
  document.getElementById("bill-modal-backdrop").hidden = false;
}

function closeBillModal() {
  document.getElementById("bill-modal-backdrop").hidden = true;
}

function syncBillTabs_() {
  document.querySelectorAll("#bill-tip-type-tabs .type-tab").forEach((t) => t.classList.toggle("active", t.dataset.v === billState.tip.type));
  document.querySelectorAll("#bill-tip-mode-tabs .type-tab").forEach((t) => t.classList.toggle("active", t.dataset.v === billState.tip.mode));
  const isPercent = billState.tip.type === "percent";
  const cur = (document.getElementById("currency").value || homeCur()).toUpperCase();
  document.getElementById("bill-tip-label").textContent = isPercent ? tr("bill.tipPercentLabel") : tr("bill.tipAmountLabel", { cur });
  const box = document.getElementById("bill-tip-value");
  box.placeholder = isPercent ? "e.g. 10" : "0.00";
  box.value = isPercent ? billState.tip.percent : billState.tip.amount;
}

function renderBillPeople_() {
  const box = document.getElementById("bill-people-chips");
  box.innerHTML = "";
  const sorted = plainFriends_().sort((a, b) =>
    (billState.people.has(b.id) - billState.people.has(a.id)) || (b.last_used || "").localeCompare(a.last_used || ""));
  const LIMIT = 10;
  const shown = billShowAllFriends ? sorted : sorted.slice(0, Math.max(LIMIT, billState.people.size));
  shown.forEach((f) => {
    const chip = document.createElement("div");
    chip.className = "tag-chip" + (billState.people.has(f.id) ? " selected" : "");
    chip.textContent = f.name;
    chip.addEventListener("click", () => {
      if (billState.people.has(f.id)) {
        billState.people.delete(f.id);
        billState.items.forEach((it) => it.people.delete(f.id));
      } else {
        billState.people.add(f.id);
      }
      renderBillPeople_();
      renderBillItems_();
      recomputeBill_();
    });
    box.appendChild(chip);
  });
  if (sorted.length > shown.length || billShowAllFriends) {
    const more = document.createElement("div");
    more.className = "tag-chip more-chip";
    more.textContent = billShowAllFriends ? tr("common.less") : tr("common.more");
    more.addEventListener("click", () => { billShowAllFriends = !billShowAllFriends; renderBillPeople_(); });
    box.appendChild(more);
  }
}

function renderBillItems_() {
  const box = document.getElementById("bill-items");
  box.innerHTML = "";
  const keys = billPeopleKeys_();
  billState.items.forEach((it) => {
    const row = document.createElement("div");
    row.className = "bill-item";

    const line = document.createElement("div");
    line.className = "bill-item-line";
    const name = document.createElement("input");
    name.type = "text";
    name.className = "bill-item-name";
    name.placeholder = tr("bill.placeholderItem");
    name.value = it.name;
    name.addEventListener("input", () => { it.name = name.value; billItemsEdited = true; });
    const price = document.createElement("input");
    price.type = "text";
    price.inputMode = "decimal";
    price.className = "bill-item-price";
    price.placeholder = "0.00";
    price.value = it.price;
    price.addEventListener("input", (e) => {
      const clean = sanitizeAmountInputValue(e.target.value);
      if (clean !== e.target.value) e.target.value = clean;
      it.price = clean;
      billItemsEdited = true;
      recomputeBill_();
    });
    const del = document.createElement("button");
    del.type = "button";
    del.className = "bill-item-remove";
    del.textContent = "✕";
    del.addEventListener("click", () => {
      billState.items = billState.items.filter((x) => x !== it);
      billItemsEdited = true;
      renderBillItems_();
      recomputeBill_();
    });
    line.append(name, price, del);

    const chips = document.createElement("div");
    chips.className = "tags-list";
    if (it.discount) {
      // A discount line printed under a dish: it comes off the item above and
      // is shared by whoever shares THAT item, so it has no people of its own.
      row.classList.add("bill-item-discount");
      name.placeholder = tr("bill.placeholderDiscount");
      const idx = billState.items.indexOf(it);
      let parent = null;
      for (let i = idx - 1; i >= 0; i--) if (!billState.items[i].discount) { parent = billState.items[i]; break; }
      const note = document.createElement("div");
      note.className = "hint bill-discount-note";
      note.textContent = parent ? tr("bill.comesOff", { name: parent.name || tr("bill.itemAbove") }) : tr("bill.needsItemAbove");
      chips.appendChild(note);
    } else {
      const everyone = keys.every((k) => it.people.has(k));
      const all = document.createElement("div");
      all.className = "tag-chip" + (everyone ? " selected" : "");
      all.textContent = tr("bill.everyone");
      all.addEventListener("click", () => {
        if (everyone) it.people.clear(); else keys.forEach((k) => it.people.add(k));
        renderBillItems_();
        recomputeBill_();
      });
      chips.appendChild(all);
      keys.forEach((k) => {
        const chip = document.createElement("div");
        chip.className = "tag-chip" + (it.people.has(k) ? " selected" : "");
        chip.textContent = billFriendName_(k);
        chip.addEventListener("click", () => {
          if (it.people.has(k)) it.people.delete(k); else it.people.add(k);
          renderBillItems_();
          recomputeBill_();
        });
        chips.appendChild(chip);
      });
    }
    // The number pad has no minus key, so a line is marked as a discount here.
    const disc = document.createElement("div");
    disc.className = "tag-chip bill-discount-toggle" + (it.discount ? " selected" : "");
    disc.textContent = tr("bill.discountLine");
    disc.addEventListener("click", () => {
      it.discount = !it.discount;
      billItemsEdited = true;
      renderBillItems_();
      recomputeBill_();
    });
    chips.appendChild(disc);
    // A new line right under this one — order matters, because a discount line
    // comes off the item above it.
    const ins = document.createElement("div");
    ins.className = "tag-chip bill-insert-chip";
    ins.textContent = tr("bill.insertLine");
    ins.addEventListener("click", () => {
      const at = billState.items.indexOf(it) + 1;
      billState.items.splice(at, 0, { id: billNextId++, name: "", price: "", people: new Set() });
      billItemsEdited = true;
      renderBillItems_();
      recomputeBill_();
      const names = document.querySelectorAll("#bill-items .bill-item-name");
      if (names[at]) names[at].focus();
    });
    chips.appendChild(ins);

    row.append(line, chips);
    box.appendChild(row);
  });
}

function addBillItem_() {
  billItemsEdited = true;
  billState.items.push({ id: billNextId++, name: "", price: "", people: new Set() });
  renderBillItems_();
  recomputeBill_();
  const names = document.querySelectorAll("#bill-items .bill-item-name");
  if (names.length) names[names.length - 1].focus();
}

function renderBillAdjs_() {
  const box = document.getElementById("bill-adjs");
  box.innerHTML = "";
  billState.adjs.forEach((a) => {
    const row = document.createElement("div");
    row.className = "bill-item bill-adj";

    const line = document.createElement("div");
    line.className = "bill-item-line";
    const name = document.createElement("input");
    name.type = "text";
    name.className = "bill-item-name";
    name.placeholder = a.kind === "discount" ? tr("bill.placeholderDiscount") : tr("bill.placeholderCharge");
    name.value = a.name;
    name.addEventListener("input", () => { a.name = name.value; billItemsEdited = true; });
    const amt = document.createElement("input");
    amt.type = "text";
    amt.inputMode = "decimal";
    amt.className = "bill-item-price";
    amt.placeholder = "0.00";
    amt.value = a.amount;
    amt.addEventListener("input", (e) => {
      const clean = sanitizeAmountInputValue(e.target.value);
      if (clean !== e.target.value) e.target.value = clean;
      a.amount = clean;
      billItemsEdited = true;
      recomputeBill_();
    });
    const del = document.createElement("button");
    del.type = "button";
    del.className = "bill-item-remove";
    del.textContent = "✕";
    del.addEventListener("click", () => {
      billState.adjs = billState.adjs.filter((x) => x !== a);
      billItemsEdited = true;
      renderBillAdjs_();
      recomputeBill_();
    });
    line.append(name, amt, del);

    const tabs = document.createElement("div");
    tabs.className = "type-tabs budget-period-tabs";
    [["proportional", tr("bill.byOrdered")], ["equal", tr("split.equal")]].forEach(([v, label]) => {
      const t = document.createElement("div");
      t.className = "type-tab" + (a.mode === v ? " active" : "");
      t.textContent = label;
      t.addEventListener("click", () => {
        a.mode = v;
        tabs.querySelectorAll(".type-tab").forEach((x) => x.classList.toggle("active", x === t));
        recomputeBill_();
      });
      tabs.appendChild(t);
    });

    row.append(line, tabs);
    box.appendChild(row);
  });
}

function recomputeBill_() {
  const res = BillSplit.compute(billInput_());
  const cur = (document.getElementById("currency").value || homeCur()).toUpperCase();
  const fmt = (cents) => `${cur} ${moneyFmt(cents / 100)}`;

  const check = document.getElementById("bill-check");
  // The bill total is BEFORE discounts: items (+ any extra charge) must match
  // it; discounts come off afterwards, then the tip.
  const chargesCents = res.preDiscountCents - res.itemsCents;
  const counted = chargesCents ? tr("bill.countedCharges", { items: fmt(res.itemsCents), charges: fmt(chargesCents) }) : tr("bill.counted", { items: fmt(res.itemsCents) });
  const lead = chargesCents ? tr("bill.leadCharges", { counted, total: fmt(res.preDiscountCents) }) : tr("bill.leadPlain", { items: fmt(res.itemsCents) });
  if (res.printedCents > 0) {
    if (res.diffCents === 0) {
      check.className = "hint bill-check-ok";
      check.textContent = tr("bill.checkOk", { counted, printed: fmt(res.printedCents) }) +
        (res.discountsCents ? tr("bill.checkAfterDiscounts", { discounts: fmt(res.discountsCents), bill: fmt(res.billCents) }) : "");
    } else {
      check.className = "hint bill-check-bad";
      check.textContent = res.diffCents > 0
        ? tr("bill.checkShort", { lead, printed: fmt(res.printedCents), diff: fmt(res.diffCents) })
        : tr("bill.checkTooMuch", { lead, printed: fmt(res.printedCents), diff: fmt(-res.diffCents) });
    }
  } else {
    check.className = "hint";
    check.textContent = res.itemsCents ? tr("bill.itemsSoFar", { items: fmt(res.itemsCents) }) : "";
  }

  const out = document.getElementById("bill-result");
  out.innerHTML = "";
  if (res.itemsCents) {
    billPeopleKeys_().forEach((k) => {
      const p = res.perPerson[k];
      const row = document.createElement("div");
      row.className = "bill-result-row";
      const left = document.createElement("div");
      const nm = document.createElement("div");
      nm.textContent = billFriendName_(k);
      const sub = document.createElement("div");
      sub.className = "bill-result-sub";
      const bits = [tr("bill.subItems", { v: moneyFmt(p.items / 100) })];
      if (p.adjustments) bits.push(tr("bill.subAdjustments", { sign: p.adjustments < 0 ? "−" : "+", v: moneyFmt(Math.abs(p.adjustments) / 100) }));
      if (p.tip) bits.push(tr("bill.subTip", { v: moneyFmt(p.tip / 100) }));
      sub.textContent = bits.join(" · ");
      left.append(nm, sub);
      const right = document.createElement("strong");
      right.textContent = fmt(p.total);
      row.append(left, right);
      out.appendChild(row);
    });
    if (res.tipCents) {
      const t = document.createElement("p");
      t.className = "hint";
      t.textContent = tr("bill.tipTotal", { tip: fmt(res.tipCents), total: fmt(res.grandCents) });
      out.appendChild(t);
    }
  }
  // Live line under the tip box: what the typed tip actually comes to, so a
  // slip like 100 instead of 10 is obvious right where it is typed.
  const preview = document.getElementById("bill-tip-preview");
  const tipTyped = billState.tip.type === "percent" ? billState.tip.percent : billState.tip.amount;
  if (!tipTyped || !res.tipCents) {
    preview.className = "hint";
    preview.textContent = res.billCents > 0 ? tr("bill.tipBase", { bill: fmt(res.billCents) }) : "";
  } else {
    const pct = res.billCents > 0 ? (res.tipCents / res.billCents) * 100 : 0;
    const odd = pct > 30;
    preview.className = "hint" + (odd ? " bill-check-bad" : "");
    preview.textContent = billState.tip.type === "percent"
      ? tr("bill.tipPctOf", { pct: tipTyped, bill: fmt(res.billCents), tip: fmt(res.tipCents), odd: odd ? tr("bill.tipOdd") : "" })
      : tr("bill.tipIs", { tip: fmt(res.tipCents), pct: pct.toFixed(1), bill: fmt(res.billCents), odd: odd ? tr("bill.tipOdd") : "" });
  }
  const err = document.getElementById("bill-error");
  // Only the blocking reason that isn't already visible above.
  err.textContent = res.ok ? "" : res.errors.filter((e) => e !== tr("bill.err.dontAddUp")).join(" ");
  document.getElementById("bill-apply").disabled = !res.ok;
  return res;
}

function applyBillToForm_() {
  const res = recomputeBill_();
  if (!res.ok) return;
  const amountEl = document.getElementById("amount");
  amountEl.value = (res.grandCents / 100).toFixed(2);
  amountEl.dispatchEvent(new Event("input"));

  const friendIds = Array.from(billState.people).filter((id) => res.perPerson[id].total > 0);
  splitFriendIds = new Set(friendIds);
  customSplitAmounts = {};
  friendIds.forEach((id) => { customSplitAmounts[id] = (res.perPerson[id].total / 100).toFixed(2); });
  customOwnAmount = (res.perPerson.me.total / 100).toFixed(2);
  splitMode = "custom";
  splitFriendsExpanded = false;
  const on = friendIds.length > 0;
  document.getElementById("split-toggle").checked = on;
  document.getElementById("split-detail").hidden = !on;
  document.querySelectorAll("#split-mode-tabs .type-tab").forEach((t) => t.classList.toggle("active", t.dataset.mode === "custom"));
  renderSplitFriendChips();
  renderSplitRows();
  renderSplitSummary();
  billApplied = true;
  closeBillModal();
}

document.getElementById("bill-open-btn").addEventListener("click", openBillModal);
document.getElementById("bill-modal-close").addEventListener("click", closeBillModal);
document.getElementById("bill-modal-backdrop").addEventListener("click", (e) => {
  if (e.target.id === "bill-modal-backdrop") closeBillModal();
});
document.getElementById("bill-apply").addEventListener("click", applyBillToForm_);
document.getElementById("bill-add-item").addEventListener("click", addBillItem_);
document.getElementById("bill-add-discount").addEventListener("click", () => {
  billItemsEdited = true;
  billState.adjs.push({ id: billNextId++, kind: "discount", name: "", amount: "", mode: "proportional" });
  renderBillAdjs_();
  recomputeBill_();
});
document.getElementById("bill-add-charge").addEventListener("click", () => {
  billItemsEdited = true;
  billState.adjs.push({ id: billNextId++, kind: "charge", name: "", amount: "", mode: "proportional" });
  renderBillAdjs_();
  recomputeBill_();
});
document.getElementById("bill-add-friend").addEventListener("click", async () => {
  const name = await askName_(tr("prompt.friendName"));
  if (!name || !name.trim()) return;
  const friend = await callApi("addFriend", { name: name.trim() });
  friend.last_used = todayLocalISO();
  meta.friends.push(friend);
  refreshFriendChips_();
  billState.people.add(friend.id);
  renderBillPeople_();
  renderBillItems_();
  recomputeBill_();
});
document.getElementById("bill-total").addEventListener("input", (e) => {
  const clean = sanitizeAmountInputValue(e.target.value);
  if (clean !== e.target.value) e.target.value = clean;
  billState.total = clean;
  recomputeBill_();
});
document.getElementById("bill-tip-value").addEventListener("input", (e) => {
  const clean = sanitizeAmountInputValue(e.target.value);
  if (clean !== e.target.value) e.target.value = clean;
  if (billState.tip.type === "percent") billState.tip.percent = clean; else billState.tip.amount = clean;
  recomputeBill_();
});
document.querySelectorAll("#bill-tip-type-tabs .type-tab").forEach((t) => t.addEventListener("click", () => {
  billState.tip.type = t.dataset.v; syncBillTabs_(); recomputeBill_();
}));
document.querySelectorAll("#bill-tip-mode-tabs .type-tab").forEach((t) => t.addEventListener("click", () => {
  billState.tip.mode = t.dataset.v; syncBillTabs_(); recomputeBill_();
}));


// ---- Reading a receipt photo (step 3) ----
// All on the phone: the photo is shrunk and cleaned up on a canvas, read by
// self-hosted tesseract.js (docs/vendor/tesseract/), and the text goes through
// ReceiptParse (receipt-parse.js). Nothing is uploaded and the photo is not
// kept. The result only FILLS the sheet — items still have to be assigned to
// people, and the sheet's own total check catches a misread line.
let tesseractLoading_ = null;

function loadTesseract_() {
  if (window.Tesseract) return Promise.resolve();
  if (!tesseractLoading_) {
    tesseractLoading_ = new Promise((resolve, reject) => {
      const el = document.createElement("script");
      el.src = siteUrl_("vendor/tesseract/tesseract.min.js");
      el.onload = resolve;
      el.onerror = () => { tesseractLoading_ = null; reject(new Error(tr("photo.loadFailed"))); };
      document.head.appendChild(el);
    });
  }
  return tesseractLoading_;
}

// Finds the paper in the photo (the big bright region) so the table, hand or
// background around it never reaches the reader. Returns the whole photo when
// no clear paper stands out.
async function receiptPaperBox_(bmp) {
  const sw = 200, sh = Math.max(1, Math.round(bmp.height * sw / bmp.width));
  const c = document.createElement("canvas");
  c.width = sw;
  c.height = sh;
  const x = c.getContext("2d", { willReadFrequently: true });
  x.drawImage(bmp, 0, 0, sw, sh);
  const d = x.getImageData(0, 0, sw, sh).data;
  const g = new Uint8Array(sw * sh);
  const hist = new Array(256).fill(0);
  for (let i = 0, p = 0; i < d.length; i += 4, p++) { g[p] = Math.round(0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]); hist[g[p]]++; }
  let sum = 0;
  for (let i = 0; i < 256; i++) sum += i * hist[i];
  let sB = 0, wB = 0, best = 0, thr = 128;
  const tot = sw * sh;
  for (let t = 0; t < 256; t++) {            // Otsu: the brightness that best splits paper from background
    wB += hist[t];
    if (!wB) continue;
    const wF = tot - wB;
    if (!wF) break;
    sB += t * hist[t];
    const mB = sB / wB, mF = (sum - sB) / wF, v = wB * wF * (mB - mF) * (mB - mF);
    if (v > best) { best = v; thr = t; }
  }
  const col = new Array(sw).fill(0), row = new Array(sh).fill(0);
  for (let y = 0; y < sh; y++) for (let xx = 0; xx < sw; xx++) if (g[y * sw + xx] > thr) { col[xx]++; row[y]++; }
  const cm = Math.max(...col), rm = Math.max(...row);
  const cx = col.map((v, i) => (v > cm * 0.3 ? i : -1)).filter((i) => i >= 0);
  const ry = row.map((v, i) => (v > rm * 0.3 ? i : -1)).filter((i) => i >= 0);
  const whole = { x: 0, y: 0, w: bmp.width, h: bmp.height };
  if (!cx.length || !ry.length) return whole;
  const pad = 0.015;
  const x0 = Math.max(0, cx[0] / sw - pad), x1 = Math.min(1, (cx[cx.length - 1] + 1) / sw + pad);
  const y0 = Math.max(0, ry[0] / sh - pad), y1 = Math.min(1, (ry[ry.length - 1] + 1) / sh + pad);
  const box = { x: Math.round(x0 * bmp.width), y: Math.round(y0 * bmp.height), w: Math.round((x1 - x0) * bmp.width), h: Math.round((y1 - y0) * bmp.height) };
  return box.w > 0.92 * bmp.width && box.h > 0.92 * bmp.height ? whole : box;
}

// Greyscale + contrast stretch, optionally cropped to the paper. Tried on 16 real
// photos: cropping read more receipts than not cropping, but not the SAME ones —
// so the reader tries the crop first and the whole photo second (see readBillPhoto_).
async function prepareReceiptImage_(file, opts) {
  opts = opts || { crop: false, maxLong: 2000 };
  const bmp = await createImageBitmap(file);   // applies the photo's rotation
  const box = opts.crop ? await receiptPaperBox_(bmp) : { x: 0, y: 0, w: bmp.width, h: bmp.height };
  const scale = Math.min(opts.crop ? Math.min(1500 / box.w, 3200 / box.h) : (opts.maxLong || 2000) / Math.max(box.w, box.h), 3);
  const w = Math.max(1, Math.round(box.w * scale));
  const h = Math.max(1, Math.round(box.h * scale));
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, w, h);
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(bmp, box.x, box.y, box.w, box.h, 0, 0, w, h);
  if (bmp.close) bmp.close();
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  const hist = new Uint32Array(256);
  for (let i = 0; i < d.length; i += 4) {
    const g = Math.round(0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]);
    d[i] = d[i + 1] = d[i + 2] = g;
    hist[g]++;
  }
  // stretch between the 2nd and 98th percentile
  const total = w * h;
  let lo = 0, hi = 255, acc = 0;
  for (let v = 0; v < 256; v++) { acc += hist[v]; if (acc >= total * 0.02) { lo = v; break; } }
  acc = 0;
  for (let v = 255; v >= 0; v--) { acc += hist[v]; if (acc >= total * 0.02) { hi = v; break; } }
  const span = Math.max(1, hi - lo);
  for (let i = 0; i < d.length; i += 4) {
    const g = Math.max(0, Math.min(255, Math.round(((d[i] - lo) * 255) / span)));
    d[i] = d[i + 1] = d[i + 2] = g;
  }
  ctx.putImageData(img, 0, 0);
  return canvas;
}

// --- two reads, then a merge -------------------------------------------------
// Pass 1 reads the whole receipt. Pass 2 re-reads ONLY the number columns
// (cropped, so no table or margin noise around them) — that is where thermal
// printers' dotted zeros get misread as 8 or 9. For every number the more
// confident of the two readings is kept. Words the reader itself is unsure
// about AND that are 1-3 characters long (the "A A e" junk picked up from the
// table at the edge) are dropped.
const RECEIPT_NUM_WORD = /^[-\dOolI.,]*\d[-\dOolI.,]*$/;
const RECEIPT_AMOUNT_WORD = /^\d{1,6}[.,]\d{2,3}$/;

function receiptLines_(data) {
  return ((data && data.blocks) || [])
    .flatMap((b) => b.paragraphs.flatMap((p) => p.lines))
    .map((l) => ({
      y0: l.bbox.y0, y1: l.bbox.y1,
      words: (l.words || []).map((w) => ({ text: w.text, conf: w.confidence, x0: w.bbox.x0, x1: w.bbox.x1 }))
        .filter((w) => w.text && w.text.trim())
    }));
}

function receiptJunkWord_(w) {
  const letters = w.text.replace(/[^A-Za-zÁÉÍÓÚÑáéíóúñü0-9]/g, "");
  if (!letters) return true;                                   // "—", "*", ":" on their own
  if (RECEIPT_NUM_WORD.test(w.text)) return false;             // numbers are never junk here
  return letters.length <= 3 && w.conf < 45;
}

function receiptLineText_(words, height) {
  let out = "";
  words.forEach((w, i) => {
    if (i) out += w.x0 - words[i - 1].x1 > height * 1.5 ? "   " : " ";
    out += w.text;
  });
  return out;
}

function trailingNumberRun_(words) {
  let n = 0;
  while (n < words.length && RECEIPT_NUM_WORD.test(words[words.length - 1 - n].text)) n++;
  return n;
}

function mergeReceiptPasses_(lines1, lines2) {
  return lines1.map((l1) => {
    const h1 = Math.max(1, l1.y1 - l1.y0);
    let best = null, bestOverlap = 0;
    lines2.forEach((l2) => {
      const overlap = Math.min(l1.y1, l2.y1) - Math.max(l1.y0, l2.y0);
      const ratio = overlap / Math.max(1, Math.min(h1, l2.y1 - l2.y0));
      if (ratio > bestOverlap) { bestOverlap = ratio; best = l2; }
    });
    let words = l1.words.slice();
    if (best && bestOverlap >= 0.5) {
      const n1 = trailingNumberRun_(words), n2 = trailingNumberRun_(best.words);
      const k = Math.min(n1, n2, 3);
      if (k >= 1) {
        const left = words.slice(0, words.length - k);
        const mine = words.slice(words.length - k);
        const theirs = best.words.slice(best.words.length - k);
        // the more confident reading of each number (ties go to the digits-only pass)
        const chosen = mine.map((w, i) => (theirs[i].conf >= w.conf ? theirs[i] : w));
        words = left.concat(chosen);
      }
    }
    return receiptLineText_(words.filter((w) => !receiptJunkWord_(w)), h1);
  }).join("\n");
}

async function recognizeReceiptText_(canvas, onProgress) {
  await loadTesseract_();
  const base = siteUrl_("vendor/tesseract/");
  const worker = await Tesseract.createWorker("spa", 1, {
    workerPath: base + "worker.min.js",
    corePath: base,
    langPath: base,
    logger: (m) => { if (m && m.status && onProgress) onProgress(m); }
  });
  try {
    await worker.setParameters({ tessedit_pageseg_mode: "6", preserve_interword_spaces: "1" });
    const first = await worker.recognize(canvas, {}, { blocks: true, text: true });
    const lines1 = receiptLines_(first.data);
    if (!lines1.length) return first.data.text || "";
    try {
      // Where do the amounts start? (a little left of the leftmost amount column,
      // to take in a quantity column)
      const xs = lines1.flatMap((l) => l.words).filter((w) => RECEIPT_AMOUNT_WORD.test(w.text)).map((w) => w.x0).sort((a, b) => a - b);
      if (xs.length >= 4) {
        const startX = Math.max(0, Math.round(xs[Math.floor(xs.length * 0.15)] - canvas.width * 0.075));
        const strip = document.createElement("canvas");
        strip.width = canvas.width - startX;
        strip.height = canvas.height;
        strip.getContext("2d").drawImage(canvas, startX, 0, strip.width, strip.height, 0, 0, strip.width, strip.height);
        const second = await worker.recognize(strip, {}, { blocks: true });
        return mergeReceiptPasses_(lines1, receiptLines_(second.data));
      }
    } catch (err) {
      /* the second read is only an improvement — fall back to the first */
    }
    return mergeReceiptPasses_(lines1, []);
  } finally {
    await worker.terminate();
  }
}

// Puts what was read into the open sheet (replacing what was there only after
// asking, if the sheet already has items).
function applyReceiptToBill_(parsed, opts) {
  opts = opts || {};
  if (!opts.noConfirm && billState.items.some((it) => it.price) && !confirm(tr("photo.confirmReplace"))) return false;
  // Lines that are unchanged keep who shared them (matched by name + price).
  const previous = billState.items.slice();
  const keepPeople = (it) => {
    if (!opts.keepAssignments || it.discount) return new Set();
    const at = previous.findIndex((o) => !o.discount && o.name.trim().toLowerCase() === it.name.trim().toLowerCase() && o.price === it.price);
    if (at < 0) return new Set();
    return new Set(previous.splice(at, 1)[0].people);
  };
  billState.items = parsed.items.map((it) => ({ id: billNextId++, name: it.name, price: it.price, people: keepPeople(it), discount: it.discount }));
  billItemsEdited = false;
  billState.adjs = [
    ...parsed.charges.map((c) => ({ id: billNextId++, kind: "charge", name: c.name, amount: c.amount, mode: "proportional" })),
    ...parsed.discounts.map((d) => ({ id: billNextId++, kind: "discount", name: d.name, amount: d.amount, mode: "proportional" }))
  ];
  if (parsed.total) {
    billState.total = parsed.total;
    document.getElementById("bill-total").value = parsed.total;
  }
  renderBillItems_();
  renderBillAdjs_();
  recomputeBill_();
  return true;
}

function billPhotoSay_(text, bad) {
  const status = document.getElementById("bill-photo-status");
  status.hidden = false;
  status.textContent = text;
  status.className = "hint" + (bad ? " bill-check-bad" : "");
}

// Reads a receipt photo: tries it cropped to the paper first and, if the result
// doesn't add up to its own printed total, the whole photo second (they fail on
// different receipts); returns the better reading {text, parsed, reconciled}.
async function readReceiptFile_(file, say) {
  say = say || (() => {});
  const attempts = [{ crop: true }, { crop: false, maxLong: 2000 }];
  let best = null;
  for (let i = 0; i < attempts.length; i++) {
    const canvas = await prepareReceiptImage_(file, attempts[i]);
    const first = !window.Tesseract;
    say(i ? tr("photo.retry") : first ? tr("photo.loadingReader") : tr("photo.reading"));
    const text = await recognizeReceiptText_(canvas, (m) => {
      if (m.status === "recognizing text") say(tr(i ? "photo.readingAgainPct" : "photo.readingPct", { pct: Math.round((m.progress || 0) * 100) }));
      else if (/loading/i.test(m.status)) say(tr("photo.loadingReader"));
    });
    const parsed = ReceiptParse.parseReceipt(text);
    const f = ReceiptParse.fit(parsed);
    // better = adds up > closer to the total > more items
    const score = (f.reconciled ? 1e9 : 0) - (f.known ? f.gap : 1e7) + parsed.items.length * 0.01;
    if (!best || score > best.score) best = { text, parsed, score, reconciled: f.reconciled, attempt: i };
    if (best.reconciled) break;
  }
  return best;
}

async function readBillPhoto_(file) {
  const btn = document.getElementById("bill-photo-btn");
  const say = billPhotoSay_;
  btn.disabled = true;
  try {
    say(tr("photo.preparing"));
    const best = await readReceiptFile_(file, say);
    document.getElementById("bill-photo-text").value = best.text;
    document.getElementById("bill-photo-raw").hidden = false;
    const parsed = best.parsed;
    if (!parsed.items.length) {
      say(tr("photo.noItems"), true);
      return;
    }
    if (!applyReceiptToBill_(parsed)) { say(tr("photo.leftAsWas")); return; }
    const dishes = parsed.items.filter((i) => !i.discount).length;
    const notes = parsed.warnings.length ? " " + parsed.warnings.join(" ") : "";
    say(tr("photo.readN", { n: dishes, notes }), parsed.warnings.length > 0);
  } catch (err) {
    say(err.message || tr("photo.couldntRead"), true);
  } finally {
    btn.disabled = false;
  }
}

// ---- 🕒 Payments in process (More → Accounts): adds up what a bank app's movements list still shows as "En proceso" ----
// Screenshots are read on the phone (same reader as receipts); nothing is saved or sent. See specs/accounts.md § Payments in process.
let inprocLists_ = [];       // one list of items per screenshot read
let inprocItems_ = [];       // merged, each with .on (ticked)
let inprocRaw_ = "";         // what the reader saw, shown under "What the phone read"
let inprocDebt_ = false;     // opened for a credit card: the box takes the card's total DEBT and the payments are added to it
let inprocPosted_ = 0;       // rows of the screenshots that were NOT marked in process

function inprocSay_(text, bad) {
  const status = document.getElementById("inproc-status");
  status.hidden = !text;
  status.textContent = text || "";
  status.className = "hint" + (bad ? " bill-check-bad" : "");
}

function renderInproc_() {
  const list = document.getElementById("inproc-list");
  list.innerHTML = "";
  inprocItems_.forEach((it, i) => {
    const row = document.createElement("label");
    row.className = "inproc-row";
    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = it.on;
    box.addEventListener("change", () => { it.on = box.checked; renderInproc_(); });
    const what = document.createElement("span");
    what.className = "inproc-what";
    const name = document.createElement("div");
    name.textContent = it.name || "—";
    const when = document.createElement("div");
    when.className = "inproc-when";
    when.textContent = it.when;
    what.append(name, when);
    const amount = document.createElement("span");
    amount.textContent = formatAmount(Math.abs(it.amount), it.currency, it.amount < 0 ? "−" : "+");
    row.append(box, what, amount);
    list.appendChild(row);
  });
  const sums = InProcess.sumsByCurrency(inprocItems_.filter((it) => it.on));
  const totals = document.getElementById("inproc-totals");
  totals.innerHTML = "";
  const curs = Object.keys(sums);
  curs.forEach((cur) => {
    const row = document.createElement("div");
    row.className = "inproc-total";
    const a = document.createElement("span");
    a.textContent = tr("inproc.total", { cur });
    const b = document.createElement("span");
    b.textContent = formatAmount(Math.abs(sums[cur]) / 100, cur, sums[cur] < 0 ? "−" : "+");
    row.append(a, b);
    totals.appendChild(row);
  });
  const box = document.getElementById("inproc-balance-box");
  box.hidden = !curs.length;
  if (curs.length) {
    document.getElementById("inproc-balance-cur").textContent = curs.length === 1 ? curs[0] : curs.join(" / ");
    updateInprocAfter_(sums);
  }
}

// The number typed in the box, as the account's balance: signed like a starting balance (the "Negative" box or a typed minus make it negative).
function inprocTypedBalance_() {
  const raw = document.getElementById("inproc-balance").value.replace(/,/g, "").replace(/[−–]/g, "-").trim();
  const x = Number(raw);
  if (!raw || !isFinite(x)) return null;
  return document.getElementById("inproc-negative").checked || x < 0 ? -Math.abs(x) : Math.abs(x);
}

// Balance in the bank app + the in-process total (negative for money out) = what is really left. Only for a single currency.
function updateInprocAfter_(sums) {
  sums = sums || InProcess.sumsByCurrency(inprocItems_.filter((it) => it.on));
  const after = document.getElementById("inproc-after");
  const curs = Object.keys(sums);
  const typed = inprocTypedBalance_();
  // A card is shown as a debt (the opposite sign of its balance).
  const bal = typed === null ? 0 : (inprocDebt_ ? -typed : typed);
  if (typed === null || curs.length !== 1) { after.textContent = curs.length > 1 ? tr("inproc.afterNote") : ""; return; }
  const cur = curs[0];
  // An account: balance minus what is in process. A card: debt plus what is in process (money out raises the debt).
  const left = inprocDebt_ ? Math.round(bal * 100) - sums[cur] : Math.round(bal * 100) + sums[cur];
  // The whole sum is shown, so it is clear which number is which: what the bank app shows, minus what is in process, = what is left.
  after.textContent = tr(inprocDebt_ ? "inproc.debtAfter" : "inproc.after", {
    balance: formatAmount(Math.abs(bal), cur, bal < 0 ? "−" : ""),
    process: formatAmount(Math.abs(sums[cur]) / 100, cur),
    left: formatAmount(Math.abs(left) / 100, cur, left < 0 ? "−" : "")
  });
}

async function readInprocFiles_(files) {
  const btn = document.getElementById("inproc-pick");
  btn.disabled = true;
  let failed = "";
  try {
    for (let i = 0; i < files.length; i++) {
      inprocSay_(tr("inproc.reading", { i: i + 1, n: files.length }));
      // Two readings at different image sizes: a phone sometimes drops a row at one size that the other keeps.
      const reads = [];
      for (const size of [2400, 1600]) {
        try {
          const canvas = await prepareReceiptImage_(files[i], { crop: false, maxLong: size });
          const text = await recognizeReceiptText_(canvas, () => {});
          const parsed = InProcess.parseInProcess(text);
          reads.push(parsed.items);
          inprocPosted_ = Math.max(inprocPosted_, parsed.posted);
          inprocRaw_ += (inprocRaw_ ? "\n\n" : "") + "— " + (i + 1) + " / " + size + " —\n" + text;
        } catch (err) {
          failed = err.message || tr("photo.couldntRead");
        }
      }
      if (reads.length) { failed = ""; inprocLists_.push(InProcess.mergeReads(reads)); }
    }
    // A row keeps its tick when the list is rebuilt. Identical rows are told apart by their order among their twins ("#1", "#2"),
    // so unticking one of two identical payments does not tick or untick the other.
    const tickKeys = (items) => {
      const seen = {};
      return items.map((it) => {
        const base = [it.name, it.when, it.amount, it.currency].join("|");
        seen[base] = (seen[base] || 0) + 1;
        return base + "#" + seen[base];
      });
    };
    const oldKeys = tickKeys(inprocItems_);
    const ticked = new Map(inprocItems_.map((it, i) => [oldKeys[i], it.on]));
    const merged = InProcess.mergeItems(inprocLists_);
    const newKeys = tickKeys(merged);
    inprocItems_ = merged.map((it, i) => Object.assign({}, it, { on: ticked.has(newKeys[i]) ? ticked.get(newKeys[i]) : true }));
    renderInproc_();
    document.getElementById("inproc-raw-text").value = inprocRaw_;
    document.getElementById("inproc-raw").hidden = !inprocRaw_;
    if (failed) inprocSay_(failed, true);
    else if (!inprocItems_.length) inprocSay_(tr("inproc.none"), true);
    else inprocSay_(tr("inproc.found", { n: inprocItems_.length }) + (inprocPosted_ ? tr("inproc.skipped", { n: inprocPosted_ }) : ""));
  } finally {
    btn.disabled = false;
  }
}

function openInprocModal_() {
  inprocLists_ = [];
  inprocItems_ = [];
  inprocRaw_ = "";
  inprocPosted_ = 0;
  document.getElementById("inproc-raw").hidden = true;
  // Which account is the balance sheet behind this one showing? A credit card is thought of as a debt, not a balance.
  const pmId = typeof balanceModalPmId !== "undefined" && (balanceModalPmId || (document.getElementById("balance-account-picker") || {}).value);
  const pm = pmId && (meta.paymentMethods || []).find((p) => p.id === pmId);
  inprocDebt_ = !!pm && pm.type === "credit";
  const labelSpan = document.querySelector("#inproc-balance-box label span");
  labelSpan.dataset.i18n = inprocDebt_ ? "inproc.debt" : "inproc.balance";
  labelSpan.textContent = tr(labelSpan.dataset.i18n);
  const hintP = document.querySelector("#inproc-balance-box .hint[data-i18n]");
  hintP.dataset.i18n = inprocDebt_ ? "inproc.debtHint" : "inproc.balanceHint";
  hintP.textContent = tr(hintP.dataset.i18n);
  // Opened from an account's balance sheet: start from the balance the person already typed in "Check against my app".
  // A card's balance is what is owed, so its "Negative" box starts ticked (same as the balance sheet's new rows).
  const prefill = (document.getElementById("balance-check-input").value || "").replace(/[−–]/g, "-").trim();
  document.getElementById("inproc-balance").value = prefill.replace(/^-/, "");
  document.getElementById("inproc-negative").checked = prefill.startsWith("-") || inprocDebt_;
  inprocSay_("");
  renderInproc_();
  document.getElementById("inproc-modal-backdrop").hidden = false;
}
function closeInprocModal_() {
  document.getElementById("inproc-modal-backdrop").hidden = true;
  inprocLists_ = [];
  inprocItems_ = [];
}
document.getElementById("inproc-open-btn").addEventListener("click", openInprocModal_);
document.getElementById("inproc-modal-close").addEventListener("click", closeInprocModal_);
document.getElementById("inproc-close").addEventListener("click", closeInprocModal_);
document.getElementById("inproc-modal-backdrop").addEventListener("click", (e) => { if (e.target.id === "inproc-modal-backdrop") closeInprocModal_(); });
document.getElementById("inproc-pick").addEventListener("click", () => document.getElementById("inproc-input").click());
document.getElementById("inproc-input").addEventListener("change", (e) => {
  const files = Array.from(e.target.files || []);
  e.target.value = "";
  if (files.length) readInprocFiles_(files);
});
document.getElementById("inproc-balance").addEventListener("input", () => updateInprocAfter_());
document.getElementById("inproc-negative").addEventListener("change", () => updateInprocAfter_());

// Puts the new balance (the number typed, or the balance this app shows now, plus the in-process total) into the balance sheet behind this one.
// Nothing is saved here: the person reviews the row and presses Save in the balance sheet.
document.getElementById("inproc-apply").addEventListener("click", () => {
  const sums = InProcess.sumsByCurrency(inprocItems_.filter((it) => it.on));
  const curs = Object.keys(sums);
  if (!curs.length) { inprocSay_(tr("inproc.applyNothing"), true); return; }
  const pmId = balanceFormPmId_;
  const tracked = pmId && balancesCache.find((b) => b.id === pmId);
  const typed = curs.length === 1 ? inprocTypedBalance_() : null;
  const newCents = {};
  for (const cur of curs) {
    let base = typed;
    if (base === null) {
      const have = tracked && tracked.balances.find((b) => b.currency === cur);
      if (!have) { inprocSay_(tr("inproc.applyNeedNumber", { cur }), true); return; }
      base = have.amount;
    }
    newCents[cur] = Math.round(base * 100) + sums[cur];
  }
  curs.forEach((cur) => {
    let row = balanceFormRows.find((r) => r.currency === cur);
    if (!row) row = balanceFormRows.find((r) => !String(r.amount).trim());
    if (!row) { row = { amount: "", negative: false, currency: cur, date: todayLocalISO() }; balanceFormRows.push(row); }
    row.currency = cur;
    row.amount = (Math.abs(newCents[cur]) / 100).toFixed(2);
    row.negative = newCents[cur] < 0;
    row.date = todayLocalISO();
  });
  renderBalanceRows_();
  closeInprocModal_();
  showToast_(tr("inproc.applied"));
});

document.getElementById("bill-photo-again").addEventListener("click", () => { if (receiptFormFile_) readBillPhoto_(receiptFormFile_); });
document.getElementById("bill-photo-btn").addEventListener("click", () => document.getElementById("bill-photo-input").click());
document.getElementById("bill-photo-reparse").addEventListener("click", () => {
  const parsed = ReceiptParse.parseReceipt(document.getElementById("bill-photo-text").value);
  if (!parsed.items.length) { billPhotoSay_(tr("photo.textNoItems"), true); return; }
  if (billItemsEdited && !confirm(tr("photo.confirmOverwrite"))) return;
  applyReceiptToBill_(parsed, { noConfirm: true, keepAssignments: true });
  const dishes = parsed.items.filter((i) => !i.discount).length;
  billPhotoSay_(tr("photo.reworked", { n: dishes }) + (parsed.warnings.length ? " " + parsed.warnings.join(" ") : ""), parsed.warnings.length > 0);
});
document.getElementById("bill-photo-input").addEventListener("change", (e) => {
  const file = e.target.files && e.target.files[0];
  e.target.value = "";           // picking the same photo again must work
  if (file) readBillPhoto_(file);
});


// ---- "📷 Read a receipt or payment" in the entry form (Business pack, step 3B) ----
// The same on-phone reader as the bill splitter (photo shrunk, read by self-hosted tesseract.js, nothing uploaded or kept); the text
// goes through ReceiptFields (receipt-fields.js). An expense gets amount, date, business name and the IGV when it is printed; an
// income gets amount, date, who paid and the invoice number (which also picks the matching expected payment). It only FILLS the
// form — the person always checks it and taps Save.

function syncReceiptField_() {
  const field = document.getElementById("receipt-read-field");
  if (field) field.hidden = !(businessOn() && (selectedType === "expense" || selectedType === "income"));
}

function receiptReadSay_(text, bad) {
  const status = document.getElementById("receipt-read-status");
  status.hidden = false;
  status.textContent = text;
  status.className = "hint" + (bad ? " bill-check-bad" : "");
}

// Tries the photo cropped to the paper first and the whole photo second (they fail on different pictures), as the bill reader does;
// stops at the first reading that found both an amount and a date.
async function readReceiptFields_(file, say) {
  const attempts = [{ crop: true }, { crop: false, maxLong: 2000 }];
  let best = null;
  for (let i = 0; i < attempts.length; i++) {
    const canvas = await prepareReceiptImage_(file, attempts[i]);
    say(i ? tr("photo.retry") : !window.Tesseract ? tr("photo.loadingReader") : tr("photo.reading"));
    const text = await recognizeReceiptText_(canvas, (m) => {
      if (m.status === "recognizing text") say(tr(i ? "photo.readingAgainPct" : "photo.readingPct", { pct: Math.round((m.progress || 0) * 100) }));
      else if (/loading/i.test(m.status)) say(tr("photo.loadingReader"));
    });
    const fields = ReceiptFields.parse(text, { today: todayLocalISO() });
    const score = (fields.amount ? 4 : 0) + (fields.date ? 2 : 0) + (fields.name || fields.payer ? 1 : 0) + (fields.igv ? 1 : 0);
    if (!best || score > best.score) best = { text, fields, score };
    if (fields.amount && fields.date) break;
  }
  return best;
}

const receiptInvoiceKey_ = (s) => String(s || "").toUpperCase().replace(/[^A-Z0-9]/g, "").replace(/^([FBE][A-Z0-9]{3})0+(\d)/, "$1$2");

// Puts what was read into the open form; returns the names of what it filled in (for the message).
function applyReceiptFields_(f) {
  const found = [];
  let igvFromExpected = false;
  let payerNote = "";
  const isIncome = selectedType === "income";
  if (f.currency && f.currency !== document.getElementById("currency").value && CURRENCIES.some((c) => c.code === f.currency)) selectCurrency(f.currency, "entry");

  // An income whose invoice number is on one of the expected payments: pick that project and that expected payment.
  if (isIncome && f.invoice) {
    const cur = document.getElementById("currency").value;
    const x = (meta.expectedPayments || []).find((e) => e.status !== "covered" && receiptInvoiceKey_(e.invoice_no) === receiptInvoiceKey_(f.invoice) && e.currency === cur);
    if (x) {
      if (!businessProjectOfPick_()) setBusinessPick_("p:" + x.project_id);
      if (businessProjectOfPick_() && businessProjectOfPick_().id === x.project_id) {
        setExpectedPick_(x.id);
        found.push("receipt.f.invoice");
        if (x.igv_included && !f.igv) igvFromExpected = true;   // that invoice includes IGV: work it out from the amount below
      }
    }
  }
  if (f.amount) {
    const el = document.getElementById("amount");
    el.value = f.amount;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    found.push("receipt.f.amount");
  }
  if (f.date) {
    document.getElementById("date").value = f.date;
    entryDateTouched_ = true;
    found.push("receipt.f.date");
  }
  const description = document.getElementById("description");
  if (isIncome) {
    const payer = f.payer ? f.payer.toLowerCase().replace(/\*+$/, "").trim() : "";
    const payorId = payer ? (meta.payors || []).find((p) => { const n = p.name.toLowerCase(); return n === payer || n.includes(payer) || payer.includes(n); }) : null;
    if (payorId) { document.getElementById("paid_by").value = payorId.id; found.push("receipt.f.payer"); }
    else if (f.payer) payerNote = " " + tr("receipt.payerUnknown", { payer: f.payer });   // read, but not in the person's list: they pick or add them
    if (!description.value.trim()) {
      const text = f.invoice ? tr("xp.incomeDescInvoice", { invoice: f.invoice }) : (f.payer ? tr("xp.incomeDescClient", { client: f.payer }) : "");
      if (text) description.value = text;
    }
  } else if (f.name) {
    if (!description.value.trim()) description.value = f.name;
    found.push("receipt.f.business");   // read (a description the person already typed is never overwritten)
  }
  // The IGV only when the form can record it (a company that charges IGV is picked); otherwise the message says what was printed.
  let igvNote = "";
  if (f.igv) {
    if (!document.getElementById("igv-field").hidden || (businessCompanyOfPick_() && businessCompanyOfPick_().igv_enabled === "yes")) {
      setIgvState_(true, f.igv, true);
      found.push("receipt.f.igv");
    } else {
      igvNote = " " + tr("receipt.igvNoCompany", { cur: document.getElementById("currency").value, igv: moneyFmt(Number(f.igv)) });
    }
  }
  if (igvFromExpected && !found.includes("receipt.f.igv") && !document.getElementById("igv-field").hidden) {
    setIgvState_(true, "", false);
    found.push("receipt.f.igv");
  }
  scheduleEntryDraftSave_();
  return { found, igvNote: igvNote + payerNote };
}

async function readReceiptPhoto_(file) {
  const btn = document.getElementById("receipt-read-btn");
  btn.disabled = true;
  try {
    receiptReadSay_(tr("photo.preparing"));
    const best = await readReceiptFields_(file, receiptReadSay_);
    document.getElementById("receipt-read-text").value = best.text;
    document.getElementById("receipt-read-raw").hidden = false;
    if (!best.score) { receiptReadSay_(tr("receipt.nothing"), true); return; }
    const { found, igvNote } = applyReceiptFields_(best.fields);
    receiptFormFile_ = file;
    receiptFormText_ = best.text;   // after filling the form: filling may reset the split state
    // "Couldn't find" means the reader found nothing for it (a payer that was read but is not in the person's list has its own note).
    const f = best.fields;
    const wanted = selectedType === "income"
      ? [["receipt.f.amount", f.amount], ["receipt.f.date", f.date], ["receipt.f.payer", f.payer]]
      : [["receipt.f.amount", f.amount], ["receipt.f.date", f.date], ["receipt.f.business", f.name]];
    const missing = wanted.filter(([, value]) => !value).map(([key]) => key);
    receiptReadSay_(tr("receipt.done", { found: found.map((k) => tr(k)).join(", ") || "—" })
      + (missing.length ? " " + tr("receipt.missing", { missing: missing.map((k) => tr(k)).join(", ") }) : "") + igvNote, missing.length > 0);
  } catch (err) {
    receiptReadSay_(err.message || tr("photo.couldntRead"), true);
  } finally {
    btn.disabled = false;
  }
}

document.getElementById("receipt-read-btn").addEventListener("click", () => document.getElementById("receipt-read-input").click());
document.getElementById("receipt-read-input").addEventListener("change", (e) => {
  const file = e.target.files && e.target.files[0];
  e.target.value = "";           // picking the same photo again must work
  if (file) readReceiptPhoto_(file);
});

// ---- One calendar for a start AND an end date (2026-10-19) ----
// Wherever the app asks for "from … to …" (a trip's dates, a Programmed item's start/end, Overview's custom
// period, Export's custom range) a single field shows the whole range and opens ONE calendar pop-up: tap the
// first day, then the last. The two real <input type="date"> elements stay in the page, hidden, as the
// values every existing handler already reads and writes — so nothing that uses them had to change.
// See specs/trips-events.md § Dates in one calendar.

// What a tap on a day does (pure, so it is tested on its own):
//  - nothing chosen yet, or a finished range → that day starts a new range (no end);
//  - a start but no end: a day BEFORE the start becomes the new start; the same day or later is the end
//    (the same day twice = a one-day range).
function rangeTap_(state, iso) {
  const start = state.start || "", end = state.end || "";
  if (!start || end) return { start: iso, end: "" };
  if (iso < start) return { start: iso, end: "" };
  return { start, end: iso };
}

function rangeFmt_(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return I18n.fmtDateMedium(new Date(y, m - 1, d));   // built from parts: new Date("YYYY-MM-DD") is UTC and can land a day early
}

// The text on the field. noEnd: "single" = a missing end date means one day (trips); "open" = no end date.
function rangeSummary_(noEnd, start, end) {
  if (!start && !end) return "";
  if (!start) return tr("range.until", { end: rangeFmt_(end) });
  if (!end) return noEnd === "single" ? rangeFmt_(start) : tr("range.fromOpen", { start: rangeFmt_(start) });
  if (end === start && noEnd === "single") return rangeFmt_(start);
  return tr("range.span", { start: rangeFmt_(start), end: rangeFmt_(end) });
}

const RANGE_WEEKDAY_KEYS_ = ["range.wd1", "range.wd2", "range.wd3", "range.wd4", "range.wd5", "range.wd6", "range.wd7"];   // Monday first
let rangeDom_ = null;
let rangeSession_ = null;   // { cfg, startEl, endEl, state, viewY, viewM }

function ensureRangeDom_() {
  if (rangeDom_) return rangeDom_;
  const backdrop = document.createElement("div");
  backdrop.id = "range-picker-backdrop";
  backdrop.className = "currency-modal-backdrop";
  backdrop.hidden = true;
  backdrop.innerHTML = `
    <div class="currency-modal range-modal">
      <div class="currency-modal-header">
        <span id="range-title"></span>
        <button type="button" id="range-close" class="currency-modal-close">✕</button>
      </div>
      <div class="range-nav">
        <button type="button" data-step="-12" aria-label="−12">«</button>
        <button type="button" data-step="-1" aria-label="−1">‹</button>
        <span id="range-month"></span>
        <button type="button" data-step="1" aria-label="+1">›</button>
        <button type="button" data-step="12" aria-label="+12">»</button>
      </div>
      <div class="range-weekdays">${RANGE_WEEKDAY_KEYS_.map((k) => `<span>${escapeHtml(tr(k))}</span>`).join("")}</div>
      <div class="range-grid" id="range-grid"></div>
      <p class="hint" id="range-hint" hidden></p>
      <p class="hint" id="range-summary"></p>
      <div class="range-actions">
        <button type="button" class="add-inline" id="range-remove-end">${escapeHtml(tr("range.removeEnd"))}</button>
        <button type="button" class="add-inline" id="range-clear">${escapeHtml(tr("range.clear"))}</button>
      </div>
      <button type="button" class="primary" id="range-done">${escapeHtml(tr("range.done"))}</button>
    </div>`;
  document.body.appendChild(backdrop);
  const dom = {
    backdrop, title: backdrop.querySelector("#range-title"), month: backdrop.querySelector("#range-month"),
    grid: backdrop.querySelector("#range-grid"), summary: backdrop.querySelector("#range-summary"), hint: backdrop.querySelector("#range-hint"),
    removeEnd: backdrop.querySelector("#range-remove-end"), clear: backdrop.querySelector("#range-clear"),
    done: backdrop.querySelector("#range-done")
  };
  const close = () => { backdrop.hidden = true; rangeSession_ = null; };
  backdrop.querySelector("#range-close").addEventListener("click", close);
  backdrop.addEventListener("click", (e) => { if (e.target === backdrop) close(); });
  backdrop.querySelectorAll("[data-step]").forEach((b) => b.addEventListener("click", () => {
    const s = rangeSession_;
    if (!s) return;
    const moved = new Date(s.viewY, s.viewM - 1 + Number(b.dataset.step), 1);
    s.viewY = moved.getFullYear();
    s.viewM = moved.getMonth() + 1;
    renderRange_();
  }));
  dom.removeEnd.addEventListener("click", () => { if (rangeSession_) { rangeSession_.state.end = ""; renderRange_(); } });
  dom.clear.addEventListener("click", () => { if (rangeSession_) { rangeSession_.state = { start: "", end: "" }; renderRange_(); } });
  dom.done.addEventListener("click", () => {
    const s = rangeSession_;
    if (!s) return;
    // An end-only pick (Programmed items → Stop it) hands the chosen end date to its caller instead of writing into the form.
    if (s.cfg.onDone) { const picked = { start: s.state.start, end: s.state.end }; close(); s.cfg.onDone(picked); return; }
    // Written to the real inputs, which then tell every existing listener ("change") as if typed.
    s.startEl.value = s.state.start;
    s.endEl.value = s.state.end;
    [s.startEl, s.endEl].forEach((el) => { el.dispatchEvent(new Event("input", { bubbles: true })); el.dispatchEvent(new Event("change", { bubbles: true })); });
    close();
  });
  rangeDom_ = dom;
  return dom;
}

function renderRange_() {
  const s = rangeSession_, dom = rangeDom_;
  if (!s || !dom) return;
  const { start, end } = s.state;
  dom.month.textContent = I18n.fmtMonthYear(new Date(s.viewY, s.viewM - 1, 1));
  dom.grid.innerHTML = "";
  const first = new Date(s.viewY, s.viewM - 1, 1);
  const lead = (first.getDay() + 6) % 7;                       // Monday = 0
  const days = new Date(s.viewY, s.viewM, 0).getDate();
  const today = todayLocalISO();
  for (let i = 0; i < lead; i++) dom.grid.appendChild(document.createElement("span"));
  for (let d = 1; d <= days; d++) {
    const iso = `${s.viewY}-${String(s.viewM).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = d;
    b.disabled = !!s.cfg.endOnly && !!start && iso < start;   // an end cannot come before the start
    b.className = "range-day"
      + (iso === start && !s.cfg.endOnly ? " is-start" : "") + (iso === end ? " is-end" : "")
      + (start && end && iso > start && iso < end ? " in-range" : "")
      + (iso === today ? " is-today" : "");
    b.addEventListener("click", () => { s.state = s.cfg.endOnly ? { start: s.state.start, end: iso } : rangeTap_(s.state, iso); renderRange_(); });
    dom.grid.appendChild(b);
  }
  const cfg = s.cfg;
  dom.summary.textContent = cfg.endOnly
    ? (end ? tr("range.until", { end: rangeFmt_(end) }) : tr("recDel.endPrompt"))
    : !start
    ? tr("range.promptStart")
    : !end
      ? tr(cfg.noEnd === "single" ? "range.promptEndSingle" : "range.promptEndOpen")
      : rangeSummary_(cfg.noEnd, start, end);
  // visibility, not `hidden`: the pop-up must keep its height, or the days jump under the finger between taps
  dom.removeEnd.style.visibility = end && !cfg.endOnly ? "visible" : "hidden";
  dom.clear.style.visibility = cfg.endOnly || cfg.startRequired || (!start && !end) ? "hidden" : "visible";
  dom.done.disabled = cfg.endOnly ? !end : (!!cfg.startRequired && !start);
}

function openDateRangePicker_(cfg, startEl, endEl) {
  const dom = ensureRangeDom_();
  const state = { start: startEl.value || "", end: endEl.value || "" };
  const anchor = cfg.anchor || state.start || state.end || todayLocalISO();
  rangeSession_ = { cfg, startEl, endEl, state, viewY: Number(anchor.slice(0, 4)), viewM: Number(anchor.slice(5, 7)) };
  dom.title.textContent = tr(cfg.titleKey);
  dom.done.textContent = tr(cfg.doneKey || "range.done");
  dom.hint.textContent = cfg.hint || "";
  dom.hint.hidden = !cfg.hint;
  bringModalToFront_(dom.backdrop);
  dom.backdrop.hidden = false;
  renderRange_();
}

// Replaces a pair of date inputs by one field. cfg: { startId, endId, titleKey, startRequired, noEnd }.
// The inputs stay (hidden) as the stored values; assigning `.value` from code refreshes the field too.
function attachDateRange_(cfg) {
  const startEl = document.getElementById(cfg.startId), endEl = document.getElementById(cfg.endId);
  const field = document.createElement("button");
  field.type = "button";
  field.className = "range-field";
  startEl.insertAdjacentElement("beforebegin", field);
  startEl.hidden = true;
  endEl.hidden = true;
  const refresh = () => {
    const text = rangeSummary_(cfg.noEnd, startEl.value, endEl.value);
    field.textContent = text || tr("range.choose");
    field.classList.toggle("empty", !text);
  };
  const nativeValue = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value");
  [startEl, endEl].forEach((el) => {
    Object.defineProperty(el, "value", {
      configurable: true,
      get() { return nativeValue.get.call(this); },
      set(v) { nativeValue.set.call(this, v); refresh(); }
    });
  });
  field.addEventListener("click", () => openDateRangePicker_(cfg, startEl, endEl));
  refresh();
}

attachDateRange_({ startId: "custom-start", endId: "custom-end", titleKey: "period.dates", startRequired: false, noEnd: "open" });
attachDateRange_({ startId: "export-start", endId: "export-end", titleKey: "period.dates", startRequired: false, noEnd: "open" });
attachDateRange_({ startId: "trip-start", endId: "trip-end", titleKey: "trips.dates", startRequired: true, noEnd: "single" });
attachDateRange_({ startId: "recurring-start-date", endId: "recurring-end-date", titleKey: "recModal.dates", startRequired: true, noEnd: "open" });

init();
